// 每日科普知识库 —— 考公常识高频考点 100 条
// 每条包含:field 领域、title 考点标题、body 讲解、fact 记忆点/易错点
// 配图由 app.js 按 field 自动匹配对应的 SVG 图标(6 大类),完全离线
// 为避免引号导致的语法错误,正文内一律使用「」而非直引号

const KNOWLEDGE = [
  // ========== 法律常识 (17) ==========
  { field: "法律", title: "我国现行宪法是 1982 年宪法", body: "新中国先后颁布过 1954、1975、1978、1982 四部宪法。现行宪法是 1982 年 12 月 4 日通过的「八二宪法」,此后经过 1988、1993、1999、2004、2018 共五次修正。宪法是国家根本大法,具有最高法律效力。", fact: "12 月 4 日是国家宪法日。现行宪法是第四部,不是第一部。" },
  { field: "法律", title: "《民法典》2021 年 1 月 1 日起施行", body: "《中华人民共和国民法典》被称为「社会生活的百科全书」,是新中国第一部以法典命名的法律,共七编 1260 条,包括总则、物权、合同、人格权、婚姻家庭、继承、侵权责任。施行后《婚姻法》《合同法》等九部法律同时废止。", fact: "民法典独立设「人格权编」,为世界首创。" },
  { field: "法律", title: "完全刑事责任年龄为 16 周岁", body: "已满 16 周岁犯罪应负刑事责任;已满 14 不满 16 周岁只对故意杀人、重伤、强奸、抢劫、贩毒、放火、爆炸、投放危险物质八类重罪负责。2021 年刑法修正案(十一)规定,已满 12 不满 14 周岁犯故意杀人、重伤致残情节恶劣的,经核准也可追责。", fact: "最低可追刑责年龄已下调至 12 周岁(特定情形)。" },
  { field: "法律", title: "民事行为能力按年龄划分", body: "不满 8 周岁为无民事行为能力人;8 周岁以上未成年人为限制民事行为能力人;18 周岁以上成年人为完全民事行为能力人。16 周岁以上以自己劳动收入为主要生活来源的,视为完全民事行为能力人。", fact: "无民事行为能力的分界线是 8 周岁,不是 10 周岁(民法典已下调)。" },
  { field: "法律", title: "法的效力层级:宪法最高", body: "我国法的效力层级由高到低为:宪法 > 法律 > 行政法规 > 地方性法规、规章。法律由全国人大及其常委会制定,行政法规由国务院制定,部门规章由国务院各部委制定,地方性法规由地方人大制定。", fact: "下位法不得与上位法相抵触,抵触者无效。" },
  { field: "法律", title: "行政处罚的种类", body: "《行政处罚法》规定的处罚包括:警告、通报批评;罚款、没收违法所得;暂扣或吊销许可证、降低资质等级;限制开展生产经营、责令停产停业；行政拘留等。其中行政拘留只能由公安机关决定。", fact: "行政拘留≠刑事拘留;前者是处罚,后者是刑事强制措施。" },
  { field: "法律", title: "刑罚分主刑和附加刑", body: "主刑包括:管制、拘役、有期徒刑、无期徒刑、死刑,只能单独适用。附加刑包括:罚金、剥夺政治权利、没收财产、驱逐出境,可以附加也可以独立适用。死刑缓期执行不是独立刑种。", fact: "罚金是刑罚(附加刑),罚款是行政处罚,二者不同。" },
  { field: "法律", title: "正当防卫与紧急避险", body: "正当防卫是对正在进行的不法侵害实施的反击,针对的是不法侵害人本人。紧急避险是为避免更大危险而损害另一较小合法权益,针对的是第三方。对严重危及人身安全的暴力犯罪防卫,造成不法侵害人伤亡的,不属防卫过当。", fact: "后者是「两害相权取其轻」,前者是「以正对不正」。" },
  { field: "法律", title: "我国的诉讼时效一般为三年", body: "《民法典》规定,向人民法院请求保护民事权利的普通诉讼时效期间为三年,自权利人知道或应当知道权利受损及义务人之日起计算。但从权利受损之日起超过二十年的,法院不予保护。", fact: "普通诉讼时效从两年改为三年(民法典变化点)。" },
  { field: "法律", title: "我国审判实行两审终审制", body: "一个案件经过两级法院审判即告终结。当事人不服一审判决,可在法定期限内向上一级法院上诉;二审判决即为终审判决,立即生效。但死刑案件还需经过最高人民法院核准。", fact: "死刑复核不是第三审,是特殊核准程序。" },
  { field: "法律", title: "行政复议与行政诉讼", body: "对行政机关的具体行政行为不服,可申请行政复议(找上级行政机关),也可提起行政诉讼(找法院「民告官」)。多数情况下二者可自由选择,少数法定情形须先复议才能起诉(复议前置)。", fact: "行政诉讼俗称「民告官」,被告只能是行政机关。" },
  { field: "法律", title: "法律关系三要素", body: "法律关系由主体、客体、内容三要素构成。主体是参加者(自然人、法人等);客体是权利义务指向的对象(物、行为、智力成果、人身利益);内容是主体享有的权利和承担的义务。三者缺一不构成法律关系。", fact: "客体常见四类:物、行为、智力成果、人身利益。" },
  { field: "法律", title: "全国人大是最高国家权力机关", body: "全国人民代表大会是最高国家权力机关,行使修改宪法、制定基本法律、选举国家主席、决定国务院组成等职权。其常设机关是全国人大常委会。国务院是最高国家行政机关,对全国人大及其常委会负责。", fact: "立法权在人大,行政权在国务院,审判权在法院。" },
  { field: "法律", title: "公民基本权利与义务", body: "宪法规定公民享有平等权、政治权利、宗教信仰自由、人身自由、社会经济权利、文化教育权利等。同时须履行维护国家统一、遵守宪法法律、维护祖国安全、依法纳税、服兵役等义务。权利与义务相统一。", fact: "劳动和受教育既是公民的权利,也是义务。" },
  { field: "法律", title: "合同的成立与生效", body: "合同一般自承诺生效时成立。依法成立的合同自成立时生效,但法律规定或当事人约定需办理批准、登记等手续的除外。无民事行为能力人订立的合同无效;限制行为能力人订立的待追认。", fact: "要约是希望订立合同的意思表示,承诺是同意要约。" },
  { field: "法律", title: "知识产权的主要类型", body: "知识产权主要包括著作权(版权)、专利权、商标权。专利分发明、实用新型、外观设计三种,发明专利保护期 20 年。商标注册有效期 10 年,可续展。著作权中的财产权一般保护至作者死后 50 年。", fact: "发明专利 20 年、商标 10 年、著作权作者终身加 50 年。" },
  { field: "法律", title: "违法与犯罪的区别", body: "违法是违反法律的行为的总称,犯罪是其中情节严重、触犯刑法、应受刑罚处罚的违法行为。所有犯罪都是违法,但违法不一定构成犯罪。区分关键在社会危害程度及是否达到刑法规定的追诉标准。", fact: "犯罪是最严重的违法,二者是包含关系。" },

  // ========== 历史人文 (17) ==========
  { field: "历史", title: "中国历史朝代顺序口诀", body: "夏商与西周,东周分两段(春秋、战国);秦汉三国晋,南北朝并立;隋唐五代传,宋元明清后。这是常识判断必背主线。注意东周分春秋战国,三国指魏蜀吴,南北朝是长期分裂时期。", fact: "记忆口诀:夏商周秦汉,三国两晋南北朝,隋唐五代宋元明清。" },
  { field: "历史", title: "四大发明及其朝代", body: "造纸术由东汉蔡伦改进;印刷术中雕版印刷始于隋唐,活字印刷为北宋毕昇发明;火药始于唐、宋代用于军事;指南针前身「司南」战国已有,北宋用于航海。四大发明推动了世界文明进程。", fact: "活字印刷=毕昇=北宋;造纸术改进=蔡伦=东汉。" },
  { field: "历史", title: "商鞅变法与秦的崛起", body: "战国时期秦孝公任用商鞅变法,推行废井田、开阡陌、奖励耕战、建立县制、统一度量衡等措施,使秦国迅速强大,为日后秦始皇统一六国奠定基础。商鞅变法是战国时期最彻底的一次变法。", fact: "商鞅变法发生在秦孝公时期,不是秦始皇时期。" },
  { field: "历史", title: "丝绸之路的开辟者是张骞", body: "西汉汉武帝时期,张骞两次出使西域,开辟了连接中国与中亚、西亚乃至欧洲的陆上丝绸之路。它促进了东西方经济文化交流,佛教、葡萄、汗血马等由此传入中原。", fact: "张骞「凿空西域」,出使在汉武帝时期。" },
  { field: "历史", title: "科举制度始于隋朝", body: "科举制由隋朝创立(隋炀帝设进士科为标志),唐朝完善,明清达到鼎盛并走向僵化(八股取士),1905 年清末废除。它打破了门阀世族对官位的垄断,是中国影响深远的选官制度。", fact: "科举创于隋、兴于唐、废于 1905 年(清末)。" },
  { field: "历史", title: "贞观之治与开元盛世", body: "唐太宗李世民在位期间政治清明、经济繁荣,史称「贞观之治」;唐玄宗李隆基前期励精图治,出现「开元盛世」,是唐朝的全盛时期。安史之乱后唐朝由盛转衰。", fact: "贞观=唐太宗,开元=唐玄宗(前期);安史之乱是转折点。" },
  { field: "历史", title: "鸦片战争是中国近代史开端", body: "1840 年英国发动鸦片战争,1842 年清政府签订中国近代史上第一个不平等条约《南京条约》,割让香港岛、赔款、开五口通商。鸦片战争标志着中国开始沦为半殖民地半封建社会,是中国近代史的开端。", fact: "中国近代史的起点是 1840 年鸦片战争。" },
  { field: "历史", title: "辛亥革命推翻帝制", body: "1911 年孙中山领导的辛亥革命爆发,推翻了清王朝统治,结束了中国两千多年的君主专制制度,建立了中华民国。1912 年元旦中华民国成立,孙中山任临时大总统。这是一次伟大的资产阶级民主革命。", fact: "辛亥革命结束的是「君主专制制度」,不是封建社会。" },
  { field: "历史", title: "中国共产党成立于 1921 年", body: "1921 年 7 月中国共产党第一次全国代表大会在上海召开(后转浙江嘉兴南湖),标志着中国共产党正式成立。这是开天辟地的大事变,中国革命的面貌从此焕然一新。", fact: "建党=1921 年;七一是建党纪念日。" },
  { field: "历史", title: "遵义会议是生死攸关的转折点", body: "1935 年长征途中召开的遵义会议,确立了毛泽东在党和红军中的领导地位,结束了「左」倾错误路线,是中国共产党历史上一个生死攸关的转折点,标志着中国共产党从幼年走向成熟。", fact: "遵义会议=转折点=确立毛泽东领导地位,时间 1935 年。" },
  { field: "历史", title: "新中国成立于 1949 年", body: "1949 年 10 月 1 日,毛泽东在天安门城楼宣告中华人民共和国中央人民政府成立。新中国的成立标志着新民主主义革命基本胜利,中国人民从此站起来了,开启了中国历史新纪元。", fact: "开国大典=1949 年 10 月 1 日,国庆节由此而来。" },
  { field: "历史", title: "儒家与诸子百家", body: "春秋战国百家争鸣,主要有:儒家(孔子、孟子,主张仁政礼治);道家(老子、庄子,主张无为);法家(韩非、商鞅,主张以法治国);墨家(墨子,主张兼爱非攻);兵家(孙武《孙子兵法》)。", fact: "仁=儒家,无为=道家,法治=法家,兼爱=墨家。" },
  { field: "历史", title: "四书五经", body: "四书指《大学》《中庸》《论语》《孟子》,由南宋朱熹编定。五经指《诗经》《尚书》《礼记》《周易》《春秋》。四书五经是儒家经典,也是古代科举考试的核心内容。", fact: "四书=大学中庸论语孟子;五经=诗书礼易春秋。" },
  { field: "历史", title: "中国古代四大名著", body: "《三国演义》(罗贯中)、《水浒传》(施耐庵)、《西游记》(吴承恩)、《红楼梦》(曹雪芹)合称四大名著,均为明清小说。《红楼梦》是中国古典小说的巅峰之作。", fact: "红楼梦作者曹雪芹,成书于清代;其余三部为明代。" },
  { field: "历史", title: "唐诗宋词的代表人物", body: "唐诗:李白(诗仙)、杜甫(诗圣)、白居易(诗魔)、王维(诗佛)。宋词:豪放派有苏轼、辛弃疾;婉约派有李清照、柳永。唐诗宋词是中国文学史上的两座高峰。", fact: "诗仙李白、诗圣杜甫;豪放苏辛、婉约李柳。" },
  { field: "历史", title: "世界四大文明古国", body: "古巴比伦(两河流域)、古埃及(尼罗河)、古印度(印度河恒河)、中国(黄河长江)并称四大文明古国,均发源于大河流域。其中只有中华文明从未中断,延续至今。", fact: "四大古国唯有中国文明未曾中断。" },
  { field: "历史", title: "文艺复兴与启蒙运动", body: "文艺复兴(14-17 世纪)发源于意大利,核心是人文主义,代表有但丁、达芬奇、莎士比亚。启蒙运动(17-18 世纪)发源于法国,核心是理性主义,代表有伏尔泰、孟德斯鸠、卢梭,为资产阶级革命提供思想武器。", fact: "文艺复兴讲「人文」,启蒙运动讲「理性」。" },

  // ========== 地理国情 (17) ==========
  { field: "地理", title: "中国陆地面积约 960 万平方公里", body: "中国陆地面积约 960 万平方公里,居世界第三(俄罗斯、加拿大之后)。陆地边界线长约 2.2 万公里,与 14 个国家接壤;大陆海岸线长约 1.8 万公里。中国是世界上邻国最多的国家之一。", fact: "面积世界第三;陆上邻国 14 个。" },
  { field: "地理", title: "我国地势西高东低呈三级阶梯", body: "中国地势西高东低,呈三级阶梯状分布。第一级阶梯是青藏高原(平均 4000 米以上);第二级是高原和盆地(1000-2000 米);第三级是东部平原和丘陵(500 米以下)。这种地势利于水汽东进、河流东流。", fact: "大江大河多自西向东流,正因地势西高东低。" },
  { field: "地理", title: "长江是中国第一长河", body: "长江全长约 6300 公里,是中国第一、世界第三长河(尼罗河、亚马孙河之后),发源于青藏高原唐古拉山。黄河全长约 5464 公里,是中国第二长河、母亲河,发源于巴颜喀拉山。", fact: "长江最长(世界第三),黄河第二(母亲河)。" },
  { field: "地理", title: "我国四大高原", body: "青藏高原(世界屋脊,最高)、内蒙古高原(地面平坦)、黄土高原(水土流失严重、沟壑纵横)、云贵高原(喀斯特地貌、崎岖不平)合称四大高原。各具典型地貌特征,是常识高频考点。", fact: "黄土高原=水土流失;云贵高原=喀斯特。" },
  { field: "地理", title: "我国四大盆地", body: "塔里木盆地(最大,内有塔克拉玛干沙漠)、准噶尔盆地(纬度最高,位于新疆北部)、柴达木盆地(海拔最高,聚宝盆)、四川盆地(紫色盆地、天府之国)合称四大盆地。前三者在西北,四川盆地在西南。", fact: "最大塔里木、最高柴达木、最北准噶尔。" },
  { field: "地理", title: "二十四节气", body: "二十四节气反映太阳周年视运动,指导农业生产。顺序:立春雨水惊蛰春分清明谷雨、立夏小满芒种夏至小暑大暑、立秋处暑白露秋分寒露霜降、立冬小雪大雪冬至小寒大寒。2016 年被列入联合国教科文组织非遗名录。", fact: "春分、秋分昼夜平分;夏至昼最长,冬至昼最短。" },
  { field: "地理", title: "我国季风气候显著", body: "中国东部属季风气候,夏季盛行来自海洋的东南风,高温多雨;冬季盛行来自大陆的西北风,寒冷干燥。雨热同期是季风气候的突出特点,有利于农业,但也易引发旱涝灾害。", fact: "季风气候最大特点:雨热同期。" },
  { field: "地理", title: "秦岭—淮河是重要地理分界线", body: "秦岭—淮河一线是中国南北方的重要分界线:大致是 1 月 0℃等温线、800 毫米年等降水量线、湿润区与半湿润区分界、水田与旱地分界、亚热带与暖温带分界。", fact: "此线以南种水稻、以北种小麦;以南过年不供暖。" },
  { field: "地理", title: "我国的三大平原", body: "东北平原(最大,黑土地)、华北平原(黄淮海平原,地势低平)、长江中下游平原(鱼米之乡、河湖密布)合称三大平原,均位于地势第三级阶梯,是我国重要的农业区和人口密集区。", fact: "东北平原最大;长江中下游平原称「鱼米之乡」。" },
  { field: "地理", title: "地球自转与公转", body: "地球自转一周约 24 小时,产生昼夜交替和时差;自西向东转,所以太阳东升西落。地球公转一周约 365.25 天,由于地轴倾斜 23.5 度,产生四季更替和昼夜长短变化。", fact: "自转=昼夜/时差,公转=四季/昼夜长短。" },
  { field: "地理", title: "七大洲与四大洋", body: "七大洲面积由大到小:亚洲、非洲、北美洲、南美洲、南极洲、欧洲、大洋洲。四大洋由大到小:太平洋、大西洋、印度洋、北冰洋。亚洲是面积最大、人口最多的洲;太平洋是最大最深的洋。", fact: "亚非北南美,南极欧大洋;太大印北(洋)。" },
  { field: "地理", title: "经线纬线与经纬度", body: "经线连接南北极、指示南北方向,又称子午线;纬线平行于赤道、指示东西方向。本初子午线(0 度经线)过伦敦格林尼治天文台;赤道是 0 度纬线,把地球分为南北半球。东西半球分界为 20°W 和 160°E。", fact: "纬度定南北、经度定东西;赤道是最长的纬线。" },
  { field: "地理", title: "我国人口与民族", body: "中国是世界人口大国,有 56 个民族,汉族人口最多,其余 55 个为少数民族,其中壮族人口最多。人口地理分界线是「胡焕庸线」(黑河—腾冲一线),东南稠密、西北稀疏。", fact: "少数民族中壮族人口最多;胡焕庸线分东密西疏。" },
  { field: "地理", title: "我国的五种地形类型", body: "我国地形多样,包括山地、高原、盆地、平原、丘陵五种基本类型,其中山地面积最大,约占陆地的三分之一。地形复杂多样,山区面积广大,为发展多种经营提供条件,但也增加了交通建设难度。", fact: "五种地形中山地占比最大。" },
  { field: "地理", title: "常见自然灾害与成因", body: "我国主要自然灾害有旱涝(季风不稳定)、台风(东南沿海夏秋)、地震(位于环太平洋和地中海—喜马拉雅两大地震带之间)、滑坡泥石流(山区暴雨)。我国是世界上自然灾害较严重的国家之一。", fact: "我国多地震,因处两大地震带交界。" },
  { field: "地理", title: "黄河为什么会「地上河」", body: "黄河中游流经黄土高原,携带大量泥沙,到下游华北平原流速减慢,泥沙淤积抬高河床,河床高出两岸地面,形成「地上悬河」。治理黄河的关键在于中游的水土保持。", fact: "黄河之害在泥沙,治理关键是中游水土保持。" },
  { field: "地理", title: "时区与北京时间", body: "全球分 24 个时区,每隔 15 度经度为一个时区,相邻时区相差 1 小时。我国统一采用东八区区时作为标准时间,即「北京时间」(实际采用东经 120 度的地方时)。向东时间早,向西时间晚。", fact: "北京时间=东八区区时,全国统一使用。" },

  // ========== 科技生活 (17) ==========
  { field: "科技", title: "牛顿三大运动定律", body: "牛顿第一定律(惯性定律):物体不受力时保持静止或匀速直线运动;第二定律:力等于质量乘加速度(F=ma);第三定律:作用力与反作用力大小相等、方向相反。它们是经典力学的基础。", fact: "惯性=第一定律;F=ma=第二定律;作用反作用=第三定律。" },
  { field: "科技", title: "能量守恒定律", body: "能量既不会凭空产生,也不会凭空消失,只会从一种形式转化为另一种形式,或从一个物体转移到另一个物体,总量保持不变。这是自然界最普遍的基本定律之一,永动机因违反它而不可能造成。", fact: "永动机不可能实现,正是违反了能量守恒。" },
  { field: "科技", title: "光速与声速", body: "光在真空中传播速度约 30 万公里/秒,是宇宙中最快的速度。声音在空气中(15℃)传播速度约 340 米/秒,在固体、液体中更快。所以打雷时先看到闪电后听到雷声。", fact: "光速≈3×10⁸ m/s;声速(空气)≈340 m/s。先见闪电后闻雷。" },
  { field: "科技", title: "物质的三态变化", body: "物质有固、液、气三态。熔化(固→液)吸热,凝固(液→固)放热;汽化(液→气)吸热,液化(气→液)放热;升华(固→气)吸热,凝华(气→固)放热。吸热过程都是从有序到无序。", fact: "升华吸热(如干冰、樟脑丸变小);凝华放热(如霜、雾凇)。" },
  { field: "科技", title: "酸碱与 pH 值", body: "pH 值表示溶液酸碱度,范围 0-14。pH=7 为中性,小于 7 为酸性,大于 7 为碱性,数值越小酸性越强。常见:柠檬汁、食醋呈酸性;肥皂水、纯碱呈碱性;纯水呈中性。", fact: "pH 小于 7 酸、等于 7 中性、大于 7 碱。" },
  { field: "科技", title: "人体必需的六大营养素", body: "人体需要蛋白质、脂肪、糖类(碳水化合物)、维生素、无机盐(矿物质)、水六大营养素。其中蛋白质、脂肪、糖类能供能,称产能营养素;维生素、矿物质、水不供能但不可或缺。", fact: "供能三大类:蛋白质、脂肪、糖类。" },
  { field: "科技", title: "血型与输血", body: "人类 ABO 血型分 A、B、AB、O 四型。O 型曾被称「万能输血者」(红细胞无 A、B 抗原),AB 型为「万能受血者」,但现代医学强调同型输血。RH 血型中 RH 阴性俗称「熊猫血」,较为稀少。", fact: "O 型万能供血、AB 型万能受血(理论);熊猫血=RH 阴性。" },
  { field: "科技", title: "维生素缺乏症", body: "维生素 A 缺乏致夜盲症;维生素 B1 缺乏致脚气病;维生素 C 缺乏致坏血病(牙龈出血);维生素 D 缺乏致佝偻病(儿童)、骨软化(成人)。维生素 D 可经晒太阳在体内合成。", fact: "夜盲=缺 A;坏血病=缺 C;佝偻病=缺 D。" },
  { field: "科技", title: "温室效应与温室气体", body: "二氧化碳、甲烷等温室气体吸收地表长波辐射,使地球保温,过量排放则导致全球变暖。主要温室气体是二氧化碳。我国提出「双碳」目标:力争 2030 年前碳达峰、2060 年前碳中和。", fact: "最主要温室气体是 CO₂;双碳=2030 碳达峰、2060 碳中和。" },
  { field: "科技", title: "我国航天重大成就", body: "1970 年「东方红一号」是我国第一颗人造卫星;2003 年神舟五号搭载杨利伟首次载人航天;2007 年「嫦娥一号」探月;2020 年「天问一号」探火、北斗全球组网完成;2021 年「天和」核心舱发射,中国空间站开建。", fact: "首颗卫星=东方红一号(1970);首位航天员=杨利伟。" },
  { field: "科技", title: "电磁波谱", body: "电磁波按波长从长到短依次为:无线电波、微波、红外线、可见光、紫外线、X 射线、γ 射线。可见光是人眼能看到的部分(红橙黄绿青蓝紫)。红外线有热效应(遥控器),紫外线能杀菌。", fact: "波长:无线电>微波>红外>可见光>紫外>X>γ。" },
  { field: "科技", title: "计算机的存储单位", body: "计算机最小存储单位是比特(bit),基本单位是字节(Byte,1 Byte=8 bit)。换算:1 KB=1024 B,1 MB=1024 KB,1 GB=1024 MB,1 TB=1024 GB。计算机采用二进制(0 和 1)。", fact: "1 字节=8 比特;逐级按 1024 换算;计算机用二进制。" },
  { field: "科技", title: "人工智能与大数据", body: "人工智能(AI)是研究模拟、延伸人类智能的技术,含机器学习、深度学习等。大数据特征概括为「4V」:海量(Volume)、高速(Velocity)、多样(Variety)、价值(Value)。它们是新一代信息技术的核心。", fact: "大数据 4V:量大、速快、种类多、价值密度低。" },
  { field: "科技", title: "DNA 与遗传", body: "DNA(脱氧核糖核酸)是主要遗传物质,呈双螺旋结构,由沃森和克里克于 1953 年发现。基因是有遗传效应的 DNA 片段。生物的性状由基因控制,这是现代遗传学的基础。", fact: "DNA 双螺旋=沃森+克里克,1953 年。" },
  { field: "科技", title: "生态系统的组成", body: "生态系统由生产者(绿色植物,通过光合作用制造有机物)、消费者(动物)、分解者(细菌真菌)和非生物环境组成。能量沿食物链单向流动、逐级递减,物质则可循环利用。", fact: "能量单向递减,物质循环利用;植物是生产者。" },
  { field: "科技", title: "简单机械:杠杆原理", body: "杠杆平衡条件:动力×动力臂=阻力×阻力臂。省力杠杆(动力臂大,如撬棍、瓶起子)省力费距离;费力杠杆(如钓鱼竿、镊子)费力省距离;等臂杠杆(如天平)不省力不省距离。", fact: "省力杠杆动力臂>阻力臂,省力但费距离。" },
  { field: "科技", title: "摩擦力与生活", body: "摩擦力阻碍物体相对运动,分静摩擦、滑动摩擦、滚动摩擦。增大摩擦:增大压力、使接触面粗糙(如防滑鞋底);减小摩擦:加润滑油、用滚动代替滑动(如轴承)。摩擦力既有用也有害。", fact: "滚动摩擦远小于滑动摩擦,故有滚珠轴承。" },

  // ========== 时政国情 (16) ==========
  { field: "时政", title: "我国社会主要矛盾的新表述", body: "党的十九大作出重大判断:我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。这是对此前「物质文化需要同落后的社会生产之间的矛盾」的发展。", fact: "新表述关键词:美好生活需要、不平衡不充分的发展。" },
  { field: "时政", title: "「两个一百年」奋斗目标", body: "第一个百年目标:到建党一百年(2021)全面建成小康社会,已如期实现。第二个百年目标:到新中国成立一百年(2049)建成富强民主文明和谐美丽的社会主义现代化强国。", fact: "第一个百年=全面小康(2021 已实现)。" },
  { field: "时政", title: "新发展理念", body: "创新、协调、绿色、开放、共享五大新发展理念,是习近平新时代中国特色社会主义经济思想的主要内容。其中创新是第一动力,绿色是永续发展的必要条件,共享是本质要求。", fact: "五大理念:创新、协调、绿色、开放、共享。" },
  { field: "时政", title: "「四个全面」战略布局", body: "全面建成社会主义现代化强国、全面深化改革、全面依法治国、全面从严治党合称「四个全面」战略布局。注意表述已从「全面建成小康社会」更新为「全面建成社会主义现代化强国」。", fact: "表述已更新:第一个全面改为「建成社会主义现代化强国」。" },
  { field: "时政", title: "乡村振兴战略", body: "党的十九大提出实施乡村振兴战略,总要求是:产业兴旺、生态宜居、乡风文明、治理有效、生活富裕。脱贫攻坚取得全面胜利后,工作重心转向全面推进乡村振兴,巩固拓展脱贫攻坚成果。", fact: "乡村振兴二十字方针开头是「产业兴旺」。" },
  { field: "时政", title: "我国的根本政治制度", body: "人民代表大会制度是我国的根本政治制度。基本政治制度包括:中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度。社会主义基本经济制度以公有制为主体。", fact: "根本政治制度=人民代表大会制度(唯一)。" },
  { field: "时政", title: "「五位一体」总体布局", body: "中国特色社会主义事业总体布局是经济建设、政治建设、文化建设、社会建设、生态文明建设「五位一体」。其中生态文明建设是后来纳入的,体现对绿色发展的重视。", fact: "五位一体=经济、政治、文化、社会、生态。" },
  { field: "时政", title: "共同富裕的科学内涵", body: "共同富裕是社会主义的本质要求,是全体人民共同富裕,不是少数人富裕,也不是整齐划一的平均主义。要在高质量发展中促进共同富裕,正确处理效率和公平的关系,构建初次分配、再分配、三次分配协调配套的制度。", fact: "共同富裕≠平均主义;靠三次分配协调推进。" },
  { field: "时政", title: "「一国两制」与港澳台", body: "「一国两制」是实现祖国和平统一的基本方针,即一个国家、两种制度。香港 1997 年、澳门 1999 年回归并设特别行政区。解决台湾问题、实现祖国完全统一,是全体中华儿女的共同愿望。", fact: "香港 1997 回归,澳门 1999 回归。" },
  { field: "时政", title: "人类命运共同体", body: "构建人类命运共同体是我国为解决全球性问题贡献的中国智慧和方案,主张建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界。「一带一路」倡议是其重要实践平台。", fact: "一带一路=丝绸之路经济带+21 世纪海上丝绸之路。" },
  { field: "时政", title: "全过程人民民主", body: "全过程人民民主是我国社会主义民主政治的本质属性,把选举民主与协商民主结合起来,实现过程民主和成果民主、程序民主和实质民主的统一,是最广泛、最真实、最管用的民主。", fact: "全过程人民民主强调「全链条、全方位、全覆盖」。" },
  { field: "时政", title: "我国的外交政策", body: "我国奉行独立自主的和平外交政策,维护世界和平、促进共同发展是宗旨。坚持和平共处五项原则(互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处)处理国家间关系。", fact: "和平共处五项原则由中国倡导,1954 年首次提出。" },
  { field: "时政", title: "依法治国与依规治党", body: "全面依法治国是国家治理的一场深刻革命,要坚持依法治国、依法执政、依法行政共同推进,法治国家、法治政府、法治社会一体建设。党内法规同国家法律衔接协调,实现依法治国和依规治党有机统一。", fact: "法治三位一体:法治国家、政府、社会。" },
  { field: "时政", title: "生态文明:绿水青山就是金山银山", body: "「绿水青山就是金山银山」是习近平生态文明思想的核心理念,强调经济发展与生态保护辩证统一。我国坚持节约资源和保护环境的基本国策,推动形成绿色生产生活方式,建设美丽中国。", fact: "「两山论」:绿水青山就是金山银山。" },
  { field: "时政", title: "脱贫攻坚全面胜利", body: "2020 年底,我国现行标准下近 1 亿农村贫困人口全部脱贫,832 个贫困县全部摘帽,区域性整体贫困得到解决,完成了消除绝对贫困的艰巨任务,创造了人类减贫史上的奇迹。", fact: "2020 年我国消除了「绝对贫困」(不是相对贫困)。" },
  { field: "时政", title: "国家治理体系和治理能力现代化", body: "全面深化改革的总目标是完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化。治理体系指制度体系,治理能力指运用制度管理国家的能力,二者相辅相成。", fact: "全面深化改革总目标含「推进国家治理现代化」。" },

  // ========== 经济管理 (16) ==========
  { field: "经济", title: "GDP 与 GNP 的区别", body: "GDP(国内生产总值)按「国土」原则统计,指一国领土范围内生产的最终产品和服务总值;GNP/GNI(国民生产总值/国民总收入)按「国民」原则统计,指一国全体国民所创造的价值。GDP 是衡量经济规模最常用指标。", fact: "GDP 看地域、GNP 看国籍;常用的是 GDP。" },
  { field: "经济", title: "通货膨胀与通货紧缩", body: "通货膨胀指物价持续普遍上涨、货币贬值,通常因货币发行过多或需求过旺;通货紧缩指物价持续下跌、货币升值,往往伴随经济低迷。衡量通胀常用居民消费价格指数(CPI)。温和通胀对经济有一定好处。", fact: "通胀=物价涨钱贬值;衡量指标常用 CPI。" },
  { field: "经济", title: "价值规律", body: "价值规律是商品经济的基本规律:商品价值量由社会必要劳动时间决定,商品交换以价值量为基础实行等价交换。价格受供求关系影响围绕价值上下波动,这正是价值规律的表现形式。", fact: "价值由社会必要劳动时间决定;价格围绕价值波动。" },
  { field: "经济", title: "供给与需求", body: "一般情况下,商品价格上涨,需求量减少、供给量增加;价格下跌则相反。供不应求价格上涨(卖方市场),供过于求价格下跌(买方市场)。供求关系是影响价格的直接因素。", fact: "供不应求=卖方市场=涨价;供过于求=买方市场=降价。" },
  { field: "经济", title: "财政政策与货币政策", body: "财政政策通过政府收支(税收、国债、财政支出)调节经济,由财政部门实施;货币政策通过货币供应量和利率调节经济,由中央银行实施。经济过热时采取紧缩政策,经济低迷时采取扩张(积极)政策。", fact: "财政政策管「收支」,货币政策管「钱和利率」。" },
  { field: "经济", title: "我国的基本经济制度", body: "公有制为主体、多种所有制经济共同发展是我国社会主义基本经济制度的重要内容。同时,按劳分配为主体、多种分配方式并存,社会主义市场经济体制也是基本经济制度的重要组成部分。", fact: "两个「为主体」:公有制、按劳分配。" },
  { field: "经济", title: "市场在资源配置中起决定性作用", body: "党的十八届三中全会提出,要使市场在资源配置中起决定性作用,更好发挥政府作用。这是对市场与政府关系认识的深化(此前表述为「基础性作用」)。市场决定价格、引导资源流向。", fact: "表述已从「基础性作用」升级为「决定性作用」。" },
  { field: "经济", title: "恩格尔系数", body: "恩格尔系数指食品支出占家庭总消费支出的比重。系数越高,说明越穷(收入主要用于吃饭);系数越低,说明越富裕、生活水平越高。它是衡量居民生活水平和贫富程度的重要指标。", fact: "恩格尔系数越低,生活越富裕。" },
  { field: "经济", title: "汇率:升值与贬值", body: "人民币升值意味着同样的人民币能换更多外币,利于进口和出国消费,不利于出口;人民币贬值则利于出口、不利于进口。汇率变化通过影响进出口来影响经济。", fact: "本币升值利进口、抑出口;贬值反之。" },
  { field: "经济", title: "三大产业的划分", body: "第一产业指农业(含农林牧渔);第二产业指工业和建筑业;第三产业指服务业(流通和服务部门)。一国第三产业比重越高,通常经济越发达。我国正推动产业结构优化升级。", fact: "一产农业、二产工业、三产服务业。" },
  { field: "经济", title: "股票、债券与基金", body: "股票是股份公司所有权凭证,风险收益较高,无固定期限;债券是债权债务凭证(到期还本付息),风险相对较低;基金由专业机构集合投资、分散风险。股票代表「股权」,债券代表「债权」。", fact: "股票=股权(当股东);债券=债权(当债主)。" },
  { field: "经济", title: "社会主义市场经济", body: "我国实行社会主义市场经济体制,既发挥市场配置资源的决定性作用,又更好发挥政府作用(宏观调控),把社会主义制度的优越性和市场经济的长处结合起来。这是我国经济体制改革的目标模式。", fact: "特色在于:市场决定+政府宏观调控相结合。" },
  { field: "经济", title: "供给侧结构性改革", body: "供给侧结构性改革从提高供给质量出发,用改革办法推进结构调整,核心任务曾概括为「三去一降一补」:去产能、去库存、去杠杆、降成本、补短板。目的是提高供给体系对需求的适应性。", fact: "三去一降一补:去产能、去库存、去杠杆、降成本、补短板。" },
  { field: "经济", title: "双循环新发展格局", body: "加快构建以国内大循环为主体、国内国际双循环相互促进的新发展格局。它是应对国内外环境变化、把握发展主动权的战略选择,关键在于提升经济循环的畅通水平,扩大内需是战略基点。", fact: "双循环以「国内大循环」为主体,扩大内需是基点。" },
  { field: "经济", title: "机会成本", body: "机会成本指为了得到某种东西而必须放弃的其他东西的最大价值。例如用一块地种粮食,就放弃了用它盖厂房的收益。经济学强调「天下没有免费的午餐」,任何选择都有机会成本。", fact: "机会成本=放弃掉的选项中价值最高的那个。" },
  { field: "经济", title: "边际效用递减规律", body: "在一定时间内,随着消费某种物品数量的增加,消费者从中获得的满足感(边际效用)会逐渐减少。例如很饿时第一个包子最香,越吃后面越没感觉。这解释了为什么需求曲线向下倾斜。", fact: "越吃越不香,就是边际效用递减。" },

  // ========== 考研政治 · 马原(哲学+政经,35) ==========
  { field: "考研政治", title: "哲学的基本问题", body: "哲学的基本问题是思维和存在(意识和物质)的关系问题,包括两个方面:一是何者为第一性(划分唯物主义与唯心主义);二是思维能否认识存在,即有无同一性(划分可知论与不可知论)。", fact: "第一方面分唯物/唯心,第二方面分可知/不可知。" },
  { field: "考研政治", title: "物质的唯一特性是客观实在性", body: "列宁指出,物质是标志客观实在的哲学范畴,它不依赖于人的意识而存在,能被意识所反映。物质的唯一特性是客观实在性。这与自然科学讲的具体物质形态不同,是对一切物质的最高哲学概括。", fact: "物质唯一特性=客观实在性;不等于某种具体实物。" },
  { field: "考研政治", title: "运动是物质的根本属性", body: "运动是标志一切事物变化及其过程的哲学范畴,是物质的根本属性和存在方式。物质和运动不可分:脱离运动的物质和脱离物质的运动都是不可想象的。静止是运动的特殊状态(相对静止)。", fact: "运动绝对、静止相对;静止是运动的特殊状态。" },
  { field: "考研政治", title: "意识的本质", body: "意识是人脑的机能和属性,是客观世界的主观映象。意识在内容上是客观的,在形式上是主观的,即「主观形式、客观内容」的统一。意识的能动作用表现为能动地认识世界和改造世界。", fact: "意识:主观形式+客观内容;人脑是器官,不是源泉。" },
  { field: "考研政治", title: "对立统一规律是唯物辩证法的实质和核心", body: "唯物辩证法三大规律中,对立统一规律(矛盾规律)是实质和核心。它揭示了事物发展的源泉和动力(内部矛盾),是理解其它规律和范畴的钥匙,也是辩证法与形而上学的根本分歧所在。", fact: "三大规律核心=对立统一;它讲发展的「动力」。" },
  { field: "考研政治", title: "矛盾的同一性与斗争性", body: "矛盾的基本属性是同一性和斗争性。同一性指矛盾双方相互依存、相互贯通(你中有我);斗争性指相互排斥、相互对立。同一性是相对的,斗争性是绝对的,二者相结合推动事物发展。", fact: "同一性相对、斗争性绝对;二者共同推动发展。" },
  { field: "考研政治", title: "矛盾的普遍性与特殊性", body: "矛盾普遍性指矛盾无处不在、无时不有(共性);特殊性指具体事物的矛盾各有特点(个性)。二者是共性与个性、一般与个别的关系。具体问题具体分析是马克思主义活的灵魂。", fact: "共性寓于个性之中;「具体问题具体分析」是活的灵魂。" },
  { field: "考研政治", title: "主要矛盾和矛盾的主要方面", body: "主要矛盾在事物发展中处于支配地位、起决定作用,要抓重点、牵牛鼻子。矛盾的主要方面决定事物的性质,要分清主流与支流。前者解决「办事情」抓重点,后者解决「看问题」分主流。", fact: "办事情抓主要矛盾,看问题抓矛盾主要方面。" },
  { field: "考研政治", title: "质量互变规律", body: "量变是数量的增减和场所的变更,是连续的、不显著的变化;质变是根本性质的变化,是飞跃。量变是质变的必要准备,质变是量变的必然结果。要重视量的积累,又要不失时机促成飞跃。", fact: "量变引起质变;「不积跬步无以至千里」讲量变积累。" },
  { field: "考研政治", title: "否定之否定规律", body: "事物发展经过两次否定、三个阶段(肯定—否定—否定之否定),呈现螺旋式上升、波浪式前进的总趋势。辩证否定是「扬弃」——既克服又保留,是事物自我发展的环节和联系的环节。", fact: "辩证否定=扬弃(既克服又保留);发展是前进性与曲折性统一。" },
  { field: "考研政治", title: "实践是认识的基础", body: "实践对认识起决定作用:实践是认识的来源、发展的动力、检验真理的唯一标准、认识的目的。认识又反作用于实践。这是马克思主义认识论首要的和基本的观点——实践的观点。", fact: "实践决定认识(来源、动力、标准、目的四条)。" },
  { field: "考研政治", title: "认识的两次飞跃", body: "认识的辩证运动:第一次飞跃是从感性认识上升到理性认识(实践到认识);第二次飞跃是从理性认识回到实践(认识到实践),后者更重要。认识运动不断反复、无限发展。", fact: "两次飞跃,第二次(理性→实践)更为重要。" },
  { field: "考研政治", title: "真理的客观性、绝对性和相对性", body: "真理是对客观事物及规律的正确反映,具有客观性。真理的绝对性指其无条件性、无限性;相对性指在一定条件下的近似、有限。任何真理都是绝对性和相对性的统一,是一个过程。", fact: "真理内容客观、形式主观;绝对与相对相统一。" },
  { field: "考研政治", title: "实践是检验真理的唯一标准", body: "真理的检验标准只能是社会实践,因为实践具有直接现实性,能把主观认识同客观实际联系起来加以对照。逻辑证明是重要补充,但不能代替实践标准。实践标准既确定又不确定。", fact: "唯一标准是实践;原因在于实践的「直接现实性」。" },
  { field: "考研政治", title: "联系与发展是唯物辩证法总特征", body: "唯物辩证法有两个总特征:联系的观点和发展的观点。联系具有客观性、普遍性、多样性、条件性;发展是前进上升的运动,实质是新事物的产生和旧事物的灭亡。", fact: "两个总特征=联系+发展;发展实质是新事物战胜旧事物。" },
  { field: "考研政治", title: "原因和结果", body: "原因和结果是揭示事物前后相继、彼此制约关系的一对范畴。因果联系的特点是「引起和被引起」,且原因在先、结果在后。承认因果联系的客观普遍性是科学研究的前提。", fact: "因果关系特点:引起与被引起 + 时间先后。" },
  { field: "考研政治", title: "必然性和偶然性", body: "必然性是事物联系和发展中确定不移的趋势,偶然性是可能出现也可能不出现的不确定趋势。必然性通过大量偶然性表现并为自己开辟道路,偶然性背后隐藏着必然性。要透过偶然把握必然。", fact: "必然性通过偶然性表现;偶然性是必然性的补充和表现形式。" },
  { field: "考研政治", title: "可能性和现实性", body: "现实性是已经实现的东西,可能性是包含在事物中、预示发展前途的东西。要区分可能与不可能、现实可能与抽象可能、好的可能与坏的可能。立足现实,努力把好的可能变为现实。", fact: "分清「现实可能」与「抽象(非现实)可能」。" },
  { field: "考研政治", title: "内容和形式", body: "内容是构成事物的要素总和,形式是结构和表现方式。内容决定形式,形式反作用于内容:适合的形式促进内容发展,不适合的则阻碍。要反对形式主义,也反对忽视形式的倾向。", fact: "内容决定形式,形式反作用于内容。" },
  { field: "考研政治", title: "现象和本质", body: "现象是事物的外部联系和表面特征,本质是内部联系和根本性质。现象分真象和假象,假象也是本质的表现(不同于错觉)。科学的任务就是透过现象揭示本质。", fact: "假象是客观的、属本质的表现;错觉是主观的。" },
  { field: "考研政治", title: "尊重客观规律与发挥主观能动性", body: "规律是客观的,不以人的意志为转移,人不能创造或消灭规律。发挥主观能动性必须以尊重客观规律为前提和基础,而认识和利用规律又必须发挥主观能动性。二者辩证统一。", fact: "尊重规律是前提,能动性要在规律基础上发挥。" },
  { field: "考研政治", title: "商品的二因素:价值和使用价值", body: "商品是用来交换的劳动产品,具有使用价值(有用性)和价值(凝结的无差别人类劳动)二因素。使用价值是价值的物质承担者,价值是交换价值的基础。二者对立统一。", fact: "使用价值是价值的物质承担者;价值是本质。" },
  { field: "考研政治", title: "劳动的二重性:具体劳动和抽象劳动", body: "生产商品的劳动具有二重性:具体劳动创造使用价值,抽象劳动创造价值。劳动二重性学说是理解政治经济学的枢纽,由马克思首先论证,是其对经济学的重大贡献。", fact: "具体劳动造使用价值,抽象劳动造价值;二重性是「枢纽」。" },
  { field: "考研政治", title: "价值规律(马原)", body: "价值规律是商品经济的基本规律:商品价值由社会必要劳动时间决定,交换按等价原则进行。表现形式是价格围绕价值上下波动。作用:调节资源配置、刺激技术进步、引起两极分化。", fact: "价值量由「社会必要劳动时间」决定;价格围绕价值波动。" },
  { field: "考研政治", title: "剩余价值的生产", body: "资本家购买劳动力商品,劳动力在使用中创造的价值大于其自身价值,超出的部分即剩余价值,被资本家无偿占有。剩余价值是雇佣工人创造的、被资本家无偿占有的那部分价值,体现剥削关系。", fact: "剩余价值=工人创造的、超过劳动力价值的部分。" },
  { field: "考研政治", title: "不变资本和可变资本", body: "以生产资料形式存在的资本是不变资本(c),其价值只是转移、不发生增殖;以劳动力形式存在的是可变资本(v),它能带来剩余价值(m)。这一区分揭示了剩余价值的真正来源是可变资本。", fact: "剩余价值来源是可变资本(v),不是不变资本(c)。" },
  { field: "考研政治", title: "绝对剩余价值与相对剩余价值", body: "绝对剩余价值靠延长工作日生产;相对剩余价值靠缩短必要劳动时间(提高社会劳动生产率)生产。超额剩余价值是个别企业率先提高劳动生产率获得的,是相对剩余价值的一种特殊形式。", fact: "延长工时=绝对;提高生产率缩短必要劳动=相对。" },
  { field: "考研政治", title: "资本积累", body: "把剩余价值转化为资本,叫资本积累。其源泉是剩余价值。资本积累导致资本有机构成提高,产生相对过剩人口(失业),并加剧两极分化。资本积累是扩大再生产的源泉。", fact: "资本积累源泉=剩余价值;后果含相对过剩人口。" },
  { field: "考研政治", title: "资本的循环与周转", body: "产业资本循环要依次经过购买、生产、销售三个阶段,相应采取货币资本、生产资本、商品资本三种职能形式。资本周转速度影响年剩余价值量,加速周转可提高资本增殖效率。", fact: "循环三阶段:购买—生产—销售;三种职能形式对应。" },
  { field: "考研政治", title: "经济危机的实质与根源", body: "资本主义经济危机的实质是生产相对过剩(相对于劳动人民有支付能力的需求过剩,不是绝对过剩)。根源是资本主义基本矛盾,即生产社会化和生产资料资本主义私人占有之间的矛盾。", fact: "危机实质=相对过剩;根源=资本主义基本矛盾。" },
  { field: "考研政治", title: "社会存在与社会意识", body: "社会存在是社会物质生活条件(主要是生产方式),社会意识是社会精神生活。社会存在决定社会意识,社会意识具有相对独立性并反作用于社会存在。这是历史唯物主义的基本问题。", fact: "社会存在决定社会意识;社会意识有相对独立性。" },
  { field: "考研政治", title: "生产力和生产关系", body: "生产力是人们改造自然的能力(含劳动者、劳动资料、劳动对象);生产关系是生产中结成的经济关系。生产力决定生产关系,生产关系反作用于生产力。这是人类社会的基本矛盾之一。", fact: "生产力决定生产关系;生产工具是生产力发展水平的标志。" },
  { field: "考研政治", title: "经济基础和上层建筑", body: "经济基础是一定社会占统治地位的生产关系的总和;上层建筑包括政治上层建筑(国家、法律制度等)和思想上层建筑。经济基础决定上层建筑,上层建筑反作用于经济基础。", fact: "经济基础决定上层建筑;国家属于政治上层建筑核心。" },
  { field: "考研政治", title: "人民群众是历史的创造者", body: "历史唯物主义认为,人民群众是社会物质财富和精神财富的创造者,是社会变革的决定力量。这要求坚持群众观点和群众路线。与英雄史观(唯心史观)根本对立。", fact: "人民群众创造历史;对立面是唯心史观(英雄史观)。" },
  { field: "考研政治", title: "科学技术是第一生产力", body: "科学技术属于生产力中的智能性要素,通过渗透到劳动者、劳动资料、劳动对象中转化为现实生产力。邓小平提出「科学技术是第一生产力」,现代科技对经济发展起第一位的变革作用。", fact: "科技是第一生产力(邓小平);通过渗透转化为现实生产力。" },

  // ========== 考研政治 · 毛中特(30) ==========
  { field: "考研政治", title: "马克思主义中国化的提出", body: "1938 年,毛泽东在党的六届六中全会上首次提出「马克思主义中国化」的命题。马克思主义中国化就是把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合。", fact: "「马克思主义中国化」首次提出=1938 年六届六中全会(毛泽东)。" },
  { field: "考研政治", title: "毛泽东思想的活的灵魂", body: "毛泽东思想活的灵魂有三个基本方面:实事求是、群众路线、独立自主。其中实事求是是毛泽东思想的精髓,是贯穿其中的根本立场、观点和方法。", fact: "三个活的灵魂:实事求是、群众路线、独立自主;精髓是实事求是。" },
  { field: "考研政治", title: "新民主主义革命的总路线", body: "新民主主义革命总路线是:无产阶级领导的,人民大众的,反对帝国主义、封建主义和官僚资本主义的革命。其中无产阶级的领导权是革命的中心问题,也是区别于旧民主主义革命的根本标志。", fact: "三大革命对象:帝国主义、封建主义、官僚资本主义;核心是领导权。" },
  { field: "考研政治", title: "新民主主义革命的三大法宝", body: "统一战线、武装斗争、党的建设是中国共产党在新民主主义革命中战胜敌人的三大法宝。统一战线和武装斗争是战胜敌人的两个基本武器,党的建设是掌握这两个武器的英勇战士。", fact: "三大法宝:统一战线、武装斗争、党的建设。" },
  { field: "考研政治", title: "农村包围城市、武装夺取政权", body: "毛泽东开创了农村包围城市、武装夺取政权的中国革命道路(井冈山道路)。其依据是中国是半殖民地半封建的农业大国,这条道路反映了中国革命发展的客观规律,是马克思主义中国化的典范。", fact: "井冈山道路=农村包围城市、武装夺取政权。" },
  { field: "考研政治", title: "实事求是思想路线", body: "党的思想路线是:一切从实际出发,理论联系实际,实事求是,在实践中检验真理和发展真理。其核心和实质是实事求是。这是毛泽东为党确立的思想路线,是党制定正确路线方针的思想基础。", fact: "思想路线核心=实事求是;是毛泽东确立的。" },
  { field: "考研政治", title: "社会主义改造(三大改造)", body: "1953—1956 年,我国对农业、手工业和资本主义工商业进行社会主义改造。对资本主义工商业采取和平赎买政策、国家资本主义形式。三大改造完成,标志着社会主义制度在我国基本确立。", fact: "三大改造完成(1956)=社会主义制度基本确立;对资改造用「赎买」。" },
  { field: "考研政治", title: "社会主义初级阶段理论", body: "我国正处于并将长期处于社会主义初级阶段。这是对我国基本国情的科学判断。初级阶段指两层含义:我国已经是社会主义社会;我国的社会主义还处在不发达阶段。至少需要上百年时间。", fact: "初级阶段两层含义:已是社会主义 + 还不发达。" },
  { field: "考研政治", title: "党在社会主义初级阶段的基本路线", body: "基本路线核心内容:领导和团结全国各族人民,以经济建设为中心,坚持四项基本原则,坚持改革开放,为把我国建设成为富强民主文明和谐美丽的社会主义现代化强国而奋斗。概括为「一个中心、两个基本点」。", fact: "一个中心=经济建设;两个基本点=四项基本原则+改革开放。" },
  { field: "考研政治", title: "社会主义本质", body: "邓小平指出,社会主义的本质是解放生产力,发展生产力,消灭剥削,消除两极分化,最终达到共同富裕。这一概括突出了发展生产力和共同富裕,是对「什么是社会主义」的科学回答。", fact: "社会主义本质=解放发展生产力 + 消灭剥削消除两极分化 + 共同富裕。" },
  { field: "考研政治", title: "改革开放", body: "1978 年党的十一届三中全会作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策,是新中国成立以来党的历史上具有深远意义的伟大转折,开启了改革开放和社会主义现代化建设新时期。", fact: "改革开放起点=1978 年十一届三中全会(伟大转折)。" },
  { field: "考研政治", title: "社会主义市场经济理论", body: "邓小平指出,计划和市场都是经济手段,不是社会主义与资本主义的本质区别。1992 年南方谈话和党的十四大确立了建立社会主义市场经济体制的改革目标。这是重大理论突破。", fact: "计划市场都是手段;社会主义市场经济目标=十四大(1992)确立。" },
  { field: "考研政治", title: "「三个代表」重要思想", body: "中国共产党要始终代表中国先进生产力的发展要求、代表中国先进文化的前进方向、代表中国最广大人民的根本利益。「三个代表」重要思想的本质是立党为公、执政为民,集中回答了建设什么样的党、怎样建设党。", fact: "三个代表:先进生产力、先进文化、最广大人民根本利益。" },
  { field: "考研政治", title: "科学发展观", body: "科学发展观第一要义是发展,核心立场是以人为本,基本要求是全面协调可持续,根本方法是统筹兼顾。它深刻回答了新形势下实现什么样的发展、怎样发展的重大问题。", fact: "科学发展观:第一要义发展、核心以人为本、基本要求全面协调可持续。" },
  { field: "考研政治", title: "习近平新时代中国特色社会主义思想", body: "它是马克思主义中国化的最新成果,是党和人民实践经验和集体智慧的结晶,是当代中国马克思主义、二十一世纪马克思主义,是全党全国人民为实现中华民族伟大复兴而奋斗的行动指南。", fact: "新思想=当代中国马克思主义、21 世纪马克思主义。" },
  { field: "考研政治", title: "新时代我国社会主要矛盾", body: "党的十九大指出,中国特色社会主义进入新时代,我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。这是关系全局的历史性变化。", fact: "新矛盾=美好生活需要 vs 不平衡不充分的发展。" },
  { field: "考研政治", title: "「五位一体」总体布局(考研)", body: "统筹推进经济建设、政治建设、文化建设、社会建设、生态文明建设,是中国特色社会主义事业的总体布局,简称「五位一体」。生态文明建设的纳入体现了对可持续发展的高度重视。", fact: "五位一体:经济、政治、文化、社会、生态。" },
  { field: "考研政治", title: "「四个全面」战略布局(考研)", body: "全面建成社会主义现代化强国、全面深化改革、全面依法治国、全面从严治党,构成「四个全面」战略布局。注意第一个「全面」的表述已随全面建成小康社会目标实现而更新。", fact: "四个全面:现代化强国、深化改革、依法治国、从严治党。" },
  { field: "考研政治", title: "新发展理念(考研)", body: "创新、协调、绿色、开放、共享五大发展理念,是针对我国发展中的突出问题提出的。创新是引领发展的第一动力,协调是持续健康发展的内在要求,绿色是永续发展必要条件,开放是必由之路,共享是本质要求。", fact: "五大理念:创新(第一动力)、协调、绿色、开放、共享。" },
  { field: "考研政治", title: "「两步走」战略安排", body: "到 2035 年基本实现社会主义现代化;到本世纪中叶(2050)把我国建成富强民主文明和谐美丽的社会主义现代化强国。这是新时代中国特色社会主义发展的战略安排。", fact: "第一步 2035 基本实现现代化;第二步 2050 建成现代化强国。" },
  { field: "考研政治", title: "全面深化改革的总目标", body: "全面深化改革的总目标是完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化。这是「两句话组成的一个整体」,前者规定根本方向,后者指明实现途径。", fact: "总目标两句:完善发展中国特色社会主义制度 + 推进国家治理现代化。" },
  { field: "考研政治", title: "坚持党对一切工作的领导", body: "中国特色社会主义最本质的特征是中国共产党领导,中国特色社会主义制度的最大优势是中国共产党领导。党是最高政治领导力量。「东西南北中,党政军民学,党是领导一切的」。", fact: "最本质特征 + 最大优势,都是中国共产党领导。" },
  { field: "考研政治", title: "新发展格局", body: "加快构建以国内大循环为主体、国内国际双循环相互促进的新发展格局。这是立足国内、面向世界的战略选择,其中扩大内需是战略基点,科技自立自强是关键支撑。", fact: "新发展格局以国内大循环为主体;扩大内需是战略基点。" },
  { field: "考研政治", title: "高质量发展", body: "高质量发展是全面建设社会主义现代化国家的首要任务。它是体现新发展理念的发展,是从「有没有」转向「好不好」,要以推动高质量发展为主题,把发展质量问题摆在更为突出的位置。", fact: "高质量发展=现代化建设的首要任务;从「有没有」到「好不好」。" },
  { field: "考研政治", title: "全过程人民民主(考研)", body: "全过程人民民主是社会主义民主政治的本质属性,是最广泛、最真实、最管用的民主。它实现了过程民主和成果民主、程序民主和实质民主、直接民主和间接民主的统一。", fact: "全过程人民民主=最广泛、最真实、最管用的民主。" },
  { field: "考研政治", title: "全面依法治国", body: "全面依法治国是国家治理的一场深刻革命。总目标是建设中国特色社会主义法治体系、建设社会主义法治国家。要坚持依法治国、依法执政、依法行政共同推进,法治国家、法治政府、法治社会一体建设。", fact: "依法治国总目标:中国特色社会主义法治体系 + 社会主义法治国家。" },
  { field: "考研政治", title: "全面从严治党", body: "全面从严治党永远在路上,党的自我革命永远在路上。要以党的政治建设为统领,把政治建设摆在首位。新时代党的建设总要求强调坚持和加强党的全面领导、坚持党要管党全面从严治党。", fact: "全面从严治党以「政治建设」为统领、摆首位。" },
  { field: "考研政治", title: "人类命运共同体(考研)", body: "构建人类命运共同体,主张建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界。这是中国为解决人类面临的共同问题贡献的中国智慧和中国方案,「一带一路」是重要实践平台。", fact: "人类命运共同体:持久和平、普遍安全、共同繁荣、开放包容、清洁美丽。" },
  { field: "考研政治", title: "中国式现代化", body: "中国式现代化是中国共产党领导的社会主义现代化,具有五个特征:人口规模巨大、全体人民共同富裕、物质文明和精神文明相协调、人与自然和谐共生、走和平发展道路的现代化。", fact: "中国式现代化五特征,含「人口规模巨大」「共同富裕」。" },
  { field: "考研政治", title: "「两个结合」", body: "推进马克思主义中国化时代化,必须坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合。「两个结合」是我们取得成功的最大法宝,其中第二个结合是又一次思想解放。", fact: "两个结合:同中国具体实际 + 同中华优秀传统文化。" },

  // ========== 考研政治 · 史纲(近代史,20) ==========
  { field: "考研政治", title: "鸦片战争与近代史开端", body: "1840 年英国发动鸦片战争,1842 年签订《南京条约》。鸦片战争使中国开始沦为半殖民地半封建社会,是中国近代史的起点。中国社会主要矛盾、革命任务由此发生根本变化。", fact: "近代史开端=1840 年鸦片战争;首个不平等条约《南京条约》。" },
  { field: "考研政治", title: "太平天国运动", body: "1851—1864 年洪秀全领导太平天国运动,颁布《天朝田亩制度》(绝对平均主义纲领)和《资政新篇》(最早提出发展资本主义的方案)。它是旧式农民战争的最高峰,因阶级局限性而失败。", fact: "《天朝田亩制度》平均主义;《资政新篇》首倡发展资本主义。" },
  { field: "考研政治", title: "洋务运动", body: "19 世纪 60—90 年代,洋务派以「自强」「求富」为口号兴办近代军事、民用工业。它没有使中国走上富强,甲午战败宣告其破产,但客观上促进了中国早期现代化。指导思想是「中学为体,西学为用」。", fact: "洋务运动口号:自强、求富;指导思想「中体西用」。" },
  { field: "考研政治", title: "戊戌维新运动", body: "1898 年以康有为、梁启超为代表的维新派推动戊戌变法,主张君主立宪、发展资本主义。变法仅持续百余日即被慈禧镇压(百日维新)。它是一次思想启蒙运动,失败说明改良道路在中国行不通。", fact: "戊戌变法=百日维新(1898);康梁维新派,走改良道路失败。" },
  { field: "考研政治", title: "辛亥革命的历史意义", body: "1911 年孙中山领导辛亥革命,推翻清王朝,结束了两千多年的封建君主专制制度,建立中华民国,使民主共和观念深入人心。但它没有改变半殖民地半封建社会性质,革命果实被袁世凯窃取。", fact: "辛亥革命结束「君主专制制度」,但未改变社会性质。" },
  { field: "考研政治", title: "新文化运动", body: "1915 年陈独秀创办《青年杂志》(后改《新青年》),高举民主与科学(德先生、赛先生)两面大旗,是一场思想解放运动。后期开始传播马克思主义,为五四运动和中共成立作了思想准备。", fact: "新文化运动两大旗帜:民主(德先生)、科学(赛先生)。" },
  { field: "考研政治", title: "五四运动", body: "1919 年五四运动爆发,是一场彻底反帝反封建的爱国运动,工人阶级开始登上政治舞台。它是中国新民主主义革命的开端,促进了马克思主义的传播及其同工人运动的结合。", fact: "五四运动(1919)=新民主主义革命开端;工人阶级登上舞台。" },
  { field: "考研政治", title: "中国共产党成立", body: "1921 年 7 月,中共一大在上海召开(后转嘉兴南湖),宣告中国共产党成立。这是开天辟地的大事变,自从有了中国共产党,中国革命的面貌焕然一新。党成立的阶级基础是工人阶级。", fact: "中共一大=1921 年;「开天辟地的大事变」。" },
  { field: "考研政治", title: "第一次国共合作与大革命", body: "1924 年国民党一大召开,标志第一次国共合作正式形成,推动了以北伐战争为高潮的大革命。1927 年蒋介石、汪精卫叛变革命,大革命失败,其经验教训是必须掌握革命领导权和武装力量。", fact: "第一次国共合作(1924)推动北伐;1927 年大革命失败。" },
  { field: "考研政治", title: "南昌起义", body: "1927 年 8 月 1 日,周恩来等领导南昌起义,打响了武装反抗国民党反动派的第一枪,标志着中国共产党独立领导革命战争、创建人民军队的开始。8 月 1 日后成为建军节。", fact: "南昌起义=1927.8.1=武装反抗第一枪=建军节由来。" },
  { field: "考研政治", title: "井冈山革命根据地", body: "1927 年毛泽东领导秋收起义后,率部上井冈山,创建了第一个农村革命根据地,开辟了农村包围城市、武装夺取政权的革命道路,提出「工农武装割据」思想。这是马克思主义中国化的开始。", fact: "井冈山=第一个农村革命根据地;「工农武装割据」。" },
  { field: "考研政治", title: "遵义会议", body: "1935 年 1 月遵义会议召开,集中解决军事和组织问题,实际确立了毛泽东在党中央和红军的领导地位,结束了「左」倾教条主义错误在中央的统治。它是党历史上一个生死攸关的转折点,标志党走向成熟。", fact: "遵义会议(1935)=生死攸关转折点=确立毛泽东领导。" },
  { field: "考研政治", title: "红军长征", body: "1934—1936 年,红军进行战略转移长征,1936 年红军三大主力在甘肃会宁会师,标志长征胜利结束。长征是人类历史上的伟大壮举,铸就了伟大长征精神,保存了革命的火种。", fact: "长征胜利结束=1936 年会宁三大主力会师。" },
  { field: "考研政治", title: "抗日民族统一战线", body: "1935 年瓦窑堡会议确定建立抗日民族统一战线的策略方针。1936 年西安事变和平解决,成为时局转换的枢纽。1937 年抗日民族统一战线正式形成,实现第二次国共合作,全民族抗战开始。", fact: "西安事变(1936)和平解决是时局转换枢纽;推动统一战线。" },
  { field: "考研政治", title: "《论持久战》", body: "1938 年毛泽东发表《论持久战》,科学分析了中日双方特点,批驳「速胜论」和「亡国论」,指出抗战将经过战略防御、战略相持、战略反攻三个阶段,最后胜利属于中国,阐明了持久战的总方针。", fact: "《论持久战》(1938)=三阶段论,批速胜论与亡国论。" },
  { field: "考研政治", title: "中共七大与毛泽东思想指导地位确立", body: "1945 年中共七大在延安召开,制定了「放手发动群众、壮大人民力量」的路线,并把毛泽东思想确立为党的指导思想写入党章。七大为抗战胜利和新民主主义革命在全国的胜利奠定了基础。", fact: "中共七大(1945)=毛泽东思想写入党章、确立为指导思想。" },
  { field: "考研政治", title: "抗日战争胜利", body: "1945 年 8 月 15 日日本宣布无条件投降,中国人民抗日战争取得完全胜利。这是近代以来中国抗击外敌入侵的第一次完全胜利,也是世界反法西斯战争的重要组成部分,中国作出巨大民族牺牲和贡献。", fact: "抗战胜利=1945.8.15 日本投降=近代反侵略第一次完全胜利。" },
  { field: "考研政治", title: "解放战争与三大战役", body: "1946 年全面内战爆发。1948—1949 年辽沈、淮海、平津三大战役基本消灭国民党主力。1949 年 4 月渡江战役解放南京,宣告国民党反动统治覆灭。人民解放战争取得基本胜利。", fact: "三大战役:辽沈、淮海、平津;渡江战役解放南京。" },
  { field: "考研政治", title: "中共七届二中全会", body: "1949 年七届二中全会召开,提出党的工作重心由乡村转移到城市,规定了全国胜利后党在各方面的基本政策。毛泽东告诫全党务必继续保持谦虚谨慎、艰苦奋斗的作风(「两个务必」)。", fact: "七届二中全会(1949):工作重心乡村转城市;提出「两个务必」。" },
  { field: "考研政治", title: "中华人民共和国成立的意义", body: "1949 年 10 月 1 日新中国成立,标志着新民主主义革命取得基本胜利,结束了帝国主义、封建主义、官僚资本主义在中国的统治,中国人民站起来了,实现了民族独立和人民解放,开启了中华民族发展新纪元。", fact: "新中国成立(1949)=新民主主义革命基本胜利;中国人民站起来了。" },

  // ========== 考研政治 · 思修法基(15) ==========
  { field: "考研政治", title: "理想信念的作用", body: "理想信念是精神之钙,是人的精神世界的核心,是世界观、人生观、价值观在奋斗目标上的集中体现。崇高的理想信念能指引人生方向、提供前进动力、提高精神境界。共产主义远大理想与中国特色社会主义共同理想相统一。", fact: "理想信念=精神之钙;远大理想与共同理想相统一。" },
  { field: "考研政治", title: "中国精神:民族精神与时代精神", body: "中国精神以爱国主义为核心的民族精神和以改革创新为核心的时代精神为主要内容。中国精神是兴国强国之魂,是凝心聚力的兴国之魂、强国之魂。弘扬中国精神能凝聚中国力量。", fact: "民族精神核心=爱国主义;时代精神核心=改革创新。" },
  { field: "考研政治", title: "人生观的主要内容", body: "人生观主要包括人生目的、人生态度、人生价值三方面。人生目的回答「为什么活」,居于核心地位,决定人生道路、人生态度和人生价值选择。应树立为人民服务的人生观。", fact: "人生观三要素:目的、态度、价值;人生目的是核心。" },
  { field: "考研政治", title: "人生价值的评价", body: "人生价值包括自我价值和社会价值。人生的社会价值是基础和源泉,自我价值是前提和条件。评价人生价值的根本尺度,是看一个人的行为是否对社会、对他人作出了贡献。", fact: "社会价值是基础;评价根本尺度=是否作出贡献。" },
  { field: "考研政治", title: "社会主义核心价值观", body: "富强、民主、文明、和谐是国家层面的价值目标;自由、平等、公正、法治是社会层面的价值取向;爱国、敬业、诚信、友善是公民层面的价值准则。这是当代中国精神的集中体现,凝结着共同的价值追求。", fact: "三个层面:国家(富强民主文明和谐)、社会(自由平等公正法治)、公民(爱国敬业诚信友善)。" },
  { field: "考研政治", title: "道德的功能与作用", body: "道德具有认识、规范、调节等功能,其中调节功能是道德最主要、最突出的功能。道德通过社会舆论、传统习俗和内心信念发挥作用,调节人与人、人与社会、人与自然之间的关系。", fact: "道德最主要功能=调节功能。" },
  { field: "考研政治", title: "中华传统美德与社会公德", body: "中华传统美德是中华文化的精髓。社会公德是公共生活中应遵守的基本准则,主要包括:文明礼貌、助人为乐、爱护公物、保护环境、遵纪守法。它涵盖人与人、人与社会、人与自然的关系。", fact: "社会公德五项:文明礼貌、助人为乐、爱护公物、保护环境、遵纪守法。" },
  { field: "考研政治", title: "职业道德的基本要求", body: "社会主义职业道德的基本要求是:爱岗敬业、诚实守信、办事公道、服务群众、奉献社会。其中爱岗敬业是最基本的要求,奉献社会是职业道德的最高境界。", fact: "职业道德五要求;爱岗敬业最基本,奉献社会最高。" },
  { field: "考研政治", title: "我国宪法的基本原则", body: "我国宪法的基本原则包括:党的领导原则、人民主权原则、尊重和保障人权原则、社会主义法治原则、民主集中制原则。宪法是国家的根本法,是治国安邦的总章程,具有最高法律效力。", fact: "宪法是根本法、总章程、最高法律效力。" },
  { field: "考研政治", title: "我国的国家制度", body: "我国的国体是人民民主专政,政体是人民代表大会制度(根本政治制度)。国家结构形式是单一制。基本政治制度包括中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度。", fact: "国体=人民民主专政;政体=人民代表大会制度。" },
  { field: "考研政治", title: "法律权利与法律义务", body: "法律权利是法律赋予主体为满足其利益而自主行动的许可;法律义务是主体依法必须作出或不作出一定行为。权利和义务是对立统一、相互依存的关系,不存在只享受权利不承担义务的情况。", fact: "权利义务相统一;没有无义务的权利。" },
  { field: "考研政治", title: "法治思维的基本内容", body: "法治思维主要包括:法律至上、权力制约、公平正义、权利保障、程序正当。其中法律至上是法治思维的内在要求,表现为法律的普遍适用性、优先性和不可违抗性。要善于运用法治思维和法治方式。", fact: "法治思维五方面;「法律至上」是内在要求。" },
  { field: "考研政治", title: "依法行使权利与履行义务", body: "公民行使权利要遵循合法、正当的原则,不得损害国家、社会、集体利益和其他公民的合法权利。权利的行使有界限,自由不是为所欲为。同时要自觉履行法定义务,法律义务具有强制性。", fact: "权利行使有界限;不得损害国家、社会、他人利益。" },
  { field: "考研政治", title: "爱国主义的基本要求", body: "爱国主义的基本要求包括:爱祖国的大好河山、爱自己的骨肉同胞、爱祖国的灿烂文化、爱自己的国家。新时代爱国主义的本质是坚持爱国和爱党、爱社会主义高度统一。", fact: "新时代爱国主义本质:爱国、爱党、爱社会主义相统一。" },
  { field: "考研政治", title: "个人理想与社会理想的统一", body: "个人理想与社会理想相互联系、相互影响。社会理想规定、指引着个人理想,是个人理想的凝聚和升华;个人理想的实现要以社会理想的实现为前提。要把个人的理想融入国家和民族的事业中。", fact: "社会理想引领个人理想;把个人理想融入国家民族事业。" },

  // ========== 生活百科 · 健康养生(40) ==========
  { field: "百科", title: "每天到底该喝多少水", body: "健康成年人一天大约需要 1500—1700 毫升水(约 7—8 杯),但这包括食物中的水分,不必强行灌够「8 杯」。口渴时就喝、尿液呈淡黄色说明水分足够。运动、高温、发烧时要多补。一次猛灌大量水反而增加肾脏负担。", fact: "看尿液颜色判断:淡黄色=刚好,深黄=该喝水了。" },
  { field: "百科", title: "成年人每天需要睡多久", body: "成年人建议每晚睡 7—9 小时。长期睡不够会影响记忆、免疫和情绪,但睡得过多(超过 9 小时)也和健康风险相关。比时长更重要的是规律和质量:固定作息、睡前远离手机屏幕更有助于深睡。", fact: "质量比时长更重要;固定作息是好睡眠的关键。" },
  { field: "百科", title: "饭后不要马上剧烈运动", body: "刚吃完饭,血液集中到胃肠帮助消化,此时剧烈运动会分走血液,既影响消化又容易岔气、恶心。建议饭后休息 30 分钟以上再运动,散步这类轻活动则没问题,反而助消化。", fact: "饭后散步可以,剧烈运动至少等半小时。" },
  { field: "百科", title: "久坐的危害与破解", body: "长时间久坐会影响血液循环、增加腰椎和颈椎负担,还和肥胖、心血管风险相关。建议每坐 1 小时就起身活动 3—5 分钟,接杯水、走动一下。哪怕只是站起来伸展,也比一直坐着强。", fact: "每坐 1 小时起身动一动,比专门锻炼还重要。" },
  { field: "百科", title: "感冒多数是病毒引起,不用抗生素", body: "普通感冒绝大多数由病毒引起,抗生素只对细菌有效,对病毒无用。乱吃抗生素不但治不好感冒,还会增加耐药风险。感冒主要靠休息、多喝水、对症缓解,一般一周左右自愈。", fact: "感冒别动不动吃消炎药(抗生素),对病毒没用。" },
  { field: "百科", title: "发烧不一定要马上退烧", body: "发烧是身体对抗感染的正常反应,38.5℃ 以下、精神尚可时,多喝水、物理降温(温水擦浴)即可,不必急着吃退烧药。超过 38.5℃ 或很难受时再用退烧药。持续高烧或精神萎靡要及时就医。", fact: "一般 38.5℃ 以上或明显难受才用退烧药。" },
  { field: "百科", title: "洗手是最有效的防病手段之一", body: "很多疾病通过手接触传播。用肥皂和流动水认真洗手 20 秒(约唱两遍生日歌),能显著减少感染风险。重点搓洗指缝、指尖、手背。饭前便后、外出回家、咳嗽打喷嚏后都该洗手。", fact: "洗手要搓够 20 秒,别忘指缝和指尖。" },
  { field: "百科", title: "护眼的 20-20-20 法则", body: "长时间看屏幕容易眼疲劳。护眼可用 20-20-20 法则:每看屏幕 20 分钟,抬头看 20 英尺(约 6 米)外的地方,持续 20 秒。让眼睛的睫状肌放松,能有效缓解酸涩和干涩。", fact: "每 20 分钟,看 6 米外 20 秒。" },
  { field: "百科", title: "正确的刷牙方式", body: "推荐「巴氏刷牙法」:牙刷与牙面成 45 度角,对准牙齿和牙龈交界处小幅度水平颤动,再轻轻向牙冠方向刷。每次刷够 2—3 分钟,别用力横着来回拉锯,否则会磨损牙颈、伤牙龈。", fact: "别横着使劲拉锯刷,会磨坏牙颈。" },
  { field: "百科", title: "早餐不吃的影响", body: "长期不吃早餐,上午容易注意力不集中、乏力,还可能因午餐过量而更易发胖,并增加胆结石风险。一份好早餐最好有主食+蛋白质(如鸡蛋、牛奶)+一点蔬果,给上午提供稳定能量。", fact: "好早餐搭配:主食 + 蛋白质 + 蔬果。" },
  { field: "百科", title: "盐吃多了的危害", body: "吃盐过多(钠超标)会升高血压,增加心脑血管和肾脏负担。世界卫生组织建议成年人每天食盐不超过 5 克(约一啤酒瓶盖)。酱油、咸菜、加工食品里都有「隐形盐」,要一起算。", fact: "每天盐不超过 5 克;酱油、零食里的隐形盐也要算。" },
  { field: "百科", title: "糖吃多了不只是长胖", body: "过量摄入添加糖除了导致肥胖、蛀牙,还会增加糖尿病和脂肪肝风险。建议每天添加糖不超过 50 克、最好控制在 25 克以内。含糖饮料是「糖大户」,一瓶可乐的糖就接近一天上限。", fact: "每天添加糖最好不超过 25 克;一瓶含糖饮料就快到顶。" },
  { field: "百科", title: "适量晒太阳有助补钙", body: "皮肤在阳光(紫外线)照射下能合成维生素 D,而维生素 D 帮助吸收钙。每天晒 10—20 分钟太阳(露出手臂脸部)对骨骼有益。但要避开正午强晒、注意防晒,别晒伤。", fact: "维生素 D 靠晒太阳合成,它帮身体吸收钙。" },
  { field: "百科", title: "憋尿和憋便的坏处", body: "经常憋尿会增加膀胱和尿路感染、结石风险,长期还可能影响膀胱功能;憋便则容易导致便秘、痔疮。有感觉就及时去,别长时间硬憋,是对身体最简单的保养。", fact: "有尿意便意别硬憋,憋久伤膀胱和肠道。" },
  { field: "百科", title: "酒精没有「安全摄入量」", body: "过去常说少量饮酒有益,但近年研究普遍认为,从健康角度看酒精并不存在绝对安全的量,能少则少、能不喝更好。酒精是明确的致癌物之一,长期过量伤肝、伤胃、伤神经。", fact: "酒越少越好,没有所谓「有益的量」。" },
  { field: "百科", title: "吸烟与二手烟", body: "吸烟是肺癌等多种疾病的重要诱因，烟草烟雾含多种有害物和致癌物。二手烟同样有害，长期处于烟雾环境的人患病风险也会升高。戒烟任何时候开始都不晚，戒烟后身体会逐步修复。", fact: "二手烟一样伤身;戒烟越早越好,什么时候戒都有用。" },
  { field: "百科", title: "久视手机的「手机脖」", body: "低头看手机时,颈椎承受的压力远大于抬头时。长期低头易引起颈肩酸痛、僵硬。建议把手机举高到接近视线平齐,减少低头幅度,并经常做抬头、转颈的放松动作。", fact: "把手机举高到眼睛高度,少低头护颈椎。" },
  { field: "百科", title: "泡脚的好处与注意", body: "用 40℃ 左右温水泡脚 15—20 分钟,能促进血液循环、帮助放松和入睡。但水温不宜过高、时间不宜过长;糖尿病人、有脚部伤口或静脉曲张者要谨慎,最好遵医嘱。", fact: "泡脚水温约 40℃、15—20 分钟即可，别太烫太久。" },
  { field: "百科", title: "运动前要热身,运动后要拉伸", body: "运动前热身(如慢跑、活动关节)能让身体进入状态、减少拉伤;运动后拉伸能缓解肌肉紧张、减少酸痛。直接上强度或运动完立刻停下坐着,都容易受伤或加重不适。", fact: "热身防拉伤,拉伸缓酸痛，两头都别省。" },
  { field: "百科", title: "情绪也会影响身体健康", body: "长期焦虑、压力大、情绪压抑,会影响睡眠、消化、免疫，甚至诱发或加重身体疾病(身心是相互影响的)。学会倾诉、运动、规律作息、必要时寻求专业帮助,是健康管理的重要一环。", fact: "坏情绪真的会「致病」;心理健康也是健康。" },
  { field: "百科", title: "不要长期戴耳机大音量听", body: "长时间、大音量使用耳机会损伤听力,且损伤往往不可逆。建议遵循「60-60」原则:音量不超过最大的 60%,连续使用不超过 60 分钟。在嘈杂环境里为盖过噪音而调大音量尤其伤耳。", fact: "耳机 60-60 原则:音量≤60%、连续≤60 分钟。" },
  { field: "百科", title: "体检该重视哪些", body: "定期体检能早发现问题。常规关注血压、血糖、血脂、体重;成年人应了解自己的基础指标。有家族病史、年龄增长后,相应的专项检查(如相关癌症筛查)也要按医生建议安排。", fact: "血压、血糖、血脂是最基础的「三高」监测项。" },
  { field: "百科", title: "BMI:判断胖瘦的常用指标", body: "BMI(身体质量指数)=体重(千克)÷身高(米)的平方。我国标准:18.5—23.9 为正常,24—27.9 为超重,28 及以上为肥胖。它是粗略参考,肌肉发达者会偏高,还需结合腰围等看。", fact: "BMI=体重÷身高²;18.5—23.9 为正常。" },
  { field: "百科", title: "午睡别超过半小时", body: "适当午睡能恢复精力,但睡太久(超过 30 分钟)容易进入深睡,醒来反而更困、头昏,还可能影响晚上入睡。建议午睡控制在 20—30 分钟,趴睡要垫高避免压迫手臂和眼睛。", fact: "午睡 20—30 分钟最提神;睡太久越睡越困。" },
  { field: "百科", title: "便秘怎么改善", body: "改善便秘要多吃富含膳食纤维的蔬菜水果和全谷物、多喝水、多活动,并养成定时排便习惯。长期靠泻药不是办法。若便秘突然加重或伴随便血、消瘦等,要及时就医排查。", fact: "多纤维+多喝水+多运动,是通便三件套。" },
  { field: "百科", title: "眼睛干涩可能是眨眼太少", body: "专注看屏幕时,人眨眼次数会明显减少,泪膜蒸发,眼睛就发干发涩。有意识地多眨眼、适当远眺、保持环境湿润,都能缓解。长期严重干眼要看眼科,别乱滴眼药水。", fact: "盯屏幕时眨眼变少,多眨眼能缓解干涩。" },
  { field: "百科", title: "洗澡水不是越热越好", body: "水温过高会带走皮肤表面油脂,使皮肤干燥、瘙痒,还会使血管扩张,老人、心脑血管疾病者久泡热水澡可能头晕。建议水温 38—40℃、时间别太长,冬天尤其注意洗后保湿。", fact: "洗澡水 38—40℃ 刚好;太烫伤皮肤还可能头晕。" },
  { field: "百科", title: "指甲上的「月牙」说明不了健康", body: "指甲根部的白色月牙(甲半月)是新长出的指甲,有没有、大不大主要和个人体质、指甲生长速度有关,并不能据此判断身体好坏或缺什么。网上「看月牙知健康」多为误传。", fact: "月牙多少≠身体好坏,别信「看月牙诊病」。" },
  { field: "百科", title: "打喷嚏不要捂紧嘴鼻憋回去", body: "强行憋住喷嚏,气流无处释放,可能冲击耳膜、鼻窦，极端情况下有伤及脆弱部位的风险。正确做法是用纸巾或手肘内侧遮挡,让喷嚏打出来,既卫生又安全。", fact: "喷嚏别硬憋,用手肘内侧挡着打出来。" },
  { field: "百科", title: "腰痛时别一直卧床不动", body: "一般性腰痛(非外伤、无严重症状)时,长期绝对卧床反而不利恢复,适度活动、维持日常轻度运动更有助康复。但若腰痛伴随腿麻、无力、大小便异常,要立即就医。", fact: "普通腰痛适度活动比一直躺着恢复快。" },
  { field: "百科", title: "正确擤鼻涕的方法", body: "两个鼻孔一起用力猛擤,压力可能把鼻涕和病菌挤向耳朵(咽鼓管),引发中耳炎。正确做法是按住一侧鼻孔、轻轻擤另一侧,交替进行,力度别太猛。", fact: "一次擤一侧鼻孔,别两边一起猛擤。" },
  { field: "百科", title: "空腹不宜做的几件事", body: "空腹时血糖偏低,不宜立刻剧烈运动(易头晕);也不建议空腹大量喝浓茶、浓咖啡(刺激肠胃)。但「空腹不能吃香蕉、喝牛奶」等说法多为谣言,健康人不必过度担心。", fact: "空腹别剧烈运动、别猛灌浓茶咖啡;空腹喝牛奶没问题。" },
  { field: "百科", title: "多出汗不等于多排毒", body: "出汗主要是身体调节体温的方式,汗液里 99% 是水,只有极少量代谢物,「出汗排毒」「暴汗减肥」是误解。靠疯狂出汗减掉的多是水分,补水后就回来了。真正减脂靠的是长期热量差。", fact: "出汗是散热,不是排毒;暴汗掉的是水不是脂肪。" },
  { field: "百科", title: "鼻血怎么正确止", body: "流鼻血时应身体稍前倾、低头,用手指捏紧鼻翼(鼻子软的部分)10—15 分钟,可同时冷敷鼻梁。切忌仰头——仰头会让血倒流进喉咙,引起呛咳甚至误吸。", fact: "流鼻血要低头捏鼻翼,千万别仰头。" },
  { field: "百科", title: "眼睛进了异物别使劲揉", body: "灰尘、小虫进眼时用力揉,可能划伤角膜。正确做法是眨眼让泪水冲出,或用干净清水冲洗。若是尖锐异物扎入或冲洗无效、持续疼痛,不要自行乱弄,尽快就医。", fact: "眼进异物别揉,靠眨眼流泪或清水冲。" },
  { field: "百科", title: "久坐起身头晕(体位性低血压)", body: "蹲久了或躺久了猛地站起来,有时会眼前发黑、头晕,这是血压一时跟不上(体位性低血压)。起身慢一点、先坐一会儿再站,能避免。若频繁发生或伴心慌,建议就医。", fact: "起身慢一点,能避免「蹲久站起黑一下」。" },
  { field: "百科", title: "热敷和冷敷怎么选", body: "急性扭伤、撞伤的 24—48 小时内用冷敷,能收缩血管、减轻肿胀和疼痛;之后或慢性酸痛、肌肉僵硬用热敷,促进血液循环帮助恢复。用反了(新伤热敷)会加重肿胀。", fact: "新伤先冷敷(消肿),旧伤用热敷(活血)。" },
  { field: "百科", title: "口腔溃疡多数会自愈", body: "普通口腔溃疡多与疲劳、上火、局部摩擦、缺乏维生素等有关,一般 1—2 周自愈,保持口腔清洁、清淡饮食即可。但同一位置的溃疡若超过 2—3 周不愈,要及时就医排查。", fact: "溃疡超过 2—3 周不好,别拖,去看医生。" },
  { field: "百科", title: "指甲和头发的生长速度", body: "指甲平均每月长约 3 毫米,脚指甲更慢;头发平均每月长约 1 厘米。所以剪坏的发型要恢复、受损的指甲要长出来,都需要耐心等待,没有快速办法。它们生长快慢也受季节、营养影响。", fact: "头发月长约 1 厘米,指甲约 3 毫米,急不来。" },

  // ========== 生活百科 · 安全急救(40) ==========
  { field: "百科", title: "烫伤后第一时间:冲冷水", body: "小面积烫伤的正确处理是「冲、脱、泡、盖、送」:立即用流动凉水冲 15—20 分钟降温,再小心脱去衣物(粘住就别硬撕),继续泡凉水,用干净布覆盖,严重时送医。切忌抹牙膏、酱油、香油。", fact: "烫伤先冲凉水 15—20 分钟,别抹牙膏酱油。" },
  { field: "百科", title: "鱼刺卡喉别吞饭团、别喝醋", body: "吞饭团、馒头可能把鱼刺推得更深、扎得更牢;喝醋停留时间太短也软化不了刺。正确做法:停止进食,轻咳试着咳出;看得见的浅处可小心夹出;弄不出或刺较大、疼痛明显,尽快去医院。", fact: "卡鱼刺别硬吞饭,弄不出就去医院。" },
  { field: "百科", title: "噎住了用海姆立克急救法", body: "食物卡住气管、无法说话呼吸时,对成人可用海姆立克法:从背后抱住,一手握拳抵住肚脐稍上方,另一手包住,快速向内上方冲击,重复直到异物排出。婴儿则用拍背压胸法。这是救命技能。", fact: "噎住不能呼吸时,海姆立克法(肚脐上方快速上顶)。" },
  { field: "百科", title: "触电先断电,别直接去拉人", body: "发现有人触电,切勿徒手去拉,否则自己也会触电。应第一时间切断电源(拉闸、拔插头),或用干燥木棍、塑料等绝缘物挑开电线,再施救、呼叫急救。救人的前提是先保证自己安全。", fact: "触电先断电;别用手直接拉触电的人。" },
  { field: "百科", title: "火灾逃生:弯腰捂口鼻、别坐电梯", body: "火灾中多数伤亡源于浓烟。逃生时用湿毛巾捂住口鼻、弯腰低姿沿墙快速撤离,因为烟雾向上、低处空气相对清新。绝不能乘电梯(可能断电困住)。门把手烫说明门外有火,不要贸然开门。", fact: "火灾捂鼻弯腰走楼梯,千万别坐电梯。" },
  { field: "百科", title: "闻到煤气味:别开灯、别打电话", body: "怀疑天然气/煤气泄漏时,任何电火花都可能引爆。应立即关闭气阀、打开门窗通风,迅速离开,到室外安全处再打电话报修报警。切勿在室内开灯、关灯、打电话、使用任何电器或明火。", fact: "疑似漏气:关阀开窗走人,室内不碰任何电器开关。" },
  { field: "百科", title: "流鼻血低头、扭伤冷敷(急救口诀)", body: "两个常被做错的小急救:流鼻血要低头、捏住鼻翼,不是仰头(仰头血倒流);刚崴脚、撞伤的头两天要冷敷消肿,不是热敷或立刻揉搓。记住这两点能少受很多罪。", fact: "鼻血低头捏鼻翼;新崴脚先冷敷别揉。" },
  { field: "百科", title: "心肺复苏(CPR)能救命", body: "有人突然倒地、没有呼吸和心跳时,在等待急救车期间进行心肺复苏能大大提高存活率。按压胸部中央(两乳头连线中点),用力快速按压,频率约每分钟 100—120 次、深度 5—6 厘米。有条件尽快用 AED。", fact: "CPR 按压:胸部中央,每分钟 100—120 次。" },
  { field: "百科", title: "AED 是「傻瓜式」救命设备", body: "AED(自动体外除颤仪)在许多公共场所都有配置,遇到心脏骤停能自动分析心律并语音指导操作,普通人也能用。按语音提示贴电极、听指令即可,不会在不该放电时放电。关键时刻别怕用。", fact: "公共场所的 AED 有语音指导,普通人也能用。" },
  { field: "百科", title: "溺水者上岸后不是先「控水」", body: "传统倒挂控水、拍背控水会耽误抢救、增加呛咳误吸。溺水者上岸若无呼吸,应尽快清理口鼻异物并立即心肺复苏、呼叫急救。控水不仅没用,还可能把胃内容物呛入肺里。", fact: "溺水救上来别忙着控水,没呼吸就直接做 CPR。" },
  { field: "百科", title: "中暑了要赶紧降温", body: "高温下出现头晕、恶心、大量出汗、体温升高,可能是中暑。应立即转移到阴凉通风处、松开衣物、用湿毛巾擦拭或扇风降温、补充含盐分的水。若出现意识模糊、高热不退(热射病),立即送医,这是急症。", fact: "中暑快到阴凉处降温补水;意识不清要立刻送医。" },
  { field: "百科", title: "低血糖:赶紧吃点糖", body: "糖尿病人或空腹过度时出现心慌、手抖、冒冷汗、头晕,可能是低血糖,应立即吃含糖食物(糖果、果汁、饼干)。低血糖发作比高血糖更凶险,严重会昏迷。随身带点糖对易低血糖者很重要。", fact: "低血糖(心慌手抖冒汗)马上吃糖,别硬扛。" },
  { field: "百科", title: "被猫狗咬抓伤要及时处理", body: "被猫狗抓咬出血或破皮,应尽快用肥皂水和流动清水反复冲洗伤口 15 分钟以上,再消毒,并尽早到医院评估是否接种狂犬疫苗。狂犬病一旦发病几乎无法救治,但可防可控,关键是及时处理。", fact: "猫狗咬伤:肥皂水冲 15 分钟,尽快去打疫苗。" },
  { field: "百科", title: "被马蜂蜇了别乱挤", body: "被蜂蜇后,蜜蜂的刺可能留在皮肤里,应轻轻刮出(别用手挤,以免挤入更多毒液),再清洗冷敷。若被群蜂攻击、出现呼吸困难、全身皮疹等过敏反应,是急症,立即就医。", fact: "蜂蜇别挤,刮出毒刺;若呼吸困难立即就医。" },
  { field: "百科", title: "异物入眼、入耳的处理", body: "眼睛进异物靠眨眼流泪或清水冲,别揉;耳朵进小虫可用灯光诱出或滴几滴食用油让虫浮出,别用尖物乱掏,以免捅伤耳道和鼓膜。处理不了都应及时就医。", fact: "耳朵进虫滴点油让它浮出,别拿尖东西掏。" },
  { field: "百科", title: "割伤出血怎么止", body: "一般割伤:用干净纱布或布直接压住伤口持续按压止血,抬高受伤部位。多数小伤口按压几分钟能止住。若血呈喷射状、按压不住或伤口很深,持续加压并尽快就医,别反复松开查看。", fact: "出血先用布直接按压伤口,抬高患处。" },
  { field: "百科", title: "骨折或疑似骨折不要乱动", body: "怀疑骨折时(剧痛、畸形、不能活动),不要随意搬动或试图「掰正」,以免二次损伤。应就地固定(用木板、硬物临时制动),尽量减少移动,呼叫急救或小心送医。脊柱受伤者尤其不能随意搬动。", fact: "疑似骨折别乱搬乱掰,固定好再送医。" },
  { field: "百科", title: "家里常备小药箱该有什么", body: "基础家庭药箱建议备:创可贴、纱布、医用胶带、碘伏(消毒)、体温计、退烧止痛药、口服补液盐、创伤用的无菌棉签等。定期检查有效期,过期药品要清理。药品放在孩子够不到的地方。", fact: "药箱基础款:创可贴、碘伏、体温计、退烧药。" },
  { field: "百科", title: "药品过期了不能吃", body: "过期药品有效成分可能降解、失效,甚至产生有害物质,吃了可能延误病情或伤身。应定期清理过期药,且不要随意丢进垃圾桶或马桶(污染环境),很多地方的药店或社区设有过期药回收点。", fact: "过期药别吃也别乱扔,找回收点处理。" },
  { field: "百科", title: "退烧药不能和复方感冒药叠加吃", body: "很多复方感冒药里本身就含有退烧止痛成分(如对乙酰氨基酚)。如果再单独吃退烧药,容易成分重复、过量,伤肝。吃药前看清成分表,同类成分别叠加,不确定时问医生或药师。", fact: "吃感冒药再加退烧药,当心成分重复过量伤肝。" },
  { field: "百科", title: "儿童误服药物/异物", body: "孩子误吞药片、纽扣电池、小磁珠等很危险(纽扣电池、磁珠尤其凶险,可能灼伤或穿孔肠道)。发现后不要自行催吐乱处理,尽快带着误服的东西或包装去医院。预防最关键:危险物品收好锁好。", fact: "孩子误吞纽扣电池/磁珠,立刻就医,别拖。" },
  { field: "百科", title: "一氧化碳中毒(煤气中毒)", body: "门窗紧闭用燃气热水器洗澡、烧炭取暖,易一氧化碳中毒,出现头晕、乏力、恶心,严重会昏迷,且无色无味难察觉。预防靠通风、装报警器。发现有人中毒,立即开窗、把人转移到通风处并呼叫急救。", fact: "烧炭、燃气洗澡要通风;煤气中毒先开窗转移人。" },
  { field: "百科", title: "急救电话要记牢", body: "我国急救电话 120(医疗急救)、火警 119、匪警 110、交通事故 122。打急救电话时要说清地点(越具体越好)、病人情况、人数,并保持电话畅通等待指引,别先挂。关键时刻信息准确能争取时间。", fact: "医疗急救打 120;说清地点和病情,别先挂电话。" },
  { field: "百科", title: "扭伤的 RICE 原则", body: "崴脚、扭伤后 48 小时内遵循 RICE:Rest 休息、Ice 冰敷、Compression 加压包扎、Elevation 抬高患处。能有效减轻肿胀疼痛。别急着热敷、揉搓或继续走动,那样会加重肿胀。", fact: "扭伤 RICE:休息、冰敷、加压、抬高。" },
  { field: "百科", title: "开水、热汤烫伤孩子最常见", body: "幼儿烫伤多因打翻热水杯、热汤、热粥。预防:热饮热汤别放桌边,别抱着孩子端热水,热水瓶、电热水壶放到够不到处。真烫到了,立刻冲凉水降温再就医,别信偏方。", fact: "热汤热水远离桌边和孩子;烫到先冲凉水。" },
  { field: "百科", title: "家里插座、电器用电安全", body: "湿手不要插拔电器和触碰开关;插座别超负荷(多个大功率电器挤一个插排);电器冒烟、有焦味立即断电。浴室等潮湿处用电尤其小心。离家或睡前检查大功率电器是否关闭。", fact: "湿手别碰电;插排别挤太多大功率电器。" },
  { field: "百科", title: "阳台、窗户防儿童坠落", body: "孩子坠楼事故多因攀爬窗台、阳台。预防:窗户装限位器或防护栏,窗边、阳台不要放可攀爬的桌椅、箱子,别把孩子单独留在能接触窗户的房间。安全防护比事后后悔重要得多。", fact: "窗边别放能爬的凳子桌子;装好防护栏。" },
  { field: "百科", title: "遇到地震怎么办", body: "室内遇地震,就近躲到坚固桌子下或承重墙墙角,护住头颈,远离窗户和吊挂物,等晃动停止再有序撤离,别慌乱跳楼或挤电梯。身处室外则远离建筑、电线杆。「震时就近躲、震后快疏散」。", fact: "地震先就近躲(桌下/墙角护头),停了再撤。" },
  { field: "百科", title: "食物中毒的处理", body: "吃了变质或不洁食物后出现呕吐、腹泻、腹痛,多为食物中毒。症状轻可多喝水(或口服补液盐)防脱水、清淡饮食观察;若剧烈呕吐腹泻、脱水、发热、便血或多人同时发病,尽快就医并保留可疑食物。", fact: "食物中毒先补水防脱水;严重或多人发病要就医。" },
  { field: "百科", title: "被热油溅到、起火别用水浇", body: "厨房油锅起火,千万不能泼水(高温油遇水会炸开、火势更猛)。应立即关火,用锅盖盖住隔绝空气灭火,或用灭火毯。平时炒菜油别放太满、人别离开灶台。被热油溅到小面积烫伤按冲凉水处理。", fact: "油锅起火盖锅盖灭火,绝对不能泼水。" },
  { field: "百科", title: "宠物、孩子别单独留车内", body: "夏天封闭车内温度可在十几分钟内飙升到致命程度,把孩子或宠物单独留在车里极其危险,可能导致热射病甚至死亡。哪怕只是「下车一会儿」也不行,开窗一条缝也挡不住高温。", fact: "再热的天,也别把孩子宠物单独留车里。" },
  { field: "百科", title: "泡澡、桑拿时间别太长", body: "长时间泡热水澡或蒸桑拿,会使血管扩张、血压下降,可能头晕、乏力甚至晕厥,尤其老人和心脑血管疾病者风险更高。感觉不适要立即离开、到通风处休息。别空腹或酒后泡澡蒸桑拿。", fact: "泡澡桑拿别太久;头晕立刻出来,别空腹酒后进。" },
  { field: "百科", title: "高楼火灾不盲目往下冲", body: "高层起火时,若楼道已被浓烟封锁,盲目下冲可能被烟熏倒。此时应退回房间,用湿毛巾、湿布堵住门缝,到朝外的窗口或阳台呼救、等待救援。是否逃生要根据火势和烟雾判断,不是一味往外冲。", fact: "高楼起火楼道全是烟时,退回房间堵门缝等救援。" },
  { field: "百科", title: "眼睛被化学品溅到立刻冲水", body: "清洁剂、消毒液等溅入眼睛,要第一时间用大量清水持续冲洗至少 15 分钟（翻开眼皮冲),越快越好,然后尽快就医。冲洗是减轻损伤的关键,别犹豫找「专用药水」而耽误时间。", fact: "化学品溅眼,立刻大量清水冲 15 分钟再就医。" },
  { field: "百科", title: "独居老人、独处时的安全", body: "独居或独自在家时,手机放在随手能拿到处,存好紧急联系人;浴室地面防滑、可装扶手;煤气、电器用完及时关。和家人约定定时联系。这些准备能在突发状况时争取宝贵的求助时间。", fact: "独处时手机随身带、存急救联系人,浴室防滑。" },
  { field: "百科", title: "服药别就着茶、果汁、酒", body: "部分药物与茶、咖啡、果汁(尤其西柚汁)、牛奶、酒同服会影响药效或产生风险。最稳妥是用温白开水送服。具体某种药能不能就着什么喝,看说明书或问药师,别想当然。", fact: "吃药最好用温白开水送,别就着茶酒果汁。" },
  { field: "百科", title: "晕倒、晕厥者的处理", body: "有人突然晕倒,先判断有没有呼吸意识:有呼吸的让其平躺、抬高双腿、松开衣领,通常很快会缓解;若没有呼吸心跳则立即 CPR 并呼叫急救。别急着猛掐人中或强行灌水,以免呛到。", fact: "晕倒者有呼吸就平躺抬腿;没呼吸立即 CPR。" },
  { field: "百科", title: "过敏严重会危及生命", body: "有些人对食物(花生、海鲜)、药物、蜂毒等严重过敏,可能迅速出现呼吸困难、喉头水肿、休克(过敏性休克),这是急症。已知严重过敏者应随身带急救药并告知身边人,发作时立即就医。", fact: "严重过敏(喘不上气、休克)是急症,立刻送医。" },
  { field: "百科", title: "烟雾报警器是便宜的救命投资", body: "火灾致命往往在夜间睡梦中,烟雾报警器能在浓烟扩散时及时报警叫醒人。它便宜、好装,是性价比极高的家庭安全设备。装上后定期测试、及时换电池,别让它成了摆设。", fact: "家里装个烟雾报警器,几十块能救命。" },
  { field: "百科", title: "遇到诈骗电话、短信怎么办", body: "凡是自称公检法要你转账、「保证金」「刷单返利」、索要验证码的,基本都是诈骗。记住:不轻信、不透露、不转账,可挂断后拨打官方电话核实,或拨 96110 反诈专线。个人信息和验证码绝不给陌生人。", fact: "凡是让转账、要验证码的陌生来电,基本是诈骗。" },

  // ========== 生活百科 · 生活窍门(40) ==========
  { field: "百科", title: "衣服染色、沾油渍怎么办", body: "新沾的油渍可先撒点淀粉或滑石粉吸油,再用洗洁精涂抹揉搓后清洗;圆珠笔油可用酒精;果汁、红酒渍趁新鲜用盐或苏打水处理。关键是趁早处理、别用热水烫(很多污渍遇热会固定住更难洗)。", fact: "油渍先用洗洁精,很多污渍别先用热水(会固定)。" },
  { field: "百科", title: "冰箱不是保险箱", body: "冰箱只能延缓细菌繁殖,不能杀菌。剩饭剩菜放凉后尽快冷藏、两天内吃完并彻底加热;生熟要分开放(熟食在上、生食在下)避免交叉污染。冰箱要定期清理,别塞太满影响制冷。", fact: "冰箱只延缓变质不杀菌;生熟分开、剩菜尽快吃。" },
  { field: "百科", title: "食物冷藏、冷冻的分区", body: "冷藏室上层放熟食剩菜,下层放生肉(防血水滴落),抽屉放蔬果;冷冻室存肉类、速冻食品。鸡蛋其实不建议放门上(温度波动大),放里面更稳。热的食物稍微放凉再进冰箱,别直接塞进去。", fact: "生肉放下层防滴血水;鸡蛋放里面别放门上。" },
  { field: "百科", title: "微波炉加热的注意事项", body: "带壳鸡蛋、密封容器不能直接进微波炉(会爆);金属、带金边的餐具会打火。加热汤水时中途搅拌,避免「暴沸」。用微波炉专用容器,保鲜膜留口透气。热完取出小心烫,容器可能不烫但食物很烫。", fact: "鸡蛋、金属、密封罐别进微波炉。" },
  { field: "百科", title: "怎样让切开的水果不氧化变黑", body: "苹果、梨、牛油果等切开后会氧化变褐。泡一下淡盐水或滴几滴柠檬汁(酸性抑制氧化),或用保鲜膜贴紧切面隔绝空气,都能延缓变色。这不影响食用安全,主要是卖相问题。", fact: "切开的苹果泡淡盐水/滴柠檬汁,不易变黑。" },
  { field: "百科", title: "下水道、厨房异味怎么除", body: "下水道异味可定期倒入小苏打再冲热水(或加白醋),帮助分解油污异味;冰箱异味放一小盒小苏打或活性炭吸附。垃圾桶底垫张报纸、勤倒勤洗。很多异味问题靠「勤清理+小苏打」就能解决。", fact: "小苏打是除味小能手:下水道、冰箱都能用。" },
  { field: "百科", title: "白醋和小苏打的妙用", body: "白醋能除水垢(烧水壶、花洒泡醋)、去异味;小苏打能去油污、除味、辅助清洁。但两者不要指望「万能」,也别和含氯的洁厕灵、消毒液混用(可能产生有害气体)。分开用,安全又好使。", fact: "白醋除水垢、小苏打去油污;别和含氯清洁剂混用。" },
  { field: "百科", title: "清洁剂千万别混用", body: "洁厕灵(含酸)和 84 消毒液/漂白水(含氯)混在一起会产生有毒的氯气,可能致命。不同清洁剂不要混用,用完一种充分冲洗再用另一种。使用含氯消毒剂时保持通风。这是厨卫安全的重要一条。", fact: "洁厕灵 + 84 消毒液 = 有毒氯气,绝不能混!" },
  { field: "百科", title: "羽绒服、毛衣的清洗收纳", body: "羽绒服多可机洗(放网袋、少量中性洗剂),洗后充分漂净、拍松晾干恢复蓬松;毛衣要用冷水、平铺晾干,别挂起来(会被拉变形)。收纳前务必彻底晾干,潮气会发霉长虫。", fact: "毛衣平铺晾别挂(防变形);收纳前一定要晾干。" },
  { field: "百科", title: "怎么防衣柜生虫、发霉", body: "衣柜防潮防虫:放干燥剂或竹炭包吸潮,樟脑丸/天然樟木防虫(但樟脑丸别直接接触衣物、孕妇婴儿房慎用)。衣物洗净晾干再收,梅雨季多开柜通风。真丝、羊毛这类天然纤维更招虫,重点防护。", fact: "衣物收前晾透;放干燥剂防霉、樟木防虫。" },
  { field: "百科", title: "鞋子有异味怎么办", body: "鞋臭多因潮湿滋生细菌。可把鞋彻底晾干、塞干燥的纸团或茶包、小苏打吸潮除味;鞋垫勤换勤洗;两双鞋换着穿给鞋「休息」透气。保持脚部干爽、袜子勤换,是治本之道。", fact: "鞋里塞点小苏打/茶包除味,两双换着穿更透气。" },
  { field: "百科", title: "省电的小习惯", body: "空调温度调高 1℃ 可明显省电(夏天 26℃ 左右较适宜);电器待机也耗电,长时间不用拔插头或用开关插排;冰箱别塞太满、也别太空;用节能灯。这些小习惯累积起来,电费能省下不少。", fact: "空调调高 1℃ 省电;待机电器也耗电,记得断电。" },
  { field: "百科", title: "省水的小窍门", body: "淘米水、洗菜水可用来浇花、冲厕所;洗澡时抹沐浴露先关水;马桶水箱放一瓶装满水的瓶子可减少每次冲水量;及时修好滴漏的水龙头(一个滴水龙头一天能漏掉不少水)。积少成多。", fact: "淘米水洗菜水别倒,浇花冲厕都行。" },
  { field: "百科", title: "怎么让毛巾恢复柔软", body: "毛巾用久变硬,多是水垢和洗涤剂残留所致。可用温水加少量白醋浸泡后清洗,或洗时少放柔顺剂(柔顺剂反而会降低吸水性)。洗后充分晾干、别长期潮着放,能保持松软和吸水。", fact: "毛巾变硬用白醋泡;柔顺剂别放多(会降低吸水)。" },
  { field: "百科", title: "切洋葱不流泪的办法", body: "洋葱被切开会释放刺激性气体让人流泪。可以把洋葱先冷藏一会儿再切(低温减少气体挥发)、刀蘸点水、开着抽油烟机或旁边放盆水、用锋利的刀快切。戴个泳镜当然也管用,就是有点好笑。", fact: "切洋葱前先冷藏、用快刀,能少流泪。" },
  { field: "百科", title: "大蒜快速剥皮", body: "整头大蒜放微波炉叮十几秒,或装进带盖的罐子/两个碗扣起来用力摇晃几十秒,蒜皮就容易脱落。单瓣可用刀面拍一下,皮就裂开好剥。这些小技巧能省下剥蒜的烦躁时间。", fact: "大蒜放罐里使劲摇,皮就松了好剥。" },
  { field: "百科", title: "保鲜膜、保鲜袋的正确用法", body: "保鲜膜贴紧食物表面隔绝空气效果最好;但高油、高糖食物微波加热时别让保鲜膜直接接触食物。蔬菜用保鲜袋时留点透气口,全密封反而易捂烂。生熟食物分开包装,避免串味和交叉污染。", fact: "保鲜膜贴紧食物最保鲜;微波时别直接贴高油食物。" },
  { field: "百科", title: "面包、馒头怎么保存", body: "面包常温只能放两三天,放冷藏反而容易变干变硬(淀粉老化加快);吃不完最好冷冻,吃时取出回温或加热即可,口感接近新鲜。馒头同理,一次多做可冷冻保存。常温久放会发霉,别舍不得扔。", fact: "面包馒头吃不完要冷冻,别冷藏(冷藏更易变硬)。" },
  { field: "百科", title: "怎么判断鸡蛋还新不新鲜", body: "把鸡蛋放进清水里:平躺沉底的最新鲜;大头朝上立起来的放了有段时间,还能吃;浮起来的说明内部变质产生气体,别吃了。这是因为鸡蛋存放越久、内部气室越大,浮力越大。", fact: "鸡蛋放水里:沉底新鲜,浮起来的别吃。" },
  { field: "百科", title: "蔬菜水果怎么保存更久", body: "叶菜用厨房纸包住吸潮、装袋冷藏;番茄、土豆、洋葱、香蕉常温阴凉存放,别冷藏;土豆和洋葱别放一起(互相催熟发芽)。多数水果和蔬菜分开放,避免乙烯催熟导致一起坏得快。", fact: "土豆洋葱别放一起;番茄香蕉别冷藏。" },
  { field: "百科", title: "食用油要避光密封保存", body: "食用油长期见光、接触空气、靠近灶台高温,容易氧化变质(产生哈喇味)。应放在阴凉避光处、用后拧紧盖子,别买太大桶一时用不完。开封后尽量几个月内用掉。有哈喇味的油别再吃。", fact: "食用油避光密封放,别靠灶台;有哈喇味就别吃了。" },
  { field: "百科", title: "怎样快速冷却热饮", body: "想让一杯热水/热饮快点变凉,可把杯子放进加了冰块和盐的水里转一转(盐让冰水温度更低),比单纯放冰水快;或换到金属容器里(导热快)。心急时别直接猛加冷水稀释口感。", fact: "热饮放进「冰水+盐」里转,凉得更快。" },
  { field: "百科", title: "衣物晾晒的小技巧", body: "深色衣物反面晒防褪色;针织、毛衣平铺晾防变形;衬衫、外套用衣架晾减少褶皱。阳光有一定杀菌除味作用,但贴身衣物暴晒后纤维易变硬发黄,阴凉通风处晾更护衣。晾干再收,防霉防味。", fact: "深色衣服反面晒防褪色;毛衣平铺别挂。" },
  { field: "百科", title: "怎么去除衣服上的口香糖", body: "粘上口香糖别硬抠。可把衣物装袋放冷冻室冻硬,口香糖变脆后一掰就掉;残留的用冰块敷硬后刮除,再处理痕迹。热反而让它更黏,所以关键是「冻」而不是「烫」。", fact: "口香糖粘衣服,冷冻冻硬了再刮掉。" },
  { field: "百科", title: "家里来小飞虫、果蝇怎么办", body: "果蝇多被熟透水果、湿垃圾吸引。对策:水果吃完或冷藏、垃圾勤倒、下水道盖好;可用一个小碗装点醋加几滴洗洁精诱捕(醋吸引、洗洁精破坏表面张力让虫落水)。治本还是保持厨房干净干燥。", fact: "醋 + 几滴洗洁精能诱捕果蝇;保持厨房干净是根本。" },
  { field: "百科", title: "新买的衣服最好先洗再穿", body: "新衣服在生产、运输、试穿过程中可能残留染料、甲醛(防皱定型用)和细菌。贴身衣物尤其建议下水洗一遍再穿,能洗掉部分残留化学物质和浮色,降低皮肤刺激和过敏风险。", fact: "新衣服(尤其贴身的)先洗一遍再穿。" },
  { field: "百科", title: "电器清灰、散热要重视", body: "电脑、电视、路由器、插排积灰会影响散热甚至引发故障或火灾隐患。定期用干布或小刷子清理散热口,别用湿布直接擦通电电器。电器周围留散热空间,别盖东西、别挤在密闭柜里长时间运行。", fact: "电器散热口定期清灰,别捂着用。" },
  { field: "百科", title: "怎样系牢鞋带不易松", body: "系鞋带爱松,可以多绕一圈打「双结」,或学「鞋带不松结」(系好后把两个耳朵再互相穿一次)。跑步、运动前检查鞋带系牢,能避免半路散开绊倒。小技巧,日常很实用。", fact: "鞋带爱松就打双结,运动前检查系牢。" },
  { field: "百科", title: "手机进水的紧急处理", body: "手机进水后立即关机(别开机测试,防短路)、擦干、取出能拆的卡,放到通风处或埋进干燥剂(别用吹风机热风吹,别放大米里——效果有限还可能进碎屑)。尽快送修检测,别急着充电。", fact: "手机进水先关机擦干,别开机别充电,尽快送修。" },
  { field: "百科", title: "怎么快速整理行李更省空间", body: "衣物卷起来(而不是叠)更省空间、还不易皱;用收纳袋/压缩袋分类装;鞋子装袋放两侧、里面塞袜子利用空间;重物放底部靠轮子侧。清单列一遍避免漏带。卷衣法是行李打包的实用神器。", fact: "衣服卷起来装,比叠更省空间还防皱。" },
  { field: "百科", title: "镜子、玻璃擦得更亮", body: "擦玻璃镜子容易留水痕,可用报纸或专用超细纤维布擦,或喷点稀释白醋水再擦;最后用干布或旧报纸收尾去除水痕。别在大太阳下擦(水干太快留痕)。窍门在「少水、用对布、及时擦干」。", fact: "擦玻璃用报纸/纤维布 + 稀醋水,不留水痕。" },
  { field: "百科", title: "怎么让室内空气更清新", body: "改善室内空气最有效的是开窗通风(哪怕冬天也要定时换气)。养些绿植有一定辅助作用但别神话。新装修的房子注意甲醛,多通风、必要时检测。香薰、空气清新剂只是掩盖气味,不能净化空气。", fact: "通风是净化空气最有效的办法,香薰只是遮味。" },
  { field: "百科", title: "怎么防止镜子、挡风玻璃起雾", body: "浴室镜子、冬天车窗、眼镜容易起雾。可在镜面涂一点点洗洁精或洗发水薄薄抹开擦匀,形成防雾膜;眼镜起雾也能这样处理。原理是降低水的表面张力,让雾气不结成小水珠。", fact: "镜面抹层薄洗洁精,能防起雾。" },
  { field: "百科", title: "怎样减少塑料袋、做好垃圾分类", body: "自带购物袋、重复利用快递箱,能减少塑料浪费。垃圾分类一般分可回收物、厨余(湿)垃圾、有害垃圾、其他(干)垃圾;电池、过期药、灯管属有害垃圾要单独投。分类标准各地略有不同,按当地来。", fact: "电池、过期药、灯管是有害垃圾,要单独扔。" },
  { field: "百科", title: "怎样去除衣服上的汗渍、黄渍", body: "白衣领口、腋下的汗渍发黄,可在洗前用少量小苏打加水调成糊涂抹、或用专门的领洁净处理,静置一会儿再搓洗。陈年黄渍较顽固,趁新鲜处理最有效。别用含氯漂白剂处理彩色衣物(会掉色)。", fact: "汗渍黄渍趁新鲜用小苏打糊涂抹再洗。" },
  { field: "百科", title: "怎么判断食物还能不能吃", body: "闻气味(有酸味、臭味、哈喇味别吃)、看外观(发霉、变色、黏液)、看保质期。注意:面包等长霉后,肉眼看不见的菌丝可能已蔓延,整个都该扔,不是切掉霉点就行。拿不准时,「宁可扔掉别冒险」。", fact: "食物长霉别只切掉霉点,整个都该扔。" },
  { field: "百科", title: "怎样快速催熟或延缓水果成熟", body: "想让生硬的猕猴桃、牛油果、香蕉快点熟,和苹果一起装袋(苹果释放乙烯催熟);想放慢成熟就分开放、放阴凉处或冷藏。熟透的香蕉别和其它水果堆一起,会把旁边都催熟催坏。", fact: "想催熟水果,和苹果装一袋;想保鲜就分开放。" },
  { field: "百科", title: "怎样省力地拧开太紧的瓶盖", body: "瓶盖拧不开,可以用橡胶手套或干毛巾增加摩擦力;金属盖的玻璃瓶可用热水冲一下盖子(热胀冷缩让盖子松)、或用勺子沿盖边轻撬破真空。别硬较劲伤手,借点巧劲更轻松。", fact: "瓶盖太紧:垫毛巾增摩擦,或热水冲一下金属盖。" },
  { field: "百科", title: "怎样让插排、数据线不乱", body: "线材缠绕打结很烦。可用扎带、线夹、旧的面包袋夹子固定分类;给每根线贴个标签标明用途;插排固定在桌下或墙边。理线既好看又安全(减少绊倒和线材损坏),花一次工夫长期受益。", fact: "用扎带+标签理线,又整洁又安全。" },
  { field: "百科", title: "怎样延长鲜花、绿植的寿命", body: "鲜切花:斜剪花茎增大吸水面、去掉泡水部分的叶子(防腐烂)、每两天换水并加一点点糖;放阴凉处避免阳光直晒和空调直吹。绿植别浇水过勤(很多植物是浇死的),见干再浇。", fact: "鲜花斜剪花茎勤换水;绿植别浇太勤。" },

  // ========== 生活百科 · 饮食营养(40) ==========
  { field: "百科", title: "「食物相克」大多是谣言", body: "网上流传的「菠菜豆腐不能一起吃」「海鲜加维C会中毒」等绝大多数是夸大或谣言,正常食量下并不会中毒。真正要注意的是食材新鲜、烹饪熟透、个人过敏。与其担心相克,不如注意卫生和均衡。", fact: "绝大多数「食物相克」是谣言,别被吓到。" },
  { field: "百科", title: "膳食要讲究均衡搭配", body: "健康饮食的关键是多样和均衡:主食(最好部分粗粮)、蔬菜、水果、蛋白质(肉蛋奶豆)、适量油脂都要有。没有哪种单一食物是「超级食物」能包办健康,也没有哪种该被彻底妖魔化。搭配比纠结单品更重要。", fact: "没有超级食物也没有洪水猛兽,均衡搭配最重要。" },
  { field: "百科", title: "多吃蔬菜水果的好处", body: "蔬菜水果富含维生素、矿物质、膳食纤维和抗氧化物质,有助消化、预防便秘、降低多种慢性病风险。建议餐餐有蔬菜、天天有水果,且种类和颜色越丰富越好。果汁不能完全代替吃水果(损失纤维、糖分浓缩)。", fact: "水果别全榨汁喝,直接吃更营养(保留纤维)。" },
  { field: "百科", title: "粗粮杂粮要适量搭配", body: "全谷物、杂豆等粗粮富含纤维和B族维生素,比精米白面更有助控血糖、促肠道。但也不是越多越好,全吃粗粮会影响消化吸收、口感差难坚持。建议粗细搭配,粗粮占主食的三分之一到一半左右。", fact: "粗粮好但别全吃,占主食三分之一到一半。" },
  { field: "百科", title: "红肉、白肉与加工肉", body: "白肉(鱼、禽)脂肪相对健康,建议常吃;红肉(猪牛羊)适量吃;加工肉(香肠、培根、火腿)含盐和添加剂多,被列为较高风险,应少吃。换着吃、控制总量,比只吃一种或完全不吃更合理。", fact: "多吃鱼禽(白肉),少吃加工肉(香肠培根)。" },
  { field: "百科", title: "鸡蛋可以每天吃", body: "鸡蛋是优质蛋白来源,营养丰富。健康人每天吃一个鸡蛋(连蛋黄)是没问题的,蛋黄里的营养别浪费。关于「吃蛋黄升胆固醇」的担心,对多数健康人影响有限。关键还是整体饮食均衡。", fact: "健康人每天一个鸡蛋没问题,蛋黄别扔。" },
  { field: "百科", title: "牛奶、豆浆都是好蛋白来源", body: "牛奶富含钙和优质蛋白,豆浆富含植物蛋白,都是不错的选择,可以换着喝。乳糖不耐受的人喝牛奶腹胀腹泻,可改喝酸奶或无乳糖奶。空腹喝豆浆、牛奶对健康人没问题,「空腹不能喝」是误传。", fact: "牛奶豆浆都好;乳糖不耐受可换酸奶。" },
  { field: "百科", title: "怎么健康地选择烹饪方式", body: "蒸、煮、炖、凉拌等方式用油少、营养损失小,更健康;煎、炸、烤用油多、高温易产生有害物,应少用。控油控盐、少放糖,是家常菜更健康的关键。同样的食材,做法不同,健康程度差很多。", fact: "多蒸煮炖拌,少煎炸烤,控油控盐。" },
  { field: "百科", title: "反式脂肪要尽量少吃", body: "反式脂肪(常见于部分人造奶油、起酥油、油炸和烘焙食品)对心血管危害大。看配料表,出现「氢化植物油」「植脂末」「人造黄油」等要警惕。少吃植脂末奶茶、酥皮点心、油炸食品,对心脏更友好。", fact: "配料表有「氢化植物油」的,少吃。" },
  { field: "百科", title: "看懂食品配料表", body: "配料表按含量从多到少排列,排第一的就是最主要成分。比如某「果汁饮料」第一位是水、第二位是糖,说明果汁含量很少。想吃得明白,学会看配料表和营养成分表,比看广告词靠谱得多。", fact: "配料表按含量排序,排第一的最多。" },
  { field: "百科", title: "看懂营养成分表(看「每 100 克」)", body: "营养成分表标了能量、蛋白质、脂肪、碳水、钠等。注意单位:有的按「每份」标、有的按「每 100 克」,对比不同产品要换算成同一标准。钠含量高、脂肪高的要留意。NRV% 表示占每日需要量的百分比。", fact: "对比食品营养,统一看「每 100 克」才公平。" },
  { field: "百科", title: "「零脂肪」不等于「零热量」", body: "标「零脂肪」的食品可能含大量糖(如很多乳酸菌饮料);「无糖」的可能脂肪不低。商家宣传往往只强调对自己有利的一面。真想控制热量,要看整体营养成分和总能量,别被单一宣传词带偏。", fact: "「零脂肪」可能高糖,「无糖」可能高脂,看整体。" },
  { field: "百科", title: "含糖饮料的糖含量惊人", body: "一瓶 500 毫升的可乐含糖约 50 克,接近成人一天添加糖的上限。奶茶、果汁饮料、运动饮料含糖往往也不低。长期大量喝含糖饮料和肥胖、糖尿病、蛀牙都有关。口渴首选白开水。", fact: "一瓶可乐的糖≈一天上限;解渴首选白开水。" },
  { field: "百科", title: "咖啡、茶可以喝但别过量", body: "适量咖啡、茶(含咖啡因)能提神,对多数健康成年人无害,每天咖啡因别超过约 400 毫克(约 3—4 杯咖啡)。但睡前几小时别喝(影响睡眠)、孕妇和对咖啡因敏感者要节制。空腹大量喝浓茶咖啡刺激肠胃。", fact: "咖啡每天别超 3—4 杯;睡前几小时别喝。" },
  { field: "百科", title: "维生素该靠食物还是补剂", body: "对多数健康、饮食均衡的人,维生素和矿物质从日常食物中就能获得,不必额外吃补剂。盲目大量补充某些维生素(尤其脂溶性的A、D、E、K)反而可能过量中毒。确有缺乏应在医生指导下补。", fact: "饮食均衡就够了,别盲目大把吃维生素(可能过量)。" },
  { field: "百科", title: "膳食纤维的重要性", body: "膳食纤维虽不被吸收,却能促进肠道蠕动、预防便秘、帮助控血糖血脂、增加饱腹感。它主要来自蔬菜、水果、全谷物、豆类。现代人饮食偏精细,普遍纤维摄入不足,有意识多吃点粗粮蔬菜很有必要。", fact: "多吃蔬菜粗粮补纤维,通便又控糖控脂。" },
  { field: "百科", title: "优质蛋白从哪来", body: "优质蛋白指氨基酸组成接近人体需要、易吸收的蛋白,主要来自蛋、奶、鱼、瘦肉、大豆及其制品。每餐最好有一份蛋白质,有助维持肌肉、增强免疫。老人、术后、健身人群对蛋白需求更高。", fact: "优质蛋白:蛋奶鱼肉和大豆;每餐来一份。" },
  { field: "百科", title: "补钙:奶制品是好来源", body: "钙是骨骼健康的关键,最好的食物来源是奶及奶制品(牛奶、酸奶、奶酪),其次是豆制品、深绿色蔬菜、小鱼小虾。补钙同时需要维生素D帮助吸收(晒太阳、深海鱼)。光喝骨头汤补钙效果其实很有限。", fact: "补钙首选奶制品;喝骨头汤补钙其实没多少用。" },
  { field: "百科", title: "怎样健康吃早餐", body: "好早餐=主食(全麦面包、燕麦、杂粮粥)+蛋白质(鸡蛋、牛奶、豆浆)+一点蔬果,能提供上午稳定能量、避免昏沉和午餐暴食。只吃油条、只喝粥、或完全不吃都不够理想。再忙也尽量别省早餐。", fact: "好早餐:主食+蛋白质+蔬果,别只吃一样。" },
  { field: "百科", title: "晚餐宜清淡、别吃太晚太饱", body: "晚餐吃太饱、太油、太晚,会加重肠胃负担、影响睡眠,长期还易长胖。建议晚餐清淡、七八分饱,睡前2—3小时吃完。如果睡前实在饿,可少量吃点易消化的(如一杯牛奶),别大吃宵夜。", fact: "晚餐七八分饱、清淡、别太晚;睡前别大吃宵夜。" },
  { field: "百科", title: "细嚼慢咽的好处", body: "吃饭快、狼吞虎咽,不仅加重肠胃负担,还容易在大脑感到饱之前就吃多(饱腹信号有延迟)。细嚼慢咽能帮助消化、控制食量、更好感受食物味道。放慢速度,是最简单的减重和护胃习惯之一。", fact: "吃慢点:护胃、助消化、还不易吃多。" },
  { field: "百科", title: "剩菜剩饭怎么吃才安全", body: "剩饭剩菜放凉后及时冷藏、尽快(1—2天内)吃完,吃前彻底加热煮透。绿叶菜剩的尽量别留(易产生较多亚硝酸盐,且口感差);肉类、米饭可冷藏。反复加热多次的剩菜营养和安全都打折。", fact: "剩菜尽快吃+热透;绿叶菜剩的最好别留。" },
  { field: "百科", title: "隔夜菜、隔夜水能不能吃喝", body: "妥善冷藏的隔夜菜,加热透了一般可以吃,别妖魔化;但绿叶蔬菜、海鲜等剩的要慎重。「隔夜水致癌」是谣言,凉白开放一晚能喝,只是久置敞口可能落灰或滋生细菌,用干净带盖容器装没问题。", fact: "隔夜水能喝(别信致癌谣言);隔夜菜热透多数可吃。" },
  { field: "百科", title: "怎样减少盐的摄入", body: "减盐小技巧:少放盐、出锅前再放(更咸香、放得少)、善用葱姜蒜醋柠檬等天然调味,少吃咸菜腌制品和加工零食,留意酱油、蚝油、鸡精里的「隐形盐」。口味是可以慢慢变淡的,给味蕾一点适应时间。", fact: "出锅前放盐更省盐;善用醋、柠檬、香料替代。" },
  { field: "百科", title: "怎样健康吃油", body: "油脂要控制总量(成人每天约25—30克),种类换着用(不同植物油脂肪酸不同),少用动物油和反式脂肪。炒菜别等油冒大烟(高温破坏油、产生有害物)、别反复用炸过的油。凉拌可用橄榄油等。", fact: "每天油约 25—30 克;别等冒大烟才下锅,油别反复炸。" },
  { field: "百科", title: "水果不是吃越多越好", body: "水果健康,但含糖(果糖),一次吃太多同样会摄入过多糖分和热量,对控糖控重不利。建议每天一个拳头大小的量(约200—350克),种类多样。用大量水果代替正餐减肥并不科学。", fact: "水果每天约一两个拳头量;吃太多也会糖超标。" },
  { field: "百科", title: "坚果是健康零食但要限量", body: "坚果(核桃、杏仁、腰果等)含优质脂肪、蛋白和矿物质,是不错的零食,但热量高,一天一小把(约20—30克)即可,多吃容易热量超标。选原味的,少吃盐焗、糖衣、油炸调味的坚果。", fact: "坚果好但热量高,一天一小把就够。" },
  { field: "百科", title: "酸奶怎么选、怎么喝", body: "选酸奶看配料表和含糖量,优先选蛋白质高、糖分低的;「风味发酵乳」「乳酸菌饮料」含糖多、蛋白低,不等于酸奶。酸奶有助补钙和肠道菌群,但也别空腹大量喝刺激肠胃,常温放置的「活菌」益处会打折。", fact: "乳酸菌饮料≠酸奶;选酸奶看蛋白高、糖低的。" },
  { field: "百科", title: "怎样判断肉类是否新鲜", body: "新鲜肉色泽自然、有光泽、按压能回弹、气味正常;不新鲜的发暗发黏、有异味、弹性差。鱼看眼睛(清亮不凹陷)、鳃(鲜红)、鱼身有弹性。拿不准新鲜度的肉别买别吃,冷冻久了的肉解冻后也要闻一闻。", fact: "新鲜肉按压能回弹、无异味;发黏有味别吃。" },
  { field: "百科", title: "食材要彻底煮熟", body: "肉、禽、蛋、海鲜、豆类(如四季豆、豆浆)一定要煮熟煮透,很多食物中毒和寄生虫问题源于没熟。生豆浆含皂素、四季豆含毒素,没熟会中毒。生食(刺身等)要确保来源可靠、处理规范,孕妇幼儿老人尽量别生食。", fact: "四季豆、豆浆一定煮透;没熟会中毒。" },
  { field: "百科", title: "生熟食物要分开处理", body: "切生肉和切熟食、果蔬的刀和砧板要分开,避免生肉上的细菌污染直接入口的食物(交叉污染)。处理生食后要洗手。这是厨房防食物中毒最重要的习惯之一,很多家庭忽视了却很关键。", fact: "切生肉和切熟食的刀板要分开,防交叉污染。" },
  { field: "百科", title: "怎样合理喝汤", body: "汤里溶解的营养其实有限,精华大多还在肉和料里,所以「只喝汤不吃肉」并不划算。老火汤、浓汤往往高盐、高嘌呤(痛风者慎喝),油也多。喝汤适量、连料一起吃、别太咸太油更健康。", fact: "营养多在料里,别只喝汤弃肉;老火汤别太咸。" },
  { field: "百科", title: "怎样健康吃火锅、烧烤", body: "火锅烧烤别太频繁。火锅注意:别烫太辣太烫(伤食道)、生熟筷分开、少喝重口锅底汤、多涮蔬菜。烧烤注意:别吃烤焦的部分(焦糊处含有害物)、搭配蔬菜、控制量。偶尔解馋没事,常吃要节制。", fact: "烧烤别吃烤焦部分;火锅生熟筷分开、少喝锅底。" },
  { field: "百科", title: "怎样控制体重:管住嘴迈开腿", body: "减重的核心是制造热量缺口:摄入的热量少于消耗的。没有哪种单一食物能「刷脂」,也不存在只吃某物的健康快速减肥。合理饮食(控总量、保证蛋白和蔬菜)+规律运动+充足睡眠,慢慢来才持久。", fact: "减肥靠「吃进的少于消耗的」,没有捷径。" },
  { field: "百科", title: "不吃主食减肥不可取", body: "完全不吃主食(碳水)短期可能掉秤(掉的多是水分),但长期易疲劳、脱发、情绪差、停食就反弹,还可能伤身。更健康的做法是适量吃、换成全谷物粗粮,而不是一刀切不吃。极端节食不可持续。", fact: "别完全断主食减肥,换粗粮、适量吃更靠谱。" },
  { field: "百科", title: "怎样给孩子/老人安排饮食", body: "孩子要均衡、不挑食,保证蛋白和钙,少吃高糖高盐零食;老人消化弱,宜软烂易消化、少食多餐、保证蛋白(防肌肉流失)和钙,注意补水(老人口渴感迟钝)。两头人群都要少盐少油少刺激。", fact: "老人宜软烂少食多餐、保证蛋白;注意主动补水。" },
  { field: "百科", title: "特殊人群的饮食注意", body: "糖尿病人控糖控总量、定时定量;高血压者严格控盐;痛风者少吃高嘌呤(动物内脏、浓汤、部分海鲜、啤酒);有慢病者遵医嘱和营养师建议。别乱信「食疗根治」偏方而放弃正规治疗。", fact: "痛风少吃内脏浓汤啤酒;慢病饮食要遵医嘱。" },
  { field: "百科", title: "「趁热吃」并不好", body: "食物和饮品太烫(超过约65℃)会反复损伤食道黏膜,长期有害。中式饮食习惯「趁热吃」,其实应等稍微放凉、不烫口再吃喝。感觉烫嘴就是太热了,给它一两分钟。护好食道,是容易被忽视的健康细节。", fact: "太烫的食物饮品伤食道,别急着「趁热吃」。" },
  { field: "百科", title: "怎样安排每天的饮水", body: "喝水贵在少量多次、别等很渴才喝。晨起一杯水、白天分散着喝、运动前后补水。别用含糖饮料、浓茶代替白开水。一次性猛灌大量水增加肾脏负担,也别为了「排毒」强行过量喝水。白开水最经济健康。", fact: "喝水少量多次;别等渴了才喝,也别猛灌。" },
  { field: "百科", title: "保质期和保存期的区别", body: "「保质期」是在规定储存条件下保证品质的期限,过期不一定立刻有害但品质下降、风险升高,尽量别吃。开封后保质期会缩短,要尽快吃完。储存条件(如需冷藏)不满足,保质期也不作数。看清楚再买再吃。", fact: "开封后保质期会变短;没按要求储存的也不算数。" },

  // ========== 生活百科 · 趣味科普(40) ==========
  { field: "百科", title: "为什么天是蓝的、晚霞是红的", body: "阳光里蓝光波长短,最容易被空气分子散射到四面八方,所以白天抬头满眼是蓝(瑞利散射)。日出日落时阳光斜穿更厚的大气,蓝光几乎被散射光了,剩下红橙光直射眼睛,于是天边一片красно。", fact: "蓝天和红霞,都是阳光被大气「散射」的结果。" },
  { field: "百科", title: "彩虹是怎么形成的", body: "彩虹是阳光射入空气中的小水滴后,发生折射和反射,不同颜色的光偏折角度不同被分开,形成的七色弧。所以彩虹总出现在太阳的反方向、雨后或喷泉旁。背对太阳、面朝水雾,就有机会看到。", fact: "彩虹=阳光在小水滴里折射分色;背对太阳才看得到。" },
  { field: "百科", title: "为什么打雷时先看到闪电后听到雷声", body: "闪电和雷声同时发生,但光速(约每秒30万公里)远快于声速(约每秒340米),所以我们总是先看到闪电、几秒后才听到雷。用「看到闪电到听到雷声的秒数×340米」可粗略估算雷电离你多远。", fact: "光比声快得多;数秒数能估算雷有多远。" },
  { field: "百科", title: "为什么会打哈欠、还会传染", body: "打哈欠可能与大脑降温、提神、调节状态有关(确切机制仍在研究)。而「哈欠传染」被认为和共情能力、镜像神经元有关——看到、听到甚至读到打哈欠,都可能让你也想打。关系越亲近越容易被「传染」。", fact: "哈欠会「传染」,和共情有关;看到就想打。" },
  { field: "百科", title: "为什么洋葱让人流泪", body: "切洋葱会破坏其细胞,释放出含硫化合物,遇空气转化成刺激性气体,接触眼睛后与泪液反应生成微量硫酸样物质,刺激眼睛分泌泪水来冲洗。这就是为什么切得越猛、泪流得越凶。", fact: "洋葱释放的含硫气体刺激眼睛,逼出眼泪。" },
  { field: "百科", title: "为什么辣其实是一种「痛觉」", body: "辣不是味觉,而是辣椒素刺激口腔里感知温度和痛的受体,产生灼烧般的「痛」感,大脑随之释放内啡肽,带来一点愉悦，所以有人越吃越上瘾。解辣喝水没用(辣椒素不溶于水),喝牛奶更有效。", fact: "辣是「痛觉」不是味觉;解辣喝牛奶比喝水管用。" },
  { field: "百科", title: "为什么冰是浮在水面上的", body: "大多数物质固态比液态密度大会下沉,但水结冰时体积变大、密度变小,所以冰浮在水上。正因如此,冬天湖面先从上面结冰,冰层下的水和鱼才能存活。这是水非常特殊的性质。", fact: "水结冰体积变大、变轻,所以冰会浮起来。" },
  { field: "百科", title: "为什么热水有时比冷水结冰还快", body: "在某些条件下,温度较高的水反而比温度较低的水先结冰,这个反直觉现象叫「姆潘巴效应」,由一名中学生做冰淇淋时发现。科学家至今仍在研究其成因,可能与蒸发、对流、溶解气体等多因素有关。", fact: "姆潘巴效应:特定条件下热水比冷水先结冰。" },
  { field: "百科", title: "微波炉是怎么加热食物的", body: "微波炉发出的微波让食物里的水分子高速振动、互相摩擦生热,所以含水多的食物热得快,而干燥的陶瓷盘子本身不太热(是被食物烫热的)。这也是为什么没水分的东西微波不太热、带壳鸡蛋会爆。", fact: "微波让水分子振动生热;所以含水多的热得快。" },
  { field: "百科", title: "为什么天冷呼气会「冒白烟」", body: "呼出的气含大量水蒸气且温暖,遇到外界冷空气迅速降温,水蒸气凝结成微小水珠,就成了看得见的白雾。夏天不冒,是因为气温高、水蒸气不凝结。这和烧开水冒「白气」是一个道理。", fact: "呼出的水汽遇冷凝成小水珠,就成了白雾。" },
  { field: "百科", title: "为什么镜子里的字是反的,上下却不反", body: "镜子其实没有左右互换,它是「前后」翻转。我们觉得字左右颠倒,是因为把纸翻过来面对镜子时自己做了左右翻转。镜子只是沿垂直于镜面的方向把前后对调,上下左右本身并没被镜子交换。", fact: "镜子翻的是「前后」,不是左右;左右是你自己翻的。" },
  { field: "百科", title: "为什么会起鸡皮疙瘩", body: "寒冷或紧张害怕时,皮肤上细小的立毛肌收缩,把毛孔周围皮肤顶起来,就成了鸡皮疙瘩。这是人类从毛发浓密的祖先那里留下的本能——竖毛能保暖、让动物看起来更大吓唬对手,如今对人基本没用了。", fact: "鸡皮疙瘩是立毛肌收缩,祖先用来保暖/虚张声势的遗留。" },
  { field: "百科", title: "为什么挠自己痒痒不觉得痒", body: "痒和挠痒的反应,部分是大脑对「意外触碰」的防御。自己挠时,大脑小脑已经预判了动作和触感,会把这种自我刺激「过滤」掉,所以不觉得痒。别人挠你因为不可预测,大脑来不及屏蔽,就痒了。", fact: "自己挠不痒,因为大脑提前预判、屏蔽了这种刺激。" },
  { field: "百科", title: "为什么海水是咸的", body: "雨水冲刷陆地和岩石,把其中的盐类矿物质溶解带入河流、最终汇入大海;海水蒸发时水跑了、盐留下,日积月累越积越咸。所以海是咸的,而不断被蒸发补给的河湖(有出口)则相对淡。", fact: "陆地的盐被水带进海,水蒸发盐留下,越积越咸。" },
  { field: "百科", title: "为什么天上的星星会「眨眼」", body: "星星本身发光稳定,看起来一闪一闪,是因为星光穿过地球大气层时,被不断流动、冷热不均的空气折射扰动,方向和亮度发生细微抖动。行星离得近、看起来是小圆面,受扰动影响小,所以相对不太闪。", fact: "星星「眨眼」是大气扰动了星光,不是星星本身在闪。" },
  { field: "百科", title: "为什么月亮有时白天也能看到", body: "月亮本身不发光,靠反射阳光,只要它在地平线以上、且天空不太亮,白天也能看到。我们常以为月亮只在晚上出现,其实它白天也在天上，只是被蓝天衬得不明显,留意一下就会发现它。", fact: "月亮白天也在天上,只是被亮亮的蓝天盖住了。" },
  { field: "百科", title: "为什么飞机能飞起来", body: "飞机飞行主要靠机翼产生的升力:机翼形状使上方气流快、压强小,下方气流慢、压强大,上下压力差把飞机托起来;加上发动机提供向前的推力。足够的速度加上机翼设计,就能克服重力起飞。", fact: "机翼上下气流压力差产生升力,把飞机托起来。" },
  { field: "百科", title: "为什么不倒翁不倒", body: "不倒翁底部重、重心很低,且底是圆弧形。一推它,重心偏离最低点,重力就产生让它转回去的力矩,于是摇一摇又回正。重心越低、底座越稳,东西就越不容易倒——这也是很多设计防倒的原理。", fact: "不倒翁重心超低,一歪重力就把它扳回来。" },
  { field: "百科", title: "为什么肥皂能洗掉油污", body: "水和油不相溶,光用水洗不掉油。肥皂/洗洁精分子一头亲水、一头亲油,能一头抓住油污、一头拉进水里,把油「包」起来带走。所以洗油腻的碗要用洗洁精,道理和洗手去油是一样的。", fact: "肥皂分子一头亲油一头亲水,把油污「拽」进水里冲走。" },
  { field: "百科", title: "为什么切开的苹果会变褐", body: "苹果、土豆等切开后接触空气,其中的酚类物质在酶和氧气作用下发生氧化,生成褐色物质(酶促褐变)。泡盐水、滴柠檬汁、隔绝空气都能延缓。这不代表坏了,只是颜色变了,一般仍可食用。", fact: "苹果变褐是氧化(酶促褐变),没坏,泡盐水可延缓。" },
  { field: "百科", title: "为什么面包放久会变硬", body: "面包变硬主要不是因为失水，而是「淀粉老化」——淀粉分子结构重新排列变得紧实。有趣的是冷藏会加速这个过程,所以面包冷藏反而更快变硬;而重新加热能让淀粉部分「回软」,冷冻则能延缓老化。", fact: "面包变硬是淀粉老化;冷藏更快,加热能回软。" },
  { field: "百科", title: "为什么可乐摇一摇会喷出来", body: "可乐里溶有大量加压的二氧化碳气体。摇晃会产生无数微小气泡作为「成核点」,打开瓶盖压力骤降,气体争相从这些气泡逃逸,就把液体一起喷出来。静置一会儿让气泡消散再开,就不会喷了。", fact: "摇可乐产生大量小气泡,开盖气体猛冲出来带出液体。" },
  { field: "百科", title: "为什么会晕车晕船", body: "晕动症源于感觉冲突:眼睛看到的(如车厢内相对静止)和内耳平衡器官感受到的(颠簸晃动)不一致,大脑「懵了」就恶心头晕。看向远处固定景物、坐前排、保证通风、别看手机,都能缓解。", fact: "晕车是眼睛和内耳「感觉打架」;看远处能缓解。" },
  { field: "百科", title: "为什么指纹人人不同", body: "指纹在胎儿时期形成,受基因和子宫内环境微小差异共同影响,即使同卵双胞胎指纹也不完全相同,且终生基本不变。正因独一无二又稳定,指纹才被用于身份识别。脚趾、手掌也有类似纹路。", fact: "指纹受发育微环境影响,连双胞胎都不一样。" },
  { field: "百科", title: "为什么人老了头发会变白", body: "头发的黑色靠毛囊里的黑色素细胞产生色素。随着年龄增长,这些细胞功能衰退、色素减少,新长的头发就变灰变白。遗传、压力、某些疾病也会影响。白发是自然老化现象,拔一根长十根是没有科学依据的说法。", fact: "白发是毛囊色素细胞衰退;「拔一根长十根」是谣言。" },
  { field: "百科", title: "为什么受伤的地方会结痂", body: "皮肤破损出血后,血液里的血小板和凝血物质会凝固形成血块止血,暴露在空气中干燥后就成了痂,像「临时创可贴」保护伤口、下面悄悄长新皮。痂别乱抠,让它自然脱落,伤口恢复得更好、不易留疤。", fact: "结痂是身体的「临时创可贴」,别乱抠,让它自然掉。" },
  { field: "百科", title: "为什么洗澡久了手指会起皱", body: "长时间泡水,手指脚趾皮肤会起皱。研究认为这不只是泡胀,更可能是神经调控血管收缩造成的主动反应,皱起的皮肤像轮胎花纹,能增加湿滑物体的抓握力——是进化留下的实用小功能。", fact: "泡水手指起皱可能是为了「增大抓握力」的进化设计。" },
  { field: "百科", title: "为什么会打嗝、怎么止", body: "打嗝是膈肌(呼吸的主要肌肉)不自主痉挛收缩引起的。大多无害,一会儿自己停。想止嗝可尝试慢慢喝温水、屏住呼吸一会儿、或分散注意力。若长时间频繁打嗝不止,则要留意就医排查。", fact: "打嗝是膈肌痉挛;喝温水、屏气常能缓解。" },
  { field: "百科", title: "为什么肚子饿会「咕咕」叫", body: "肚子叫声来自胃肠蠕动时,里面的气体和液体被挤压流动发出的声音。饿的时候胃排空、蠕动增强,气体液体多、声音更明显,所以显得特别响。吃饱后东西填满、声音被盖住,就不那么明显了。", fact: "肚子咕咕叫是胃肠蠕动挤压气液的声音,饿时更响。" },
  { field: "百科", title: "为什么冰箱门能「吸住」", body: "冰箱门边框里嵌着一圈磁性密封条,靠磁力吸附在金属门框上,既让门自动吸合、又密封保冷。老式用机械门闩的冰箱曾发生过儿童被关在里面打不开的事故,磁吸门从里面也能推开,更安全。", fact: "冰箱门靠磁性密封条吸住,既保冷又能从里推开。" },
  { field: "百科", title: "为什么不同金属摸起来凉热不同", body: "同样室温下,摸金属觉得比摸木头凉,不是因为金属真的更冷,而是金属导热快,迅速把你手上的热量带走,让你感觉「凉」;木头导热慢,热量散得慢就显得「暖」。凉热的感觉其实是导热快慢。", fact: "金属摸着凉是因为导热快,把手的热量带走了。" },
  { field: "百科", title: "为什么有的声音听着刺耳", body: "指甲划黑板、刀叉刮盘子那种声音让人起鸡皮疙瘩,研究发现是其中某个频率段正好落在人耳最敏感、也和人类尖叫/警报相近的范围,触发大脑的不适和警觉反应。是刻在本能里的「难听」。", fact: "指甲划黑板刺耳,是频率踩中了人耳最敏感的警觉段。" },
  { field: "百科", title: "为什么太空是黑的、没有声音", body: "太空接近真空,几乎没有空气分子来散射阳光,所以即使有太阳,背景天空也是黑的(不像地球有蓝天)。声音要靠介质(空气等)传播,真空里没有介质,所以太空是「寂静」的,再大的爆炸也听不到。", fact: "太空没空气:不散射光所以是黑的,也传不了声音。" },
  { field: "百科", title: "为什么四季会交替", body: "四季交替不是因为地球离太阳远近变化,而是因为地轴是倾斜的(约23.5度)。地球公转时,倾斜使不同半球接收阳光的角度和时长变化:阳光直射多、白天长就是夏天,反之是冬天。南北半球季节相反。", fact: "四季因地轴倾斜,不是因为离太阳远近。" },
  { field: "百科", title: "为什么海绵、毛巾能吸水", body: "海绵和毛巾布满细小孔隙和纤维缝隙,水在狭窄缝隙里会因「毛细现象」被自动吸上来、留在其中(就像细管子能把水吸高)。孔隙越多越细、材料越亲水,吸水能力就越强。植物根茎吸水也靠类似原理。", fact: "海绵毛巾靠「毛细现象」把水吸进细小缝隙里。" },
  { field: "百科", title: "为什么蚊子专咬某些人", body: "蚊子靠二氧化碳、体温、汗液气味、皮肤上的微生物等找目标。呼出二氧化碳多(体型大、运动后)、体温高、出汗多、某些体味的人更招蚊子。穿深色衣服、不勤洗澡也会增加吸引力。和「血型甜」关系不大。", fact: "蚊子爱找出汗多、二氧化碳多的人;和血型关系不大。" },
  { field: "百科", title: "为什么烟花有不同颜色", body: "烟花的颜色来自其中添加的金属盐在燃烧时发出的特定颜色光:钠发黄、锶和锂发红、钡发绿、铜发蓝绿、钾紫色等。这叫「焰色反应」,化学课上烧不同金属盐会看到不同火焰颜色,就是同一个原理。", fact: "烟花颜色来自不同金属燃烧(焰色反应):钠黄、铜绿、锶红。" },
  { field: "百科", title: "为什么回音和混响会出现", body: "声音遇到墙壁、山崖等会反射回来。若反射声比原声晚到约0.1秒以上,人耳能分辨出来,就是「回声」;若反射密集、延迟短,听起来是声音拖长的「混响」。空旷大厅、山谷里容易有回声和混响。", fact: "回声是声音被反射回来;延迟够长才能听出是「回音」。" },
  { field: "百科", title: "为什么气球摩擦后能吸起纸屑", body: "气球在头发或毛衣上摩擦会带上静电(电荷),带电物体能吸引轻小的纸屑、头发。这就是摩擦起电。干燥的冬天脱毛衣噼啪响、开门被电一下,都是静电在作怪。空气湿润时静电不易积累。", fact: "摩擦起电:带电的气球能吸起小纸屑;干燥天静电更多。" },
  { field: "百科", title: "为什么会做梦、梦为什么常记不住", body: "做梦主要发生在快速眼动(REM)睡眠期,可能和大脑整理记忆、处理情绪有关。醒来记不住梦,是因为睡眠中负责长期记忆的机制活跃度低,梦境往往没被「存档」,除非正好在做梦时醒来。", fact: "梦多在 REM 睡眠期;记不住是因为没被存进长期记忆。" },
  { field: "百科", title: "为什么人会脸红", body: "害羞、紧张或激动时,交感神经兴奋让面部血管扩张、血流增加,皮肤薄的脸颊就泛红。这是不受意志控制的生理反应,也被认为是人类一种独特的社交信号,传递「不好意思」等情绪。越在意反而越容易红。", fact: "脸红是面部血管扩张,一种控制不住的社交信号。" },

  // ========== 成语典故 · 第一批(34) ==========
  { field: "成语", title: "卧薪尝胆", body: "出自《史记·越王勾践世家》。越王勾践被吴王夫差打败后,回国把苦胆挂在座旁,坐卧、吃饭前都要尝一尝,提醒自己不忘耻辱,最终灭吴复仇。「卧薪」(睡柴草)是后人添加的说法。比喻刻苦自励、发愤图强。", fact: "主人公是越王勾践,对手是吴王夫差。" },
  { field: "成语", title: "破釜沉舟", body: "出自《史记·项羽本纪》。巨鹿之战时,项羽率军渡过漳河后,下令凿沉船只、砸破饭锅、烧掉营房,只带三天干粮,表示不胜不归。将士拼死作战,大败秦军。比喻下定决心、不留退路干到底。", fact: "釜是锅;人物是项羽,战役是巨鹿之战。" },
  { field: "成语", title: "纸上谈兵", body: "出自《史记·廉颇蔺相如列传》。赵国名将赵奢之子赵括熟读兵书,谈论兵法头头是道,却没有实战经验。长平之战中他代替廉颇为将,死搬兵书,结果被秦将白起打败,赵军四十万被坑杀。比喻空谈理论、不能解决实际问题。", fact: "主人公是赵括,对应长平之战。" },
  { field: "成语", title: "完璧归赵", body: "出自《史记·廉颇蔺相如列传》。秦昭王假意用十五座城换赵国的和氏璧,蔺相如奉命出使,看出秦王无意给城,设法把璧完好地送回赵国。比喻把原物完整无损地归还本人。", fact: "完璧=完好的玉璧;人物是蔺相如。" },
  { field: "成语", title: "负荆请罪", body: "出自《史记·廉颇蔺相如列传》。蔺相如因功位居廉颇之上,廉颇不服,扬言要羞辱他。蔺相如处处避让,说是以国家为重。廉颇得知后,光着上身背着荆条到蔺相如门前请罪,两人成为刎颈之交。比喻主动向人认错赔罪。", fact: "背荆条的是廉颇;两人后来成了「将相和」。" },
  { field: "成语", title: "指鹿为马", body: "出自《史记·秦始皇本纪》。秦二世时,赵高想篡权,在朝堂上献给秦二世一头鹿,却说是马,借此试探群臣。顺从他说是马的留下,说是鹿的被他暗中陷害。比喻故意颠倒黑白、混淆是非。", fact: "人物是赵高,发生在秦二世时期。" },
  { field: "成语", title: "四面楚歌", body: "出自《史记·项羽本纪》。楚汉相争末期,项羽被汉军围困在垓下,夜里听到四面汉军都唱楚地歌谣,以为楚地已被汉军占领,大势已去。比喻四面受敌、孤立无援的处境。", fact: "地点是垓下;后续有「霸王别姬」。" },
  { field: "成语", title: "背水一战", body: "出自《史记·淮阴侯列传》。韩信攻赵时,在井陉口背靠河水布阵,士兵没有退路,只能拼死作战,最终大破赵军。比喻在绝境中与敌人决一死战,也泛指下最后决心。", fact: "人物是韩信,与「破釜沉舟」意思相近。" },
  { field: "成语", title: "草木皆兵", body: "出自《晋书·苻坚载记》。淝水之战前,前秦皇帝苻坚登寿阳城远望,见晋军阵容严整,又望见八公山上的草木,以为都是晋兵,心生恐惧。比喻人在惊慌时疑神疑鬼。", fact: "出自淝水之战,人物是苻坚。" },
  { field: "成语", title: "风声鹤唳", body: "出自《晋书·谢玄传》。淝水之战中前秦大败,溃逃的士兵听到风声和鹤叫,都以为是东晋追兵来了,吓得日夜奔逃。比喻惊慌失措,稍有动静就紧张害怕。", fact: "和「草木皆兵」都出自淝水之战,常连用。" },
  { field: "成语", title: "望梅止渴", body: "出自《世说新语·假谲》。曹操行军途中找不到水,士兵都很口渴。曹操说前面有一大片梅林,梅子又酸又甜,士兵听了满嘴生津,暂时止住了口渴,最终找到水源。比喻用空想安慰自己。", fact: "人物是曹操;多含「用空想自我安慰」的意思。" },
  { field: "成语", title: "三顾茅庐", body: "出自诸葛亮《出师表》中「三顾臣于草庐之中」。东汉末年刘备三次到隆中拜访诸葛亮,终于请他出山辅佐,诸葛亮由此提出「隆中对」。比喻真心诚意、一再邀请人才。", fact: "刘备请诸葛亮;出处是《出师表》。" },
  { field: "成语", title: "刮目相看", body: "出自《三国志·吴书·吕蒙传》裴松之注。吴将吕蒙原本读书少,后听孙权劝告刻苦学习。鲁肃再见到他时大为惊讶,吕蒙说:「士别三日,即更刮目相待。」比喻用新的眼光看待别人的进步。", fact: "人物是吕蒙和鲁肃;注意是「刮」目不是「括」目。" },
  { field: "成语", title: "乐不思蜀", body: "出自《三国志·蜀书·后主传》裴松之注。蜀汉灭亡后,后主刘禅被迁到洛阳。司马昭问他是否思念蜀地,他回答「此间乐,不思蜀」。比喻乐而忘返或乐而忘本。", fact: "人物是刘禅(阿斗);多带贬义。" },
  { field: "成语", title: "闻鸡起舞", body: "出自《晋书·祖逖传》。东晋祖逖和好友刘琨志向远大,半夜听到鸡叫就起床练剑,互相勉励要报效国家。后来祖逖北伐,收复了不少失地。比喻有志之士及时奋发、刻苦自励。", fact: "人物是祖逖和刘琨。" },
  { field: "成语", title: "凿壁偷光", body: "出自《西京杂记》。西汉匡衡家贫,晚上没有蜡烛读书,邻居家有烛光却照不过来,他就在墙上凿个小洞,借邻居的光读书,后来成为大学问家。比喻家境贫寒仍刻苦学习。", fact: "人物是西汉匡衡。" },
  { field: "成语", title: "囊萤映雪", body: "由两个故事合成:晋代车胤家贫无油,夏夜用袋子装萤火虫照明读书(见《晋书·车胤传》);孙康冬夜借雪地反光读书。比喻家境贫苦、刻苦读书。", fact: "囊萤是车胤,映雪是孙康。" },
  { field: "成语", title: "悬梁刺股", body: "由两个故事合成:汉代孙敬读书怕打瞌睡,用绳子把头发系在房梁上;战国苏秦读书困倦时用锥子刺自己的大腿(见《战国策·秦策》)。比喻发愤苦读。", fact: "悬梁是孙敬,刺股是苏秦;股是大腿。" },
  { field: "成语", title: "磨杵成针", body: "见宋代祝穆《方舆胜览》。相传李白小时候不爱读书,路遇一位老婆婆在磨铁杵,说要把它磨成针。李白深受触动,从此发奋学习。比喻只要有恒心,再难的事也能做成。", fact: "俗语「只要功夫深,铁杵磨成针」;人物是李白。" },
  { field: "成语", title: "守株待兔", body: "出自《韩非子·五蠹》。宋国有个农夫,看到一只兔子撞死在树桩上,捡了便宜。从此他放下农具守在树旁,等着再捡兔子,结果田地荒芜,成了笑话。比喻死守经验不知变通,或妄想不劳而获。", fact: "出自《韩非子》,主人公是宋国人。" },
  { field: "成语", title: "拔苗助长", body: "出自《孟子·公孙丑上》,原作「揠苗助长」。宋国有人嫌禾苗长得慢,就把禾苗一棵棵往上拔,回家还说帮苗长高了,儿子跑去一看,苗全枯死了。比喻违反规律、急于求成,反而坏事。", fact: "原文是「揠(yà)苗助长」,出自《孟子》。" },
  { field: "成语", title: "画蛇添足", body: "出自《战国策·齐策二》。楚国几个人比赛画蛇,先画完的人喝酒。一人最先画好,却又给蛇画脚,结果被别人抢走了酒,因为蛇本来没有脚。比喻做多余的事,反而弄巧成拙。", fact: "出自《战国策》;核心是「多此一举」。" },
  { field: "成语", title: "亡羊补牢", body: "出自《战国策·楚策四》。庄辛劝楚襄王时说:「见兔而顾犬,未为晚也;亡羊而补牢,未为迟也。」丢了羊再修羊圈,还不算晚。比喻出了问题及时补救,可以防止更大损失。", fact: "亡=丢失,牢=羊圈;含义偏积极,强调「不晚」。" },
  { field: "成语", title: "狐假虎威", body: "出自《战国策·楚策一》。老虎捉到狐狸,狐狸骗老虎说自己是天帝派来的百兽之王,让老虎跟着它走。百兽看见老虎都逃跑了,老虎以为是怕狐狸。比喻倚仗别人的势力来欺压人。", fact: "假=借;是江乙对楚宣王讲的寓言。" },
  { field: "成语", title: "鹬蚌相争", body: "出自《战国策·燕策二》。河蚌张壳晒太阳,鹬鸟去啄蚌肉,蚌合壳夹住鹬嘴,双方互不相让,结果被渔夫一起捉走。常说「鹬蚌相争,渔翁得利」。比喻双方争执不下,让第三方占了便宜。", fact: "后半句是「渔翁得利」;是苏代劝赵王时讲的。" },
  { field: "成语", title: "杞人忧天", body: "出自《列子·天瑞》。杞国有个人担心天会塌下来、地会陷下去,自己无处存身,愁得吃不下饭、睡不着觉。比喻不必要或缺乏根据的忧虑。", fact: "杞是古国名;读 qǐ。" },
  { field: "成语", title: "愚公移山", body: "出自《列子·汤问》。愚公年近九十,家门前有太行、王屋两座大山挡路,他带领子孙挖山不止。智叟笑他,愚公说子子孙孙无穷尽,山却不会增高。天帝被感动,派神把山背走。比喻不怕困难、坚持不懈。", fact: "两座山是太行山和王屋山;对比人物是智叟。" },
  { field: "成语", title: "刻舟求剑", body: "出自《吕氏春秋·察今》。楚国有人坐船过江,剑掉进水里,他在船舷上刻个记号,说剑是从这里掉下去的。船停后,他按记号下水找剑,当然找不到。比喻拘泥固执、不懂得情况已经变化。", fact: "主人公是楚国人;核心是「不知变通」。" },
  { field: "成语", title: "掩耳盗铃", body: "出自《吕氏春秋·自知》,原作「掩耳盗钟」。有人想偷一口钟,钟太大背不动,就想打碎了拿走。一敲钟声响亮,他怕被人听见,赶紧捂住自己的耳朵。比喻自己欺骗自己。", fact: "原文是偷「钟」,后演变成「铃」。" },
  { field: "成语", title: "自相矛盾", body: "出自《韩非子·难一》。楚国有人卖矛和盾,夸盾坚固到什么都刺不穿,又夸矛锋利到什么都能刺穿。有人问:「用你的矛刺你的盾会怎样?」他答不上来。比喻言行前后互相抵触。", fact: "矛用来进攻,盾用来防守;出自《韩非子》。" },
  { field: "成语", title: "滥竽充数", body: "出自《韩非子·内储说上》。齐宣王爱听三百人合奏竽,不会吹的南郭先生混在里面领赏。齐湣王继位后喜欢听独奏,南郭先生只好逃走。比喻没有真本事的人混在行家里凑数。", fact: "人物是南郭先生;竽是一种古代乐器。" },
  { field: "成语", title: "买椟还珠", body: "出自《韩非子·外储说左上》。楚国人卖珍珠,用名贵木料做了精美的盒子。郑国人买下后,把盒子留下,却把珍珠还给了卖家。比喻没有眼光,取舍不当,只重外表不重实质。", fact: "椟(dú)是木盒;买家是郑国人。" },
  { field: "成语", title: "井底之蛙", body: "出自《庄子·秋水》。浅井里的青蛙自以为很快乐,向东海的大鳖夸耀;大鳖讲述了大海的广阔,青蛙听后惊得说不出话。比喻见识狭窄、眼界不宽的人。", fact: "出自《庄子》;近义词「坐井观天」。" },
  { field: "成语", title: "邯郸学步", body: "出自《庄子·秋水》。燕国寿陵有个少年到赵国邯郸学当地人走路的姿势,结果没学会,连自己原来怎么走路也忘了,只好爬着回去。比喻盲目模仿别人,反而丢掉了自己的长处。", fact: "邯郸是赵国都城;学步的是燕国少年。" },

  // ========== 成语典故 · 第二批(33) ==========
  { field: "成语", title: "叶公好龙", body: "出自汉代刘向《新序·杂事》。叶公很喜欢龙,衣带、酒具、屋梁上都刻着龙。天上的真龙知道后来到他家,叶公却吓得魂飞魄散,转身就逃。比喻表面上爱好某事物,实际上并不真爱好。", fact: "叶旧读 shè;讽刺口是心非。" },
  { field: "成语", title: "塞翁失马", body: "出自《淮南子·人间训》。边塞有位老人丢了马,邻居来安慰,他说未必不是福;后来马带回一匹骏马,他又说未必不是祸;儿子骑马摔断腿,却因此免于征兵。比喻坏事和好事可以互相转化。", fact: "常说「塞翁失马,焉知非福」。" },
  { field: "成语", title: "对牛弹琴", body: "出自汉代牟融《理惑论》。公明仪对着牛弹奏高雅的曲子,牛照样低头吃草;换成蚊虻声、小牛叫声,牛才摇尾竖耳听。比喻对不懂道理的人讲道理,也用来讥笑说话不看对象。", fact: "弹琴的人是公明仪;也批评说话不看对象。" },
  { field: "成语", title: "黔驴技穷", body: "出自柳宗元《三戒·黔之驴》。有人把驴运到没有驴的黔地,老虎起初很害怕。后来驴被激怒,只会用蹄子踢,老虎看出它没别的本事,就扑上去吃了它。比喻有限的一点本领已经用完。", fact: "黔指今贵州一带;作者是柳宗元。" },
  { field: "成语", title: "胸有成竹", body: "出自苏轼《文与可画筼筜谷偃竹记》。北宋画家文同(字与可)画竹之前,心中已有竹子的完整形象,所以下笔一气呵成。比喻做事之前已经有了通盘考虑和把握。", fact: "画竹的是文同(文与可),记述者是苏轼。" },
  { field: "成语", title: "入木三分", body: "出自唐代张怀瓘《书断》。相传王羲之在木板上写字,刻字工人削木时发现墨迹渗进木头三分深。原形容书法笔力强劲,后比喻见解、议论深刻透彻。", fact: "人物是书圣王羲之。" },
  { field: "成语", title: "洛阳纸贵", body: "出自《晋书·左思传》。西晋文学家左思写成《三都赋》,洛阳豪门大户争相传抄,导致洛阳的纸价都涨了。比喻作品广为流传、风行一时。", fact: "作品是左思的《三都赋》。" },
  { field: "成语", title: "江郎才尽", body: "出自《南史·江淹传》。南朝江淹少年时以文章著称,晚年诗文却大不如前。传说他梦见郭璞向他讨回一支五色笔,此后再也写不出好句子。比喻才思枯竭。", fact: "江郎指江淹;多指才思减退。" },
  { field: "成语", title: "一字千金", body: "出自《史记·吕不韦列传》。秦相吕不韦组织门客编成《吕氏春秋》,把书挂在咸阳城门上,宣称谁能增删一个字就赏千金。后用来称赞文辞精妙、价值极高。", fact: "相关的书是《吕氏春秋》。" },
  { field: "成语", title: "一鼓作气", body: "出自《左传·庄公十年》「曹刿论战」。长勺之战中,曹刿等齐军敲过三通鼓、士气衰竭后才让鲁军出击,说「一鼓作气,再而衰,三而竭」。比喻趁劲头足时一下子把事情做完。", fact: "出自「曹刿论战」,对应长勺之战。" },
  { field: "成语", title: "退避三舍", body: "出自《左传·僖公二十三年》。晋公子重耳流亡到楚国,答应楚成王:日后两国交战,晋军先后退三舍。后来城濮之战,他兑现诺言。古时行军三十里为一舍。比喻主动让步,不与人相争。", fact: "一舍=三十里,三舍=九十里;人物是重耳(晋文公)。" },
  { field: "成语", title: "唇亡齿寒", body: "出自《左传·僖公五年》。晋国向虞国借路去攻打虢国,宫之奇劝虞君说:虞虢相依,就像嘴唇和牙齿,嘴唇没了牙齿就会受冻。虞君不听,晋灭虢后回师顺手灭了虞。比喻双方关系密切、利害相关。", fact: "相关典故还有「假道伐虢」。" },
  { field: "成语", title: "一鸣惊人", body: "出自《史记·滑稽列传》。齐威王即位后沉迷享乐,淳于髡用隐语劝他:有只大鸟三年不飞不叫。齐威王答:「此鸟不飞则已,一飞冲天;不鸣则已,一鸣惊人。」随后整顿国政。比喻平时默默无闻,一下子做出惊人的成绩。", fact: "近义词「一飞冲天」;常与「不鸣则已」连用。" },
  { field: "成语", title: "毛遂自荐", body: "出自《史记·平原君虞卿列传》。秦军围攻邯郸,平原君要选二十人去楚国求救,门客毛遂主动推荐自己。在楚国,他按剑陈说利害,促成合纵抗秦。比喻自己推荐自己担任工作。", fact: "毛遂是平原君赵胜的门客。" },
  { field: "成语", title: "脱颖而出", body: "同样出自毛遂自荐的故事。平原君说贤士就像锥子放在口袋里,锥尖很快就会露出来。毛遂回答:要是早把我放进口袋,整个锥子都露出来了,不只是锥尖。比喻人的才能全部显露出来。", fact: "颖指锥尖;和「毛遂自荐」同出一个故事。" },
  { field: "成语", title: "围魏救赵", body: "出自《史记·孙子吴起列传》。魏军围攻赵国都城邯郸,齐国派田忌、孙膑救赵。孙膑不直接去邯郸,而是进攻魏国都城大梁,迫使魏军回救,在桂陵大败魏军。比喻袭击敌人后方,迫使进攻的敌人撤回。", fact: "谋士是孙膑;对应桂陵之战。" },
  { field: "成语", title: "鸡鸣狗盗", body: "出自《史记·孟尝君列传》。孟尝君被扣在秦国,门客中有人扮狗偷出狐白裘献给秦王宠妃求情,又有人学鸡叫骗开函谷关城门,孟尝君才得以逃回。比喻微不足道的本领,也指偷偷摸摸的行为。", fact: "人物是孟尝君;关口是函谷关。" },
  { field: "成语", title: "门可罗雀", body: "出自《史记·汲郑列传》。下邽翟公当廷尉时宾客满门,被罢官后门前冷落,可以张网捕麻雀。比喻门庭冷落,来客稀少。", fact: "罗是捕鸟的网;反义词「门庭若市」。" },
  { field: "成语", title: "约法三章", body: "出自《史记·高祖本纪》。刘邦攻入咸阳后,废除秦朝严苛的法令,与百姓约定三条:杀人者处死,伤人和偷盗按情节治罪。这赢得了民心。后泛指订立简单的条款共同遵守。", fact: "人物是刘邦;三章是三条法令。" },
  { field: "成语", title: "萧规曹随", body: "出自《史记·曹相国世家》,成语见扬雄《解嘲》。西汉萧何制定了法规制度,曹参接任丞相后完全遵照执行,不做改动,百姓安定。比喻后人沿用前人的成规。", fact: "萧是萧何,曹是曹参。" },
  { field: "成语", title: "一饭千金", body: "出自《史记·淮阴侯列传》。韩信年轻时贫困,在河边钓鱼挨饿,一位洗衣老妇人(漂母)给他饭吃。韩信后来被封为楚王,用千金报答她。比喻受人恩惠,加倍报答。", fact: "人物是韩信与漂母。" },
  { field: "成语", title: "多多益善", body: "出自《史记·淮阴侯列传》。刘邦问韩信:「我能带多少兵?」韩信说最多十万。又问韩信自己能带多少,韩信答:「臣多多而益善耳。」意为越多越好。", fact: "说这话的是韩信。" },
  { field: "成语", title: "投笔从戎", body: "出自《后汉书·班超传》。东汉班超家贫,靠替官府抄书养家。有一天他扔下笔感叹:大丈夫应当像张骞那样立功异域。后来他出使西域,立下大功。指文人弃文从军。", fact: "人物是班超,是史学家班固的弟弟。" },
  { field: "成语", title: "不入虎穴,焉得虎子", body: "出自《后汉书·班超传》。班超出使鄯善,遇到匈奴使者也在,鄯善王态度变冷。班超对部下说「不入虎穴,不得虎子」,夜袭匈奴使团,使鄯善归附汉朝。比喻不冒险就难以取得成功。", fact: "也出自班超出使西域的故事。" },
  { field: "成语", title: "老当益壮", body: "出自《后汉书·马援传》。东汉名将马援曾说:「丈夫为志,穷当益坚,老当益壮。」他六十多岁仍请求出征。比喻年纪虽老,志向更高、干劲更足。", fact: "人物是东汉马援(伏波将军)。" },
  { field: "成语", title: "马革裹尸", body: "同样出自《后汉书·马援传》。马援说男儿应当战死在边疆,用马皮包裹尸体回来安葬,怎么能躺在床上死在儿女身边。形容军人为国捐躯、英勇作战的决心。", fact: "也是马援的话,表现报国之志。" },
  { field: "成语", title: "举案齐眉", body: "出自《后汉书·逸民传·梁鸿》。东汉梁鸿与妻子孟光隐居,孟光每次给丈夫送饭,都把托盘举到和眉毛一样高,以示尊敬。形容夫妻相互敬重、和睦相处。", fact: "案是端食物的托盘;人物是梁鸿和孟光。" },
  { field: "成语", title: "东山再起", body: "出自《晋书·谢安传》。东晋谢安辞官后隐居会稽东山,多次征召都不出,四十多岁时才重新出仕,后来主持淝水之战。比喻失势后重新得势。", fact: "人物是谢安;东山在会稽。" },
  { field: "成语", title: "投鞭断流", body: "出自《晋书·苻坚载记》。前秦苻坚准备攻打东晋时夸口:我们兵多,把马鞭都扔进长江,就能截断江水。结果在淝水之战中惨败。形容人马众多、兵力强大,也常含骄傲轻敌的意味。", fact: "说这话的是苻坚,随后淝水之战失败。" },
  { field: "成语", title: "呕心沥血", body: "「呕心」出自李商隐《李贺小传》,李贺母亲说他写诗「要当呕出心乃已」;「沥血」出自韩愈《归彭城》。形容用尽心思,多用于写作或工作。", fact: "多形容为事业、创作费尽心血。" },
  { field: "成语", title: "程门立雪", body: "出自《宋史·杨时传》。杨时与游酢去拜见老师程颐,见他闭目养神,就恭敬地站在门外等候。程颐醒来时,门外的雪已积了一尺深。形容尊师重道、虔诚求学。", fact: "老师是程颐,学生是杨时和游酢。" },
  { field: "成语", title: "精忠报国", body: "据《宋史·岳飞传》,岳飞受审时撕开衣服露出背上「尽忠报国」四个字。民间流传为岳母刺字,后世多说成「精忠报国」。形容对国家竭尽忠诚。", fact: "史书原作「尽忠报国」;人物是岳飞。" },
  { field: "成语", title: "莫须有", body: "出自《宋史·岳飞传》。秦桧诬陷岳飞谋反,韩世忠质问证据,秦桧说:「其事体莫须有。」意思是「也许有吧」。后指凭空捏造罪名。", fact: "说这话的是秦桧;指无中生有的罪名。" },

  // ========== 成语典故 · 第三批(33) ==========
  { field: "成语", title: "杯弓蛇影", body: "出自东汉应劭《风俗通义·怪神》,《晋书·乐广传》也有类似故事。有人喝酒时,看见杯中映着墙上弓的影子,以为是蛇,喝后疑心生病;后来知道真相,病就好了。比喻疑神疑鬼,自相惊扰。", fact: "「蛇」其实是弓的倒影。" },
  { field: "成语", title: "管鲍之交", body: "出自《史记·管晏列传》。春秋时管仲和鲍叔牙是好友,管仲家贫,分财时多拿,鲍叔牙不认为他贪婪;后来鲍叔牙还推荐管仲做齐国宰相。管仲说:「生我者父母,知我者鲍子也。」形容朋友之间深厚的信任。", fact: "管仲辅佐齐桓公成为春秋首霸。" },
  { field: "成语", title: "高山流水", body: "出自《列子·汤问》。伯牙弹琴,心想高山,钟子期说「巍巍乎若泰山」;心想流水,钟子期说「洋洋乎若江河」。子期死后,伯牙摔琴不再弹。比喻知音难遇,也形容乐曲高妙。", fact: "相关成语「知音」;人物是伯牙和钟子期。" },
  { field: "成语", title: "朝三暮四", body: "出自《庄子·齐物论》。养猴人给猴子分橡子,说早上三个晚上四个,猴子都生气;改说早上四个晚上三个,猴子都高兴。原指用手法骗人,现多比喻反复无常。", fact: "现代多用来形容反复无常、用情不专。" },
  { field: "成语", title: "庖丁解牛", body: "出自《庄子·养生主》。厨师庖丁给梁惠王宰牛,动作熟练流畅。他说自己掌握了牛的骨节结构,刀顺着空隙走,用了十九年刀刃还像新的一样。比喻掌握规律后做事得心应手。", fact: "庖是厨师,丁是人名;近义词「游刃有余」。" },
  { field: "成语", title: "螳臂当车", body: "出自《庄子·人间世》。螳螂举起前腿想挡住车轮前进,不知道自己根本挡不住。比喻不自量力,必然失败。", fact: "当=阻挡;常作「螳臂挡车」。" },
  { field: "成语", title: "鹏程万里", body: "出自《庄子·逍遥游》。传说大鹏鸟从北海飞往南海,翅膀拍水三千里,乘着旋风飞上九万里高空。比喻前程远大。", fact: "常用来祝福别人前途远大。" },
  { field: "成语", title: "东施效颦", body: "出自《庄子·天运》。美女西施心口痛时皱眉,依然很美。邻村丑女东施也学她捂胸皱眉,反而更难看,吓得别人躲开。比喻胡乱模仿,效果适得其反。", fact: "颦(pín)是皱眉;注意与「邯郸学步」区分。" },
  { field: "成语", title: "望洋兴叹", body: "出自《庄子·秋水》。秋水上涨时,河伯以为天下之美都在自己这里;到北海一看,大海无边无际,只能望着海神感叹。原指在伟大事物面前感到自己渺小,现多比喻力量不足、无可奈何。", fact: "望洋原意是仰视的样子,不是「望着海洋」。" },
  { field: "成语", title: "班门弄斧", body: "化用柳宗元《王氏伯仲唱和诗序》中「操斧于班、郢之门」;明代梅之焕题李白墓诗也有「鲁班门前弄大斧」。在巧匠鲁班门前摆弄斧头,比喻在行家面前卖弄本领。", fact: "班指鲁班;常用作自谦。" },
  { field: "成语", title: "南辕北辙", body: "出自《战国策·魏策四》。季梁讲了个故事:有人要去南方的楚国,却驾车往北走,还说马好、钱多、车夫技术好,结果离楚国越来越远。比喻行动和目的相反。", fact: "辕是车杠,辙是车轮印;条件越好离目标越远。" },
  { field: "成语", title: "惊弓之鸟", body: "出自《战国策·楚策四》。射手更羸只拉弓不放箭,就让一只飞雁掉了下来。原来这只雁受过箭伤,听到弓弦响就惊慌高飞,伤口裂开而坠落。比喻受过惊吓,遇到一点动静就非常害怕。", fact: "射手是更羸;雁没被射中,是被弓声吓落的。" },
  { field: "成语", title: "百步穿杨", body: "出自《战国策·西周策》。楚国养由基善于射箭,在百步之外射柳叶,百发百中。形容射箭或枪法非常高明。", fact: "射手是养由基;这里的「杨」指杨柳的叶子。" },
  { field: "成语", title: "三人成虎", body: "出自《战国策·魏策二》。庞葱问魏王:一个人说街上有老虎,您信吗?不信。三个人都这样说呢?魏王说会信。比喻谣言传的人多了,就会让人信以为真。", fact: "近义词「众口铄金」;人物是庞葱。" },
  { field: "成语", title: "怒发冲冠", body: "出自《史记·廉颇蔺相如列传》。蔺相如在秦廷见秦王无意交城,便手持和氏璧靠着柱子,「怒发上冲冠」,表示要与璧同碎。形容极度愤怒,岳飞《满江红》也有「怒发冲冠」一句。", fact: "最早写的是蔺相如;岳飞《满江红》首句也是它。" },
  { field: "成语", title: "讳疾忌医", body: "故事见《韩非子·喻老》:扁鹊多次提醒蔡桓公有病,桓公不听,最终病入骨髓而死。周敦颐《通书》有「护疾而忌医」。比喻掩饰缺点错误,不愿改正。", fact: "相关故事是「扁鹊见蔡桓公」。" },
  { field: "成语", title: "道听途说", body: "出自《论语·阳货》:「道听而涂说,德之弃也。」在路上听到的话,又在路上随便传播。指没有根据的传闻。", fact: "古文「涂」通「途」;出自《论语》。" },
  { field: "成语", title: "温故知新", body: "出自《论语·为政》:「温故而知新,可以为师矣。」温习学过的知识,能从中获得新的理解和体会。也指回顾历史,更好地认识现在。", fact: "出自孔子,是常考的学习方法名句。" },
  { field: "成语", title: "不耻下问", body: "出自《论语·公冶长》。子贡问孔子,孔文子为什么谥号叫「文」,孔子说他「敏而好学,不耻下问」。指不以向地位、学问不如自己的人请教为耻。", fact: "下问=向地位或学问较低的人请教。" },
  { field: "成语", title: "后生可畏", body: "出自《论语·子罕》:「后生可畏,焉知来者之不如今也?」年轻人潜力很大,往往能超过前辈,值得敬畏。", fact: "这里的「畏」是敬畏,不是害怕。" },
  { field: "成语", title: "名落孙山", body: "出自宋代范公偁《过庭录》。孙山考中最后一名,同乡问他自己的儿子考中没有,孙山答:「解名尽处是孙山,贤郎更在孙山外。」意为榜上最后一名是我,你儿子还在我后面。比喻考试没有录取。", fact: "孙山是人名,他自己考中了最后一名。" },
  { field: "成语", title: "走马观花", body: "出自唐代孟郊《登科后》:「春风得意马蹄疾,一日看尽长安花。」原形容事情如意、心情愉快,后多比喻粗略地观察事物。", fact: "原意是中举后春风得意,现多指看得粗略。" },
  { field: "成语", title: "世外桃源", body: "出自陶渊明《桃花源记》。武陵渔人误入一片与世隔绝的地方,那里的人为躲避秦时战乱来到此处,生活安宁快乐。比喻不受外界影响的理想地方。", fact: "作者是东晋陶渊明。" },
  { field: "成语", title: "破镜重圆", body: "出自唐代孟棨《本事诗·情感》。南朝陈将灭亡时,徐德言把铜镜一分为二,与妻子乐昌公主各执一半,约定日后凭半镜相认。后来夫妻果然团聚。比喻夫妻失散或决裂后重新团圆。", fact: "专指夫妻重聚,不能随便用于朋友。" },
  { field: "成语", title: "一叶障目", body: "源于《鹖冠子·天则》「一叶蔽目,不见太山」。三国邯郸淳《笑林》中,楚人以为拿片树叶遮住自己,别人就看不见他,结果被抓住。比喻被局部或暂时的现象迷惑,看不清全局。", fact: "常与「不见泰山」连用。" },
  { field: "成语", title: "闻过则喜", body: "出自《孟子·公孙丑上》:「子路,人告之以有过,则喜。」子路听到别人指出自己的过错就高兴。形容虚心接受批评。", fact: "人物是孔子的学生子路。" },
  { field: "成语", title: "一暴十寒", body: "出自《孟子·告子上》。孟子说,即使是最容易生长的植物,晒一天、冻十天,也没法生长。比喻学习或工作时勤时懒,没有恒心。", fact: "暴读 pù,是「曝」的古字,意为晒。" },
  { field: "成语", title: "五十步笑百步", body: "出自《孟子·梁惠王上》。打仗时,有士兵逃跑了五十步,却嘲笑逃了一百步的人胆小。比喻自己和别人有同样的缺点,只是程度轻一些,却去讥笑别人。", fact: "本质相同,只是程度不同。" },
  { field: "成语", title: "专心致志", body: "出自《孟子·告子上》。围棋高手弈秋教两个人下棋,一人专心听讲,另一人一边听一边想着射天鹅,后者自然学得不如前者。形容一心一意、集中精力。", fact: "老师是弈秋;反义词「心不在焉」。" },
  { field: "成语", title: "水滴石穿", body: "出自宋代罗大经《鹤林玉露》。张乖崖做崇阳县令时,惩处一个每天偷一文钱的库吏,判词说:「一日一钱,千日千钱,绳锯木断,水滴石穿。」比喻力量虽小,但坚持不懈就能成功。", fact: "常与「绳锯木断」连用。" },
  { field: "成语", title: "青出于蓝", body: "出自《荀子·劝学》:「青,取之于蓝,而青于蓝。」靛青从蓼蓝草中提取,颜色却比蓼蓝更深。比喻学生胜过老师,或后人胜过前人。", fact: "完整说法是「青出于蓝而胜于蓝」。" },
  { field: "成语", title: "锲而不舍", body: "出自《荀子·劝学》:「锲而舍之,朽木不折;锲而不舍,金石可镂。」不停地雕刻,连金石也能刻穿。比喻有恒心、有毅力。", fact: "锲(qiè)是雕刻;出自《劝学》。" },
  { field: "成语", title: "实事求是", body: "出自《汉书·河间献王传》:「修学好古,实事求是。」原指做学问要以事实为依据,探求真相。毛泽东赋予它新的含义,即从实际出发,找出事物的规律,是党的思想路线的核心。", fact: "考公考研都常考:实事求是是党的思想路线的核心。" },

  // ========== 诗词每日一句 · 先秦两汉魏晋(10) ==========
  { field: "诗词", title: "关关雎鸠,在河之洲", body: "出自《诗经·周南·关雎》。雎鸠鸟关关地鸣叫,在河中的小洲上。下句是「窈窕淑女,君子好逑」。这是《诗经》的第一篇,写男子对美好女子的思慕,用鸟的和鸣起兴。", fact: "《诗经》开篇之作;「好逑」意为好的配偶。" },
  { field: "诗词", title: "蒹葭苍苍,白露为霜", body: "出自《诗经·秦风·蒹葭》。芦苇青青一片,清晨的露水凝成了霜。下句是「所谓伊人,在水一方」。诗人在秋水边追寻心中的人,可望而不可即,意境朦胧。", fact: "蒹葭(jiān jiā)指芦苇;名句「所谓伊人,在水一方」。" },
  { field: "诗词", title: "路漫漫其修远兮,吾将上下而求索", body: "出自战国屈原《离骚》。前方的道路又长又远,我要上天下地去追求探索。屈原遭到排挤仍不放弃理想,这句表达了坚持追求真理的意志,常被用来自勉。", fact: "作者屈原;「修」是长的意思。" },
  { field: "诗词", title: "少壮不努力,老大徒伤悲", body: "出自汉乐府《长歌行》。年轻时不努力,到老了只能白白悲伤。诗中先写园中葵菜和百川东流,感叹时光一去不返,最后落到劝人珍惜青春。", fact: "出自汉乐府;「徒」是白白地。" },
  { field: "诗词", title: "老骥伏枥,志在千里", body: "出自东汉末年曹操《龟虽寿》。年老的千里马伏在马槽边,仍想着驰骋千里。下句是「烈士暮年,壮心不已」。这首诗写于曹操五十多岁时,表达老而弥坚的进取精神。", fact: "作者曹操;枥(lì)是马槽。" },
  { field: "诗词", title: "本是同根生,相煎何太急", body: "据《世说新语·文学》记载,魏文帝曹丕命弟弟曹植七步之内作诗,做不出就治罪。曹植以豆和豆萁比喻兄弟,讽刺骨肉相残。这就是流传的《七步诗》。", fact: "作者曹植,被逼的是哥哥曹丕。" },
  { field: "诗词", title: "采菊东篱下,悠然见南山", body: "出自东晋陶渊明《饮酒·其五》。在东边篱笆下采菊花,无意间抬头看见了南山。陶渊明辞官归隐田园,这句写出了他闲适自得、与自然融为一体的心境。", fact: "作者陶渊明,田园诗派开创者。" },
  { field: "诗词", title: "及时当勉励,岁月不待人", body: "出自东晋陶渊明《杂诗·其一》。盛年不会重来,一天也难有两个早晨。原诗的意思偏向及时行乐、珍惜相聚,后人常截取这两句用来劝人珍惜时间、努力上进。", fact: "原意和今天常用的「劝学」含义有差别。" },
  { field: "诗词", title: "万里赴戎机,关山度若飞", body: "出自北朝民歌《木兰诗》。木兰奔赴万里外的战场,飞一般越过一道道关山。诗讲花木兰替父从军十二年,立功后不求官职,只愿回乡。", fact: "《木兰诗》是北朝民歌,与《孔雀东南飞》合称「乐府双璧」。" },
  { field: "诗词", title: "苟利国家生死以,岂因祸福避趋之", body: "出自清代林则徐《赴戍登程口占示家人》。只要对国家有利,不惜献出生命,怎能因为个人祸福而逃避或追求?林则徐虎门销烟后被贬新疆,临行前写下此诗。", fact: "作者林则徐,写于被贬伊犁途中。" },

  // ========== 诗词每日一句 · 唐诗(53) ==========
  { field: "诗词", title: "举头望明月,低头思故乡", body: "出自唐代李白《静夜思》。抬头看见天上的明月,低下头就思念起故乡。全诗只有二十个字,语言朴素,却把游子思乡写得很动人,是流传最广的唐诗之一。", fact: "上两句是「床前明月光,疑是地上霜」。" },
  { field: "诗词", title: "天生我材必有用,千金散尽还复来", body: "出自唐代李白《将进酒》。上天给了我才能,必定有它的用处;千金花光了,还能再赚回来。李白在仕途失意时写下这首诗,豪放中带着对自我价值的强烈自信。", fact: "作者李白,被称为「诗仙」。" },
  { field: "诗词", title: "长风破浪会有时,直挂云帆济沧海", body: "出自唐代李白《行路难·其一》。总有一天能乘长风破万里浪,挂起高帆横渡沧海。前面写人生道路艰难,结尾却转向乐观,相信理想终会实现。", fact: "常用于表达远大志向和乐观信念。" },
  { field: "诗词", title: "桃花潭水深千尺,不及汪伦送我情", body: "出自唐代李白《赠汪伦》。桃花潭的水即使有千尺深,也比不上汪伦送我的情谊。李白游泾县时受到汪伦款待,临别时汪伦踏歌相送,李白写诗作答。", fact: "用夸张和比较写友情深厚。" },
  { field: "诗词", title: "孤帆远影碧空尽,唯见长江天际流", body: "出自唐代李白《黄鹤楼送孟浩然之广陵》。一叶孤帆渐渐消失在碧空尽头,只看见长江向天边流去。李白在黄鹤楼送别孟浩然,把不舍之情融入景色之中。", fact: "广陵即今扬州;前句有「烟花三月下扬州」。" },
  { field: "诗词", title: "飞流直下三千尺,疑是银河落九天", body: "出自唐代李白《望庐山瀑布》。瀑布从高处飞泻而下,好像银河从九天落下来。诗人用大胆夸张和想象,写出庐山瀑布的壮观气势。", fact: "写的是庐山瀑布;「三千尺」是夸张。" },
  { field: "诗词", title: "会当凌绝顶,一览众山小", body: "出自唐代杜甫《望岳》。一定要登上泰山的最高峰,俯瞰群山都显得渺小。这是杜甫青年时期的作品,表现出不怕困难、勇攀高峰的雄心壮志。", fact: "岳指东岳泰山;作者杜甫,被称为「诗圣」。" },
  { field: "诗词", title: "国破山河在,城春草木深", body: "出自唐代杜甫《春望》。国都已经沦陷,山河依旧;春天的长安城里荒草丛生。安史之乱中杜甫被困长安,写下了对国家破碎的痛心和对家人的思念。", fact: "同诗名句「烽火连三月,家书抵万金」。" },
  { field: "诗词", title: "安得广厦千万间,大庇天下寒士俱欢颜", body: "出自唐代杜甫《茅屋为秋风所破歌》。怎样才能得到千万间宽敞的房子,庇护天下贫寒的读书人,让他们都开颜欢笑?自家茅屋被风吹破,杜甫想到的却是天下人。", fact: "体现杜甫推己及人的博大胸怀。" },
  { field: "诗词", title: "随风潜入夜,润物细无声", body: "出自唐代杜甫《春夜喜雨》。春雨随着春风悄悄在夜里落下,无声地滋润万物。杜甫在成都草堂写下这首诗,现在也常用来比喻默默奉献、潜移默化的教育。", fact: "首句是「好雨知时节,当春乃发生」。" },
  { field: "诗词", title: "读书破万卷,下笔如有神", body: "出自唐代杜甫《奉赠韦左丞丈二十二韵》。读书读透上万卷,写起文章来就像有神帮助一样。杜甫回顾自己早年的刻苦学习,这句后来成为劝学名言。", fact: "「破」可理解为读透、读破。" },
  { field: "诗词", title: "出师未捷身先死,长使英雄泪满襟", body: "出自唐代杜甫《蜀相》。诸葛亮出兵伐魏还没取得胜利就去世了,这让后世英雄每每读到都泪湿衣襟。杜甫在成都武侯祠凭吊诸葛亮时写下此诗。", fact: "蜀相指诸葛亮。" },
  { field: "诗词", title: "无边落木萧萧下,不尽长江滚滚来", body: "出自唐代杜甫《登高》。无边无际的树叶萧萧飘落,滚滚长江奔流不息。杜甫晚年漂泊夔州时登高所作,景象壮阔又充满悲凉,被誉为「古今七律第一」。", fact: "《登高》被称为「古今七律第一」。" },
  { field: "诗词", title: "朱门酒肉臭,路有冻死骨", body: "出自唐代杜甫《自京赴奉先县咏怀五百字》。富贵人家的酒肉多得发臭,路边却有冻死的穷人。这句写于安史之乱前夕,揭露了尖锐的贫富对立。", fact: "朱门指富贵人家;体现杜诗「诗史」特点。" },
  { field: "诗词", title: "海内存知己,天涯若比邻", body: "出自唐代王勃《送杜少府之任蜀州》。只要四海之内有知心朋友,即使远在天涯也像近邻一样。这首送别诗一改常见的伤感,写得开阔豁达。", fact: "作者王勃,「初唐四杰」之一。" },
  { field: "诗词", title: "落霞与孤鹜齐飞,秋水共长天一色", body: "出自唐代王勃《滕王阁序》。晚霞和孤单的野鸭一起飞翔,秋天的江水与天空连成一色。这是骈文中的写景名句,色彩和动静搭配十分精妙。", fact: "鹜(wù)是野鸭;出自骈文《滕王阁序》。" },
  { field: "诗词", title: "欲穷千里目,更上一层楼", body: "出自唐代王之涣《登鹳雀楼》。想要看得更远,就要再登上一层楼。表面写登楼,实际蕴含哲理:想要眼界更开阔,就要站得更高。", fact: "上两句是「白日依山尽,黄河入海流」。" },
  { field: "诗词", title: "羌笛何须怨杨柳,春风不度玉门关", body: "出自唐代王之涣《凉州词》。羌笛何必吹起哀怨的《折杨柳》曲调呢?春风本来就吹不过玉门关。诗写边塞荒凉和戍边将士的思乡之情。", fact: "首句是「黄河远上白云间」。" },
  { field: "诗词", title: "独在异乡为异客,每逢佳节倍思亲", body: "出自唐代王维《九月九日忆山东兄弟》。独自在外乡做客,每到节日就更加思念亲人。王维写这首诗时只有十七岁,九月九日是重阳节。", fact: "节日是重阳节;后句「遍插茱萸少一人」。" },
  { field: "诗词", title: "劝君更尽一杯酒,西出阳关无故人", body: "出自唐代王维《送元二使安西》。请你再喝完这杯酒吧,向西出了阳关就再也没有老朋友了。这首诗后来被谱成《阳关三叠》,成为送别名曲。", fact: "又名《渭城曲》,首句「渭城朝雨浥轻尘」。" },
  { field: "诗词", title: "大漠孤烟直,长河落日圆", body: "出自唐代王维《使至塞上》。广阔沙漠上一缕烽烟直上云霄,黄河边的落日又大又圆。王维出使边塞时所作,寥寥十字画出了雄浑的塞外风光。", fact: "被王国维称为「千古壮观」。" },
  { field: "诗词", title: "明月松间照,清泉石上流", body: "出自唐代王维《山居秋暝》。明月照在松林之间,清澈的泉水在石头上流淌。苏轼评价王维「诗中有画」,这两句就是典型的例子。", fact: "王维被称为「诗佛」,诗中有画。" },
  { field: "诗词", title: "愿君多采撷,此物最相思", body: "出自唐代王维《相思》。希望你多采些红豆,这种东西最能寄托相思。红豆又叫相思子,诗人借它表达对朋友的深切思念。", fact: "首句「红豆生南国」;撷(xié)是采摘。" },
  { field: "诗词", title: "春眠不觉晓,处处闻啼鸟", body: "出自唐代孟浩然《春晓》。春夜睡得香甜,不知不觉天就亮了,到处都能听到鸟叫。下句是「夜来风雨声,花落知多少」,短短四句写出了惜春之情。", fact: "作者孟浩然,与王维并称「王孟」。" },
  { field: "诗词", title: "洛阳亲友如相问,一片冰心在玉壶", body: "出自唐代王昌龄《芙蓉楼送辛渐》。如果洛阳的亲友问起我,就说我的心依然像玉壶里的冰一样纯洁。王昌龄被贬后送别友人,借此表明自己清白坚守。", fact: "「冰心玉壶」比喻品格高洁。" },
  { field: "诗词", title: "但使龙城飞将在,不教胡马度阴山", body: "出自唐代王昌龄《出塞》。只要有像飞将军李广那样的名将在,就不会让敌人的骑兵越过阴山。首句「秦时明月汉时关」也很有名。", fact: "飞将一般指汉代名将李广。" },
  { field: "诗词", title: "黄沙百战穿金甲,不破楼兰终不还", body: "出自唐代王昌龄《从军行·其四》。在黄沙中身经百战,铠甲都磨穿了,不打败敌人决不回乡。表现了戍边将士的坚定意志。", fact: "楼兰是西域古国,这里泛指敌人。" },
  { field: "诗词", title: "忽如一夜春风来,千树万树梨花开", body: "出自唐代岑参《白雪歌送武判官归京》。好像一夜之间春风吹来,千万棵树上的梨花都开了。这里的「梨花」其实是指树枝上的积雪,是写雪的千古名句。", fact: "「梨花」比喻的是雪,不是真的梨花。" },
  { field: "诗词", title: "莫愁前路无知己,天下谁人不识君", body: "出自唐代高适《别董大》。不要担心前方没有知心朋友,天下谁不认识你呢?送别友人时不说伤感话,而是鼓励对方,写得豪迈有力。", fact: "作者高适,边塞诗人,与岑参并称「高岑」。" },
  { field: "诗词", title: "前不见古人,后不见来者", body: "出自唐代陈子昂《登幽州台歌》。往前看不见古代的贤君,往后也看不见未来的明主。陈子昂怀才不遇,登台远眺,写出了孤独苍凉的心情。", fact: "下句「念天地之悠悠,独怆然而涕下」。" },
  { field: "诗词", title: "野火烧不尽,春风吹又生", body: "出自唐代白居易《赋得古原草送别》。野火也烧不尽原上的草,春风一吹它又长出来。这是白居易十六岁时的作品,常用来比喻顽强的生命力。", fact: "首句「离离原上草,一岁一枯荣」。" },
  { field: "诗词", title: "同是天涯沦落人,相逢何必曾相识", body: "出自唐代白居易《琵琶行》。我们都是流落天涯的不幸人,今天相遇何必在意以前是否认识。白居易被贬江州时遇到一位琵琶女,同病相怜写下长诗。", fact: "同诗名句「犹抱琵琶半遮面」。" },
  { field: "诗词", title: "日出江花红胜火,春来江水绿如蓝", body: "出自唐代白居易《忆江南》。太阳出来,江边的花红得胜过火焰;春天到了,江水绿得像蓝草一样。白居易回忆在杭州、苏州做官时见过的江南美景。", fact: "首句「江南好,风景旧曾谙」。" },
  { field: "诗词", title: "人间四月芳菲尽,山寺桃花始盛开", body: "出自唐代白居易《大林寺桃花》。四月里人间的花都谢了,山上寺庙里的桃花才刚刚盛开。这首诗也写出了一个地理常识:山地海拔高、气温低,花期更晚。", fact: "蕴含海拔越高气温越低的地理知识。" },
  { field: "诗词", title: "谁知盘中餐,粒粒皆辛苦", body: "出自唐代李绅《悯农·其二》。谁知道盘中的饭食,每一粒都饱含农民的辛苦。前两句是「锄禾日当午,汗滴禾下土」,常用来教育人珍惜粮食。", fact: "作者李绅;前句「锄禾日当午」。" },
  { field: "诗词", title: "春蚕到死丝方尽,蜡炬成灰泪始干", body: "出自唐代李商隐《无题》。春蚕到死才吐完丝,蜡烛烧成灰才流干蜡泪。原写爱情至死不渝,现在常被用来赞美教师等人的无私奉献。", fact: "首句「相见时难别亦难」。" },
  { field: "诗词", title: "夕阳无限好,只是近黄昏", body: "出自唐代李商隐《登乐游原》。夕阳的景色无比美好,只可惜已经接近黄昏了。诗人借景抒发对美好事物将要消逝的惋惜。", fact: "乐游原在长安城南。" },
  { field: "诗词", title: "身无彩凤双飞翼,心有灵犀一点通", body: "出自唐代李商隐《无题》。身上没有彩凤那样的双翅,不能飞到你身边;但两颗心像灵犀一样相通。成语「心有灵犀」就出自这里。", fact: "首句「昨夜星辰昨夜风」。" },
  { field: "诗词", title: "停车坐爱枫林晚,霜叶红于二月花", body: "出自唐代杜牧《山行》。停下车是因为喜爱傍晚的枫林,经霜的枫叶比二月的春花还红。诗人一反悲秋传统,写出了秋天的绚丽。", fact: "「坐」是因为的意思,不是坐下。" },
  { field: "诗词", title: "清明时节雨纷纷,路上行人欲断魂", body: "相传为唐代杜牧所作的《清明》。清明节细雨纷纷,路上的行人心情愁苦。下句是「借问酒家何处有?牧童遥指杏花村」。这首诗是否出自杜牧,学界有争议。", fact: "作者相传是杜牧,署名存在争议。" },
  { field: "诗词", title: "商女不知亡国恨,隔江犹唱后庭花", body: "出自唐代杜牧《泊秦淮》。卖唱的歌女不懂亡国之恨,隔着江水还在唱《玉树后庭花》。《后庭花》被视为南朝陈的亡国之音,诗人借此讽刺晚唐统治者沉溺享乐。", fact: "首句「烟笼寒水月笼沙」。" },
  { field: "诗词", title: "沉舟侧畔千帆过,病树前头万木春", body: "出自唐代刘禹锡《酬乐天扬州初逢席上见赠》。沉船旁边有千帆驶过,病树前面万木争春。刘禹锡被贬二十多年后与白居易相逢,用这两句表达新事物必将取代旧事物的乐观精神。", fact: "常用来说明新事物必然取代旧事物。" },
  { field: "诗词", title: "旧时王谢堂前燕,飞入寻常百姓家", body: "出自唐代刘禹锡《乌衣巷》。从前在王导、谢安等豪门大族厅堂里筑巢的燕子,如今飞进了普通百姓家。借燕子写出世事变迁、繁华不再。", fact: "王谢指东晋王导、谢安两大家族。" },
  { field: "诗词", title: "千淘万漉虽辛苦,吹尽狂沙始到金", body: "出自唐代刘禹锡《浪淘沙》。千万遍地淘洗过滤虽然辛苦,但吹尽狂沙,才能得到黄金。比喻经历艰难磨炼,才能显出真正的价值。", fact: "漉(lù)是过滤。" },
  { field: "诗词", title: "千山鸟飞绝,万径人踪灭", body: "出自唐代柳宗元《江雪》。群山里不见飞鸟,所有小路上都没有人的踪迹。后两句写一位老翁独自在寒江钓雪,是柳宗元被贬永州后孤独心境的写照。", fact: "后句「孤舟蓑笠翁,独钓寒江雪」。" },
  { field: "诗词", title: "谁言寸草心,报得三春晖", body: "出自唐代孟郊《游子吟》。谁能说小草的一点心意,能报答春天阳光般的恩情?诗人以小草比子女,以春晖比母爱,表达对母亲的感恩。", fact: "首句「慈母手中线,游子身上衣」。" },
  { field: "诗词", title: "曾经沧海难为水,除却巫山不是云", body: "出自唐代元稹《离思·其四》。见过沧海的人,别处的水就难以称为水了;看过巫山的云,别处的云都不算云。诗人借此表达对亡妻深切而专一的怀念。", fact: "作者元稹,写给亡妻韦丛。" },
  { field: "诗词", title: "月落乌啼霜满天,江枫渔火对愁眠", body: "出自唐代张继《枫桥夜泊》。月亮落下,乌鸦啼叫,寒气满天;江边枫树和渔船灯火,陪着愁绪难眠的旅人。苏州寒山寺因此诗闻名天下。", fact: "后句「姑苏城外寒山寺,夜半钟声到客船」。" },
  { field: "诗词", title: "碧玉妆成一树高,万条垂下绿丝绦", body: "出自唐代贺知章《咏柳》。高高的柳树像用碧玉装扮而成,千万条柳枝像垂下的绿色丝带。末句「二月春风似剪刀」更是巧妙的比喻。", fact: "后句「不知细叶谁裁出,二月春风似剪刀」。" },
  { field: "诗词", title: "少小离家老大回,乡音无改鬓毛衰", body: "出自唐代贺知章《回乡偶书》。年轻时离开家乡,老了才回来,口音没变,鬓发却已稀疏斑白。后两句写儿童不认识他,笑问客从何处来。", fact: "衰在这里读 cuī,意为稀疏。" },
  { field: "诗词", title: "海上生明月,天涯共此时", body: "出自唐代张九龄《望月怀远》。一轮明月从海上升起,远在天涯的人也在同一时刻看着它。诗人借月寄托对远方亲人的思念。", fact: "作者张九龄,唐代名相。" },
  { field: "诗词", title: "春江潮水连海平,海上明月共潮生", body: "出自唐代张若虚《春江花月夜》。春天的江潮水势浩荡,与大海连成一片;一轮明月随着潮水升起。这首诗被闻一多称为「诗中的诗,顶峰上的顶峰」。", fact: "有「孤篇横绝全唐」的说法。" },
  { field: "诗词", title: "晴川历历汉阳树,芳草萋萋鹦鹉洲", body: "出自唐代崔颢《黄鹤楼》。晴朗的江面上,汉阳的树木清晰可见;鹦鹉洲上芳草茂盛。相传李白登黄鹤楼见此诗,感叹「眼前有景道不得,崔颢题诗在上头」。", fact: "传说李白看了此诗后搁笔。" },

  // ========== 诗词每日一句 · 五代宋词宋诗(30) ==========
  { field: "诗词", title: "问君能有几多愁?恰似一江春水向东流", body: "出自五代南唐后主李煜《虞美人》。问我心里有多少愁?就像一江春水滔滔东流。李煜亡国后被囚,用江水比喻愁绪的无穷无尽。", fact: "首句「春花秋月何时了」;作者是亡国之君李煜。" },
  { field: "诗词", title: "但愿人长久,千里共婵娟", body: "出自北宋苏轼《水调歌头·明月几时有》。只希望亲人平安长久,即使相隔千里也能共赏美丽的月亮。这首词写于中秋夜,怀念弟弟苏辙。婵娟指月亮。", fact: "写给弟弟苏辙(子由);婵娟指月亮。" },
  { field: "诗词", title: "大江东去,浪淘尽,千古风流人物", body: "出自北宋苏轼《念奴娇·赤壁怀古》。长江向东奔流,浪花淘尽了千古英雄人物。苏轼被贬黄州时游赤壁,怀念周瑜,是豪放词的代表作。", fact: "苏轼是豪放派代表;怀念的是周瑜。" },
  { field: "诗词", title: "竹杖芒鞋轻胜马,谁怕?一蓑烟雨任平生", body: "出自北宋苏轼《定风波》。拄竹杖、穿草鞋,比骑马还轻快,怕什么?披着蓑衣在风雨里过一生也坦然。苏轼在黄州途中遇雨,同行都狼狈,他却从容吟啸。", fact: "前句「莫听穿林打叶声」;体现豁达人生观。" },
  { field: "诗词", title: "不识庐山真面目,只缘身在此山中", body: "出自北宋苏轼《题西林壁》。之所以看不清庐山的真实面貌,是因为自己身处山中。比喻身处局中往往看不清全局,要跳出来看问题。", fact: "前句「横看成岭侧成峰」;相关成语「当局者迷」。" },
  { field: "诗词", title: "欲把西湖比西子,淡妆浓抹总相宜", body: "出自北宋苏轼《饮湖上初晴后雨》。想把西湖比作美女西施,无论淡妆还是浓妆都很美。从此西湖也被称为「西子湖」。", fact: "西子指西施;西湖因此称「西子湖」。" },
  { field: "诗词", title: "竹外桃花三两枝,春江水暖鸭先知", body: "出自北宋苏轼《惠崇春江晚景》。竹林外桃花开了两三枝,春天江水变暖,鸭子最先知道。这是一首题画诗,把画中的春意写得生动可感。", fact: "是苏轼为僧人惠崇的画题写的诗。" },
  { field: "诗词", title: "一年好景君须记,最是橙黄橘绿时", body: "出自北宋苏轼《赠刘景文》。一年中最好的景色你一定要记住,就是橙子金黄、橘子青绿的初冬时节。苏轼借此勉励好友不要因年老而消沉。", fact: "写给好友刘景文,鼓励对方。" },
  { field: "诗词", title: "人生如逆旅,我亦是行人", body: "出自北宋苏轼《临江仙·送钱穆父》。人生就像住旅店,我也是匆匆过客。送别友人时,苏轼以旷达的态度看待聚散离别。逆旅指旅店。", fact: "逆旅是旅店,不是逆境。" },
  { field: "诗词", title: "生当作人杰,死亦为鬼雄", body: "出自南宋李清照《夏日绝句》。活着要做人中豪杰,死了也要做鬼中英雄。下句「至今思项羽,不肯过江东」,借项羽讽刺南宋朝廷苟且偷安。", fact: "李清照的诗少见地豪迈;下句提到项羽。" },
  { field: "诗词", title: "知否,知否?应是绿肥红瘦", body: "出自宋代李清照《如梦令》。你知道吗?应该是绿叶繁茂、红花凋零了。一夜风雨后,词人追问海棠,用「绿肥红瘦」写出惜春之情。", fact: "首句「昨夜雨疏风骤」;李清照是婉约派代表。" },
  { field: "诗词", title: "莫道不消魂,帘卷西风,人比黄花瘦", body: "出自宋代李清照《醉花阴》。不要说这情景不让人伤神,西风卷起帘子,帘内的人比菊花还要消瘦。这首词写重阳节思念丈夫赵明诚。", fact: "黄花指菊花;写重阳思念丈夫。" },
  { field: "诗词", title: "醉里挑灯看剑,梦回吹角连营", body: "出自南宋辛弃疾《破阵子·为陈同甫赋壮词以寄之》。喝醉了挑亮灯火端详宝剑,梦里回到号角相连的军营。辛弃疾一心抗金收复失地,却长期被闲置。", fact: "结尾「可怜白发生」;辛弃疾是豪放派代表。" },
  { field: "诗词", title: "众里寻他千百度,蓦然回首,那人却在,灯火阑珊处", body: "出自南宋辛弃疾《青玉案·元夕》。在人群中找了她千百遍,猛然回头,她却在灯火稀落的地方。王国维把这句比作治学的第三境界。", fact: "元夕是元宵节;王国维「三境界」之第三。" },
  { field: "诗词", title: "稻花香里说丰年,听取蛙声一片", body: "出自南宋辛弃疾《西江月·夜行黄沙道中》。在稻花香里,人们谈论着丰收的年景,耳边传来一片蛙声。写出了夏夜农村的宁静美好。", fact: "首句「明月别枝惊鹊」。" },
  { field: "诗词", title: "山重水复疑无路,柳暗花明又一村", body: "出自南宋陆游《游山西村》。山峦重叠、水流曲折,以为前面没路了,忽然柳色深绿、花色明亮,又出现一个村庄。常用来比喻困境中出现转机。", fact: "成语「柳暗花明」出自这里。" },
  { field: "诗词", title: "纸上得来终觉浅,绝知此事要躬行", body: "出自南宋陆游《冬夜读书示子聿》。从书本上得来的知识终究浅显,要真正理解,必须亲自实践。这是陆游写给小儿子子聿的。", fact: "强调实践;躬行是亲身去做。" },
  { field: "诗词", title: "王师北定中原日,家祭无忘告乃翁", body: "出自南宋陆游《示儿》。等到朝廷军队收复中原的那一天,家里祭祀时别忘了告诉我。这是陆游临终绝笔,到死仍牵挂国家统一。", fact: "陆游临终绝笔;乃翁指你的父亲(陆游自称)。" },
  { field: "诗词", title: "莫等闲,白了少年头,空悲切", body: "出自相传为南宋岳飞所作的《满江红》。不要虚度光阴,等到少年黑发变白时,只能白白悲伤。词中「三十功名尘与土,八千里路云和月」也很有名。", fact: "首句「怒发冲冠」;作者一般认为是岳飞,学界有争议。" },
  { field: "诗词", title: "先天下之忧而忧,后天下之乐而乐", body: "出自北宋范仲淹《岳阳楼记》。在天下人忧虑之前先忧虑,在天下人快乐之后才快乐。这句表达了以天下为己任的政治抱负,是古代士大夫精神的代表。", fact: "作者范仲淹;同文有「不以物喜,不以己悲」。" },
  { field: "诗词", title: "衣带渐宽终不悔,为伊消得人憔悴", body: "出自北宋柳永《蝶恋花》。衣带一天天变宽也不后悔,为了她甘愿消瘦憔悴。原写相思,王国维用它比喻治学的第二境界:执着追求。", fact: "王国维「三境界」之第二。" },
  { field: "诗词", title: "无可奈何花落去,似曾相识燕归来", body: "出自北宋晏殊《浣溪沙》。花落去让人无可奈何,燕子归来又好像曾经相识。这两句对仗自然,写出了时光流逝和美好事物的循环。", fact: "成语「似曾相识」出自这里。" },
  { field: "诗词", title: "春风又绿江南岸,明月何时照我还", body: "出自北宋王安石《泊船瓜洲》。春风又吹绿了江南的岸边,明月什么时候才能照着我回家?相传「绿」字经过多次修改才定下,是炼字的经典例子。", fact: "「绿」字用作动词,是炼字典范。" },
  { field: "诗词", title: "不畏浮云遮望眼,自缘身在最高层", body: "出自北宋王安石《登飞来峰》。不怕浮云遮住远望的视线,因为我站在最高处。王安石年轻时所作,表现出高瞻远瞩、不畏困难的政治抱负。", fact: "和「会当凌绝顶」意境相近。" },
  { field: "诗词", title: "墙角数枝梅,凌寒独自开", body: "出自北宋王安石《梅花》。墙角有几枝梅花,冒着严寒独自开放。下句「遥知不是雪,为有暗香来」。诗人借梅花表达坚守品格。", fact: "后句「遥知不是雪,为有暗香来」。" },
  { field: "诗词", title: "问渠那得清如许?为有源头活水来", body: "出自南宋朱熹《观书有感》。问池塘为什么这样清澈?因为有源头活水不断流进来。比喻只有不断学习新知识,思想才能保持活跃。", fact: "渠指池塘(它);那得即怎么会。" },
  { field: "诗词", title: "接天莲叶无穷碧,映日荷花别样红", body: "出自南宋杨万里《晓出净慈寺送林子方》。莲叶一望无际,好像与天相接;阳光下的荷花显得格外鲜红。写的是六月西湖的美景。", fact: "前句「毕竟西湖六月中」。" },
  { field: "诗词", title: "小荷才露尖尖角,早有蜻蜓立上头", body: "出自南宋杨万里《小池》。小荷叶刚刚露出尖尖的角,就有蜻蜓站在上面了。杨万里善于捕捉自然中的小细节,写得清新活泼。", fact: "杨万里诗风被称为「诚斋体」。" },
  { field: "诗词", title: "春色满园关不住,一枝红杏出墙来", body: "出自南宋叶绍翁《游园不值》。满园春色是关不住的,一枝红杏伸出了墙外。诗人去朋友家赏花没进去门,却从一枝红杏感受到了园中春意。", fact: "「不值」是没遇到主人。" },
  { field: "诗词", title: "两情若是久长时,又岂在朝朝暮暮", body: "出自北宋秦观《鹊桥仙》。如果两人的感情长久坚贞,又何必在乎每天朝夕相守。词借牛郎织女七夕相会,表达对真挚爱情的看法。", fact: "写的是七夕牛郎织女。" },

  // ========== 诗词每日一句 · 宋末元明清(7) ==========
  { field: "诗词", title: "人生自古谁无死,留取丹心照汗青", body: "出自南宋文天祥《过零丁洋》。自古以来谁都难免一死,我要留下一颗赤诚的心,永照史册。文天祥被元军俘虏后拒绝劝降,以此诗明志。汗青指史册。", fact: "汗青指史册;同诗「山河破碎风飘絮」。" },
  { field: "诗词", title: "枯藤老树昏鸦,小桥流水人家", body: "出自元代马致远《天净沙·秋思》。枯藤缠着老树,黄昏的乌鸦归巢;小桥下流水潺潺,旁边是人家。全曲用景物堆叠写出游子的思乡之苦。", fact: "被称为「秋思之祖」;结句「断肠人在天涯」。" },
  { field: "诗词", title: "粉骨碎身浑不怕,要留清白在人间", body: "出自明代于谦《石灰吟》。即使粉身碎骨也完全不怕,只要把清白留在人间。诗人借石灰被烧炼的过程,表达自己坚贞清廉的品格。", fact: "作者于谦;浑是全然、完全。" },
  { field: "诗词", title: "千磨万击还坚劲,任尔东西南北风", body: "出自清代郑燮(郑板桥)《竹石》。经历千万次磨难打击,竹子依旧坚韧挺拔,任凭四面八方的风吹。借竹子比喻人坚定不屈的品格。", fact: "首句「咬定青山不放松」;郑燮以画竹著名。" },
  { field: "诗词", title: "落红不是无情物,化作春泥更护花", body: "出自清代龚自珍《己亥杂诗》。落花并不是无情的,化成春泥还能滋养花木。诗人辞官离京,表示虽离开官场仍愿为国家出力,现在也常用来赞美奉献精神。", fact: "作者龚自珍;落红指落花。" },
  { field: "诗词", title: "江山代有才人出,各领风骚数百年", body: "出自清代赵翼《论诗》。每个时代都有杰出人才出现,各自引领文坛几百年。赵翼认为诗歌应随时代创新,不必一味推崇古人。", fact: "风骚源自《诗经·国风》和《离骚》,代指文学。" },
  { field: "诗词", title: "不要人夸好颜色,只留清气满乾坤", body: "出自元代王冕《墨梅》。不需要别人夸它颜色好看,只要把清香之气留在天地之间。王冕擅长画梅,借墨梅表达不慕名利、坚守高洁的志向。", fact: "作者王冕,元代画家、诗人。" }
];

